INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594530486', 'Recarb Energy Gel Squeeze - 600g Água de Coco - Reidrat', 'O Recarb Energy Gel Reidrat Nutrition é um repositor que fornece energia rápida para os praticantes de atividades físicas prolongadas, no qual a combinação de carboidratos (Maltodextrina, Frutose, Palatinose e Waxy Maize), proteína (Proteína Concentrada de Arroz), e vitaminas (A, B, C, D e E) favorecem uma melhora considerável no rendimento e no desempenho do atleta. Repor energia e eletrólitos é primordial para preservar a massa muscular, reduzir os desgastes físicos e impedir que ocorra a desidratação. Como Tomar Consumir 1 dose 30 minutos antes e a cada 30 minutos de exercício. Tome sempre um copo de água após cada dose de energy gel, ou conforme indicação do seu médico ou nutricionista. Ingredientes Maltodextrina, Água Filtrada, Frutose, Proteína Concentrada de Arroz, Isomaltulose (Palatinose), Waxy Maize (Amido de Milho Ceroso), Citrato de Sódio (Regulador de Acidez), Fosfato de Potássio Monobásico, Cloreto de Sódio, Ácido Cítrico (Acidulante), Vitaminas A, C, D, E, e Vitamina do Complexo B (B2, B3, B6 e B12), Aromatizante Idêntico ao Natural e Conservantes: Sorbato de Potássio e Benzoato de Sódio. NÃO CONTÉM GLÚTEN. DIABÉTICOS: CONTÉM GLICOSE E FRUTOSE. ...', 63.36, 63.36, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-824jh-mfrh1wf711c8f8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976704374%2F22594530486', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
