INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21999705537', 'Anodo De Eixo 1 1/4 Polegada', 'Anodo de Eixo 1 1/4 Polegada O anodo de zinco tem a função de proteger o barco da corrosão, causada pelo contato com a água salgada. Sendo assim, o anodo é acoplado ao barco, em lugares como rabeta, leme e eixo e devem ser avaliados e trocados periodicamente, a troca é fundamental para que não haja um prejuízo, como uma hélice ou casco enferrujados. O anodo de zinco é o primeiro a ser corroído, protegendo o restante, por isso também é conhecido como "anodo de sacrifício". Certifique-se de que os anodos do seu barco tenham conexões físicas e elétricas adequadas. Um ânodo com uma conexão elétrica ruim não pode fornecer proteção contra corrosão. Limpe a área onde os anodos serão montados, lixando ou escovando levemente. Não pinte seus anodos. Especificações Técnicas Modelo: ZM125Zn Composição: Liga de Zinco Diâmetro Eixo: 1 1/4" Largura: 62mm Altura: 60mm Peso: 0.55kg', 117.22, 117.22, NULL, 'Spare Parts and Accessories for Vehicles > Heavy Duty and Boats > Spare Parts for Boats', 'https://cf.shopee.com.br/file/sg-11134201-7rfg4-m9g19ydnw33bf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1511959705%2F21999705537', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
