INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58256307104', 'Fritadeira Airfryer Série 1000 XL 6,2L 1700W Grelha Removível Philips Walita', 'Prepare suas refeições de forma saudável e rapidamente com a Fritadeira Airfryer Philips Walita Série 1000 XL. Garantindo alimentos crocantes por fora, macios por dentro, com muito mais sabor e praticidade no preparo. Com capacidade total de 6,2L (suficiente para até 1,2kg de alimentos), pensada para famílias de até 6 pessoas. Sua potência de 1700W aliada à exclusiva Tecnologia Rápida proporciona circulação de ar por todos os lados, garantindo cozimento uniforme e rápido. Características: Marca: Philips Walita Modelo: Série 1000 XL Lâmpada piloto: não Desligamento automático: sim Anti-aquecimento externo: sim Cesto removível: Sim Mantém aquecido: Não Tipo: Sem óleo* Quantidade de cestos: 1 Temperatura máxima (°C): 200° C Consumo de energia (kW/h): 1,7 kWh Capacidade (litros): 6,2 L Potência (W): 1700W Tensão/Voltagem: 220V,110V Tipo de Tomada: 20A (4.8mm),10A (4mm) Tipo de Plugue: 3 Pinos Conteúdo da Embalagem: 01 Fritadeira Air Fryer Série 1000 XL 6,2L 1700W Grelha Removível Philips Walita 01 Manual de Instruções 01 Certificado de Garantia Garantia: 24 Meses Atenção: Antes do primeiro uso, retire os materiais de embalagem Limpe todas as peças conforme o manual Utilize o aparelho em superfície estável e resistente ao calor Evite encostar em paredes ou objetos durante o uso Não utilize produtos abrasivos na limpeza Não operar sob móveis ou armários Entrega do Produto: Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto', 452.17, 443.12, NULL, 'Home Appliances > Kitchen Appliances > Air Fryers', 'https://cf.shopee.com.br/file/sg-11134201-82613-mlgh4des0wea66', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2