INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58211630764', 'Aspirador De Pó Vertical Wap Power Speed Max 1600w 3', 'O Aspirador de Pó Vertical WAP Power Speed Max 1600W 3 em 1 oferece praticidade, potência e versatilidade para facilitar a limpeza do dia a dia. Com alto poder de sucção e Tecnologia Cyclone, proporciona limpeza eficiente enquanto compacta a sujeira e mantém o fluxo de ar desobstruído. Seu sistema 360 graus permite alcançar áreas de difícil acesso com mais facilidade, enquanto a função 3 em 1 possibilita o uso como aspirador vertical, portátil ou com acessórios para diferentes superfícies. O filtro HEPA contribui para um ambiente mais saudável ao eliminar impurezas e alérgenos do ar. Características: Fabricante: Wap Potência: 1600 W Tecnologia Cyclone: Sim Sistema 360 graus: Sim Função 3 em 1: Sim Filtro HEPA: Sim Filtro HEPA filtra até 99,9 Porcentagem das impurezas do ar Capacidade do coletor: 1,3 L Alcance: Até 5 metros Tensão/Voltagem: 220V e 110V Uso indicado: Limpeza residencial e comercial Conteúdo da Embalagem: 01 Aspirador Vertical WAP Power Speed Max 01 Bico canto 01 Bico escova 01 Adaptador para bico escova 01 Filtro HEPA 01 Suporte para acessórios 01 Haste removível Garantia: 12 Meses. Observações: Dicas de Utilização: Esvaziar o reservatório após o uso. Limpar o filtro HEPA conforme instruções do fabricante. Não aspirar líquidos. Armazenar em local seco. Utilizar os bicos adequados para cada superfície. Entrega do Produto: Todas as instruções, manuais e peças necessárias para a montagem são fornecidas junto com o produto.', 256.47, 229.0, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/br-11134207-820lt-motq1rtmark5bb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1083800536%2F58211