INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21671500819', 'Pá Higiênica Para Catar Cocô Pet Areia De Gato PVC Animal Estimação Cores Sortidas', 'COMERCIAL VIPASA DISTRIBUIDORA. Pá Higiênica Para Catar Cocô Pet Areia De Gato PVC Animal Estimação Cores Sortidas Pá Higiênica Pet P/ Areia De Gato PVC A pá higiênica para gatos, também chamada de pá coletora ou simplesmente pazinha para gato, é uma ferramenta importante para manter a higiene do seu bichinho. Ela facilita a limpeza da caixinha de areia, evita contaminações e ainda ajuda a economizar com a areia higiênica. Cores SORTIDAS COMERCIAL VIPASA DISTRIBUIDORA.', 8.75, 8.75, NULL, 'Pets > Pet Accessories > Others', 'https://cf.shopee.com.br/file/sg-11134201-23010-d16eb2g4ugmv9e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F408128510%2F21671500819', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209716113', 'Cenoura Ifrutus', 'A Cenoura Ifrutus 500g é fresca, crocante e cheia de sabor, perfeita para trazer mais saúde e cor às suas refeições. Rica em nutrientes e versátil, pode ser usada em saladas, sucos, sopas, bolos, refogados e muito mais. Embalada com qualidade, garante praticidade e frescor para o seu dia a dia.', 7.79, 7.79, NULL, 'Food & Beverages > Fresh & Frozen Food > Others', 'https://cf.shopee.com.br/file/sg-11134201-82625-mke8y21swhdxd7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554886%2F58209716113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209750593', 'FRUIT. MAST. MELANCIA', '"A Fruittella Melancia é feita com suco da fruta, trazendo o delicioso sabor natural da melancia! A textura macia e fácil de mastigar faz de cada bala uma experiência única e deliciosa. O display contém 16 unidades, totalizando 640 g, e a embalagem prática é perfeita para ter sempre à mão, seja na mochila ou no bolso. Sabor melancia delicioso. Feita com suco da fruta, oferece o sabor doce e natural da melancia em cada bala, proporcionando uma experiência de sabor irresistível. Textura macia. Com uma textura suave e fácil de mastigar, cada bala oferece uma experiência de sabor duradoura e agradável. Embalagem prática. Ideal para carregar no bolso ou na mochila, garantindo que você tenha sempre à mão balas deliciosas para compartilhar com toda a família. Quantidade ideal. 16 unidades, porção na medida certa para aproveitar ao longo do dia, com um toque macio e gosto marcante. Sinônimo de qualidade. Fruittella é reconhecida por seus doces feitos com cuidado, combinando ingredientes de qualidade e sabores únicos que encantam gerações. Informações Técnicas: - Quantidade: 16 unidades (total 640 g) - Sabor: Melancia - Tipo: Bala mastigável - Linha: Fruittella"', 56.07, 56.07, NULL, 'Food & Beverages > Snacks > Sweets & Candy', 'https://cf.shopee.com.br/file/sg-11134201-820o6-mnlduz461ddv44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1744074434%2F58209750593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22998710082', 'Placa Mãe Asus TUF Gaming A520M-PLUS WIFI, Chipset A520, AMD AM4, mATX, DDR4, 90MB17F0-M0EAY0', 'Placa Mãe Asus TUF Gaming A520M-PLUS WIFI, Chipset A520, AMD AM4, mATX, DDR4, 90MB17F0-M0EAY0 POR QUE ESTA PLACA-MÃE É IDEAL PARA O SEU SETUP? A ASUS TUF GAMING A520M-PLUS WIFI combina durabilidade militar da linha TUF com conectividade moderna, incluindo suporte a Ryzen 5000 e possibilidade de Wi-Fi via slot dedicado. É perfeita para quem busca estabilidade, resistência e ótimo desempenho em setups gamers e profissionais. --------------------------------- BENEFÍCIOS PARA O CLIENTE • Suporte aos processadores AMD Ryzen 3000, 4000G e 5000 • Até 128GB de memória DDR4 com altas frequências (OC) • Construção TUF com maior durabilidade e proteção reforçada • Slot M.2 para SSDs NVMe de alta velocidade • Preparada para expansão com conectividade moderna e versátil --------------------------------- INFORMAÇÕES ESSENCIAIS • Marca: ASUS • Modelo: TUF GAMING A520M-PLUS WIFI • Chipset: AMD A520 • Dimensões: 24.4 cm x 24.4 cm (mATX) --------------------------------- ESPECIFICAÇÕES TÉCNICAS • Marca: ASUS • Modelo: TUF GAMING A520M-PLUS WIFI • Soquete: AM4 • Chipset: AMD A520 • Formato: mATX Processadores Compatíveis: • AMD Ryzen 5000 Series • AMD Ryzen 4000 G-Series • AMD Ryzen 3000 Series Memória: • 4x DIMM, até 128GB DDR4 • Frequências: até 4800MHz (OC) • Arquitetura: Dual Channel • Suporte ECC: Dependente da CPU Gráficos: • 1x VGA (D-Sub) • 1x DVI-D • 1x HDMI 2.1 (4K@60Hz) Slots de Expansão: • 1x PCIe 3.0 x16 • 2x PCIe 3.0 x1 Armazenamento: • 1x M.2 (PCIe 3.0 x4 / SATA – até 22110) • 4x SATA 6Gb/s • Suporte RAID 0, 1, 10 Rede: • Realtek L8200A Gigabit Ethernet • TUF LANGuard Rede Sem Fio: • Slot M.2 Key E para módulo Wi-Fi USB: Traseiras: • 1x USB 3.2 Gen 2 • 4x USB 3.2 Gen 1 • 2x USB 2.0 Frontais: • 2x USB 3.2 Gen 1 • 3x USB 2.0 Portas Traseiras (I/O): • 1x PS/2 • 1x DVI-D • 1x VGA • 1x HDMI • 1x LAN (RJ45) • 2x USB 2.0 • 4x USB 3.0 • 1x USB 3.2 Gen 2 • 3x conectores de áudio BIOS e Sistema: • BIOS: 256 Mb Flash ROM, UEFI AMI BIOS • Gerenciamento: WOL, PXE • Sistema Operacional: Windows 10 64-bit --------------------------------- TERABYTE SHOP OFICIAL: 19 ANOS DE LEGADO TECH A loja preferida de Gamers e Entusiastas é referência em qualidade e excelência. Montamos seu setup dos sonhos com produtos de alta performance e suporte excepcional. Sua melhor experiência em tecnologia começa aqui!', 1799.99, 832.12, NULL, 'Computers & Accessories > Desktop & Laptop Components > Motherboards', 'https://cf.shopee.com.br/file/sg-11134201-824h7-mea30c40ugoxbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1552226494%2F22998710082', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
