INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58251735456', 'Jurassic World Dinosaur Rebirth Wild Roar Spiclypeus Mattel Jgb89', 'Entre em ação com este Wild Roar Spiclypeus inspirado em Jurassic World Rebirth. Com o Total Attack, as crianças podem mover facilmente a cauda para cima e para baixo neste brinquedo de dinossauro para ativar um emocionante ataque de cabeçada para cima e para baixo, acompanhado de um rugido feroz, depois girar a cauda para mudar a direção para os lados! Essa figura de mais de 28 cm de comprimento, inspirada no filme, possui articulações móveis, pronta para emocionantes batalhas ou exibições dramáticas. Escaneie o Código de Rastreamento no pé do dinossauro no aplicativo gratuito Jurassic World Play com um dispositivo inteligente compatível Android ou iOS, não incluso, para desbloquear uma versão digital do dinossauro e jogar o divertido jogo feroz para correr com vários veículos em terra, ar e mar. O Spiclypeus é adequado para fãs de dinossauros a partir de 4 anos. Cores e decorações podem variar. Ataque e ruge! Este brinquedo Wild Roar Spiclypeus inspirado em Jurassic World Rebirth tem um ataque agressivo de cabeçada que pode mudar de direção e um rugido feroz para brincadeiras de batalha de dinossauros! Ataque Total! As crianças dominarão facilmente ambos os movimentos movendo a cauda para cima e para baixo para ativar o ataque específico da espécie com um rugido feroz, e depois torcendo a cauda para mudar a direção do ataque! Cheio de emoção! Esta figura do Spiclypeus tem mais de 28 cm de comprimento e 14,7 cm de altura e possui articulações móveis, pronta para movimentos de ação ou poses realistas. Muito divertido! Este Wild Roar Spiclypeus é uma adição emocionante para qualquer coleção de dinossauros para fãs a partir de 4 anos. Escaneie e colecione! Escaneie o código no pé do dinossauro no aplicativo gratuito Jurassic World Play com um dispositivo inteligente compatível não incluso para atividades de AR e criar uma coleção digital de dinossauros! Ride N Rampage Colossal Chase! Neste jogo de aplicativo atualizado, corra com vários veículos em terra, ar e mar e jogue um emocionante jogo de tiro que extrai DNA dos dinossauros! Especificações: Dimensões do produto: 7,62 x 26,67 x 15,24 centímetros, Peso do item: 459 gramas, Número do modelo: JGB89, Idade recomendada pelo fabricante: 4 anos ou mais, Pilhas: 3 pilhas LR44 necessárias (incluídas), Fabricante: Mattel Inc Cor:Multicolorido', 299.9, 184.0, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mi2m2xfhtpmu7b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F58251735456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '12898467344', 'Boneco Peppa com Atividades Peppa Pig - Elka', 'Boneco Peppa com Atividades Peppa Pig - Elka O Boneco Articulado - Peppa Pig - Peppa de Atividades da Elka mede aproximadamente 24 centímetros de altura, acompanha uma bolinha que gira na barriguinha, e seus brinquedos preferidos dele na mão. Os pequenos vão passar horas se divertindo com esse novo amiguinho. Idade recomendada: a partir de 2 anos de idade. Selo INMETRO: CE-BRI/IQB 2276 - NM 300/2002 - OCP 0006.', 118.99, 118.99, NULL, 'Hobbies & Collections > Collectible Items > Action Figurines', 'https://cf.shopee.com.br/file/sg-11134201-7qve5-lezrps68qvcf75', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F952529254%2F12898467344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20498318591', 'Beyblade X Sword Dran 3-60f Kit Inicial Com Pião E Lançador Hasbro F9580', 'Prepare-se para entrar no emocionante mundo das batalhas de Beyblade com o Beyblade X Sword Dran 3-60f da Takara Tomy. Este pião, projetado para jovens de 8 a 13 anos, combina um design impressionante com materiais de alta qualidade, incluindo metal, garantindo durabilidade e desempenho superior em cada duelo. O Beyblade X Sword Dran vem acompanhado de um lançador, permitindo que você comece suas batalhas imediatamente. Sua construção robusta e estética atraente fazem dele um item indispensável para qualquer colecionador ou entusiasta de Beyblade. Desafie seus amigos e teste suas habilidades estratégicas enquanto compete para se tornar o campeão das batalhas. Com o Beyblade X Sword Dran, cada giro e cada impacto trazem uma nova oportunidade de vitória. Prepare-se para a ação e mostre quem é o verdadeiro mestre das batalhas. Aviso legal • Idade mínima recomendada: 8 anos.', 149.9, 109.0, NULL, 'Mom & Baby > Toys > Others', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meq4ih8ts7wi0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F567914216%2F20498318591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23593552610', 'Chinelo da Lata Qix Chorão Eterno Masculino Branco Preto Conforto Resistente Borracha', 'Esse produto busca materializar um dos versos famosos do cantor que indicou que o seu escritório era na praia e ele estaria sempre na área. Afinal de contas, o bom é o do lata! Com sola de borracha e correias injetadas, o chinelo possui estampado em sua palmilha trechos da música da banda. A lata de alumínio totalmente personalizada dá o toque especial para aqueles que desejam colecionar os itens desse artista que se tornou eterno. Informações do produto: Material das Correias: Borracha Solado: Borracha Natural Dimensão da Embalagem: 13,5x33,5 cmX14,0cm', 194.87, 69.9, NULL, 'Men Shoes > Sandals & Flip Flops > Flip Flops', 'https://cf.shopee.com.br/file/br-11134207-81z1k-mhgbzsc8hz416d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F976841479%2F23593552610', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29239367145', 'Almofada De Esponja U Convexo Respirável Bojo Para Sungas E Cuecas 24171', 'Bem-vindos a 【Z&D Lingerie】,Insistimos no menor preço para vender os melhores itens de qualidade!! Descrição do Produto Almofada De Esponja U Convexo Respirável Bojo Para Sungas E Cuecas 24171 Esta almofada é projetada para uso com sungas e cuecas. Feita de esponja U convexo, oferece conforto e suporte. A textura respirável garante frescor durante o uso. Perfeita para quem busca uma almofada funcional e prática. O modelo 24171 é ideal para aqueles que valorizam simplicidade e eficiência. A almofada combina perfeitamente com suas peças de roupa íntima, proporcionando um toque de conforto extra. Sua estrutura em esponja U convexo é notável por sua versatilidade e adaptabilidade.', 60.0, 19.99, NULL, 'Beauty > Bath & Body Care > Sun Care', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mcusyuxprs4y49', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1189432015%2F29239367145', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22293640114', 'Filtro de Combustível Peugeot Hoggar todos de 2010 a 2015 Original Mahle Metal Leve', 'FILTRO DE COMBUSTIVE L MAHLE METAL LEVE KL583 APLICAÇÃO : PEUGEOT HOGGAR MOTOR 1.4 E 1.6 TODOS OS MODELOS DE 2010 A 2015 A função do filtro de combustíve l é reter as impurezas existentes no combustíve l acumulado no tanque do veículo, evitando que cheguem à bomba injetora, bicos injetores e unidades injetoras (veículos eletrônicos). A não substiuição no periodo correto pode provocar: - Aumento de consumo; - Perda de potência; - Dano na bomba de combustíve l, bicos, unidades injetoras e até causar parada total do veículo. PRODUTO NOVO ORIGINAL COM NOTA FISCAL , ENVIO RAPIDO !', 34.99, 28.7, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m4rjaf8j6ce9a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F318894435%2F22293640114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
