INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48860210113', 'Taça de Vidro Diamante Transparente 340ml', 'Taça de Vidro Diamante Transparente é ideal para servir água, sucos, drinks e outras bebidas com mais elegância no dia a dia ou em ocasiões especiais. Produzida em vidro transparente, possui design com textura estilo diamante, que valoriza a mesa posta e combina com diferentes decorações, oferecendo beleza, praticidade e sofisticação em bares, cozinhas, eventos e recepções. Destaques: Design Sofisticado: Acabamento em relevo estilo diamante que deixa a taça mais elegante e decorativa. Vidro Transparente: Material bonito e versátil, ideal para destacar a cor das bebidas servidas. Capacidade Ideal: Com 340ml, atende bem ao uso diário e a momentos especiais. Uso Versátil: Perfeita para água, sucos, refrigerantes, drinks, coquetéis e bebidas geladas. Mesa Mais Bonita: A Taça de Vidro Diamante Transparente valoriza composições de mesa posta com charme. Fácil Combinação: A taça combina com diferentes estilos de louças, copos e acessórios de cozinha. Especificações do Produto: Produto (contém): 1 taça de vidro transparente 340ml Dimensões do produto: (largura) x (altura) x (profundidade): não informado Material: Vidro transparente Modo de uso ou Instruções de cuidado: Lavar com esponja macia e detergente neutro. Evitar quedas, impactos e produtos abrasivos para preservar o brilho e a durabilidade da peça. Não perca nenhuma novidade! Siga nossas redes sociais e fique por dentro de lançamentos e muito mais!', 59.99, 35.99, NULL, 'Home & Living > Dinnerware > Cups, Mugs & Glasses', 'https://cf.shopee.com.br/file/sg-11134201-820o8-mnzwpo5e7d3a2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341754426%2F48860210113', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
