INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21907180926', 'VINHO ALTOS DEL PLATA CABERNET SAUVIGNON 750ML', 'Tinto argentino com aromas de frutas vermelhas, especiarias, principalmente pimenta, toques de chocolate e baunilha. Em boca, apresenta bom corpo, frutas intensas mescladas aos toques da madeira, agradável acidez e taninos presentes. Terrazas de Los Andes é pioneira na elaboração de vinhos de altitude na Argentina. O terreno onde estão os vinhedos é formado por terraços inseridos na Cordilheira dos Andes. Um belo terroir para elaborar um vinho de excelente qualidade.', 89.9, 89.9, NULL, 'Food & Beverages > Alcoholic Beverages > Wine & Champagne', 'https://cf.shopee.com.br/file/br-11134201-23010-my6hu9nn0emvc6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F661273874%2F21907180926', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
