INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23294819498', 'Fertilizante Casa Verde Raiz NPK 08-08-08 120 mL', 'Fertilizante Casa Verde Raiz NPK 08-08-08 120 mL CASA VERDE RAIZ DIMY é um fertilizante líquido, indicado para ser diluído em água e aplicado na planta em formas de regas. Sua formulação é composta de 8% de nitrogênio, 8% de fósforo e 8% de potássio. Por ser solúvel é mais rapidamente absorvido pelas plantas, proporcionando uma adubação mais eficiente. Possuem em sua composição os nutrientes essenciais para as plantas. Sua fórmula é balanceada para que estimule o enraizamento, fazendo com a área radicular da planta fique maior e consequentemente a planta tenha uma absorção maior e melhor dos nutrientes. CASA VERDE RAIZ DIMY possui a conveniência de não oferecer riscos de queima para a planta, pois como é aplicado bem diluído, as chances são quase nulas.', 22.99, 12.99, NULL, 'Home & Living > Gardening > Fertilizer', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mjsusnqt569t07', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F464043565%2F23294819498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
