INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21497097591', 'Pingente ouro 18k concha do mar mini 0.7cm', 'Descubra a beleza etérea do Pingente de Ouro 18k Concha do Mar Mini da Aqua Joias. Esse delicado pingente é uma joia deslumbrante, confeccionada com o brilho incomparável do ouro 18k, trazendo consigo a magia do mar. Como um pingente de ouro 18k, essa peça é um símbolo de luxo e elegância. Sua concha do mar miniatura é habilmente trabalhada, capturando os detalhes naturais de forma impressionante. Com esse pingente, você pode levar consigo um pedaço do oceano, mantendo-o sempre perto do seu coração. Seu tamanho mini proporciona um toque discreto de estilo, tornando-o ideal para uso diário ou para ocasiões especiais. O ouro 18k confere um brilho excepcional a cada detalhe do pingente, refletindo a luz com um encanto incomparável. Essa joia é uma expressão de estilo refinado e personalidade única. Adquira o Pingente de Ouro 18k Concha do Mar Mini da Aqua Joias e mergulhe na beleza do mar. Explore nossa coleção de pingentes do mar e descubra a conexão especial entre o ouro 18k e a magia da natureza. Encontre a expressão perfeita do seu estilo pessoal com nossas joias exclusivas. Material: Ouro 18k Tamanho: 7mm x 7mm (0,7cm x 0,7cm) Peso: 0,25 gramas', 420.0, 320.0, NULL, 'Fashion Accessories > Additional Accessories > Charms, Pendants & Ornaments', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m1zvl3qp0an8d3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328147687%2F21497097591', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42274769530', 'Coenzima Q10 Pote 120 Cápsulas Arnold Nutrition', 'Coenzima Q10 com Resveratrol e TCM – 120 Cápsulas – Arnold Nutrition - O Coenzima Q10 com Resveratrol e TCM da Arnold Nutrition é um suplemento alimentar que combina nutrientes de alta qualidade em uma fórmula exclusiva. Essa sinergia reúne o poder antioxidante da Coenzima Q10, as propriedades do Resveratrol e a eficiência dos Triglicerídeos de Cadeia Média (TCM), que auxiliam na melhor absorção dos compostos. Cada cápsula fornece 200mg de Coenzima Q10, atendendo à recomendação diária desse importante nutriente. As cápsulas são vegetarianas, oferecendo uma opção prática e de qualidade para complementar a alimentação. Composição e Ingredientes: - Coenzima Q10, Resveratrol, Triglicerídeos de Cadeia Média (TCM), antiumectante dióxido de silício e cápsula vegetal (hidroxipropilmetilcelulose). Não contém glúten. Benefícios: - Suplemento antioxidante com CoQ10 e Resveratrol. - Contém TCM para melhor absorção dos nutrientes. - Cápsulas vegetarianas e de alta biodisponibilidade. Sugestão de Uso: - Consumir 1 cápsula ao dia, preferencialmente junto com as refeições, ou conforme orientação de médico ou nutricionista. Informações Técnicas: - Porção: 1 cápsula (200mg de CoQ10) - Quantidade: 120 cápsulas - Rendimento: até 120 doses - Indicação: uso adulto Armazenamento: - Conservar em local seco, fresco e ao abrigo da luz solar. Avisos Importantes: - Produto indicado para maiores de 18 anos. - Este produto não é um medicamento. - Não substitui uma alimentação equilibrada.', 159.99, 119.9, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-8259b-mfxyiqrrgc20c9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F662618933%2F42274769530', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
