INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23892825613', 'Mangá - Blue Lock Vol. 22 - Novo/Lacrado', 'Blue Lock Vol. 22O egoísmo está em constante mudança!A partida contra a Manshine City é tomada pelo caos!!Na terceira partida da Liga Neo Egoísta, o time de Isagi vira o jogo e está na frente. Mas, tendo sido atrapalhado pelo Kaiser, o nosso herói jura vingança marcando o seu próprio gol!Enquanto isso, Reo também decide evoluir de forma ''independente''. Só que Nagi lhe propõe que ''lutem juntos''. A mudança decisiva que ocorre nos dois gera um caos sem precedentes no campo de batalha! O caminho para a evolução é o domínio completo da Metavisão!Supere tudo, Yoichi Isagi!!''Só falta mais um pouco'' é mesmo coisa que ''nada''!Se você é um atacante, vença como se a sua vida dependesse disso!Tipo de Produto: Revista Segmentos: Mangás Marcas: Planet Manga Autor(es): Muneyuki Kaneshiro, Yusuke Nomura ISBN: 9786525915012, 978-65-259-1501-2 Check-List: Julho/2024 Classificação Etária: 14 anos Editora: Panini Indicação: Pré-Adolescentes - Fundamental II Demografia: Shonen Número de páginas: 192 Lombada/Encadernação: Quadrada Tipo de capa: Cartão Data de Lançamento: 21/07/2024 Idioma: Português Condição: Novo/Lacrado', 47.9, 47.9, NULL, 'Books & Magazines > Books > Comics & Manga', 'https://cf.shopee.com.br/file/sg-11134201-7reqe-m8huyfrjpqxj17', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F642933481%2F23892825613', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
