INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23694830483', 'Panela First Sauté Petit Vermelha 20cm Ichef Polishop | Ichef', 'Com a linha First Ichef, você realiza seu sonho de adulto: cozinha tudo sem grudar, sem usar óleo e não tem trabalho na hora de lavar! Mais fácil de manusear: não cansa os braços!A Panela First Sauté Petit foi pensada para ser mais fácil de manusear no preparo das refeições e, depois, na hora de lavar. Seu cabo conta, ainda, com a tecnologia Soft Touch que proporciona uma pegada macia e confortável!Antiaderente Exclusivo PolishopAs panelas Ichef Polishop contam com antiaderente NÍVEL A, ou seja, seu revestimento é o melhor para os alimentos deslizarem facilmente e sem grudar nada, segundo o Inmetro*. Aproveite receitas mais saudáveis sem usar uma gota de óleo!Todos os tipos de fogão Mais variedade nas receitas do dia a dia: faça com facilidade omeletes, panquecas, postas de salmão, steaks, molhos e muito mais! Tudo isso em qualquer tipo de fogão – a gás, elétrico, de indução ou cooktop!Ichef PolishopTodas as panelas Ichef Polishop são livres de PFOA e não soltam resíduos! Elas são resistentes, não lascam, não deformam e estão sempre prontas para a próxima receita porque são super fáceis de limpar! A Panela First Sauté Petit é uma novidade exclusiva Ichef, a marca Gourmet da Polishop!', 299.88, 177.68, NULL, 'Home & Living > Kitchenware > Pots', 'https://cf.shopee.com.br/file/sg-11134201-8262x-mkcfzjbqrnyc8e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F810071078%2F23694830483', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22798461092', 'Rolamento Universal 6205 RS 25x52x15 mm Vedação Borracha Aço Forjado - IR16205 RS', 'Especificações Técnicas: • Marca: IRB AUTOMOTIVE • Cód. da peça: IR16205 RS • Tipo de rolamento: Esferas Vedado Borracha Medidas: • Diâmetro Interno (mm): 25 • Diâmetro Externo (mm): 52 • Espessura (mm): 15 • Peso (g): 120 Os Rolamentos IRB são fabricados com aço GCR15, que é conhecido por sua excelente dureza, o que o torna capaz de suportar cargas pesadas e resistir ao desgaste, mesmo em condições de operação severas. Apesar de sua dureza, o aço GCR15 favorece uma boa tenacidade, o que significa que pode absorver impactos e choques sem quebrar facilmente, prolongando vida útil do rolamento. Rolamento ideal para diversas aplicações automotivas e industriais.', 19.9, 14.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9gbhi2g61x574', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1497249598%2F22798461092', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
