INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22794700013', 'Tênis Mizuno Feminino Wave Dynasty 7 Corrida', 'O Tênis Mizuno Wave Dynasty 7 combina inovação, conforto e performance em um só modelo. Perfeito para quem busca versatilidade no dia a dia, ele é ideal tanto para corridas quanto para caminhadas. Conta com a exclusiva tecnologia Mizuno Wave, que oferece amortecimento eficiente e excelente estabilidade a cada passada. Seu cabedal em tecido respirável e flexível se adapta aos movimentos dos pés, garantindo ventilação e conforto prolongado. Com visual moderno e desempenho de alto nível, o Wave Dynasty 7 é o parceiro certo para quem não abre mão de estilo e bem-estar durante os treinos. Garanta já o seu!', 659.89, 399.88, NULL, 'Women Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-82628-mj5pn9rqcqo20e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F22794700013', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
