INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21699244936', 'Pratice Pad de Estudos em MDF e EVA 12 Polegadas p Baterista', 'Olá, seja bem-vindo à HGZ Music Store Está em busca de um Pad de Estudos, para poder praticar suas tecnicas com metronomo de forma facil e portatil? A HGZ Music Store traz o Pratice Pad de Estudos 12" EVA Dupla Face Octogonal PAD 12 Liverpool para atender sua necessidade! Liverpool, a maior fabricante de baquetas da América Latina, especializada na criação de linhas profissionais, possui em seu portifólio mais de 400 produtos entre baquetas e acessórios para percussão e bateria. Produzido em MDF e espuma EVA de alta resistência erebote, um acessório indispensável para aprimorar os estudos e técnicas. Produtos originais e com nota fiscal. O que você está comprando: 1 Pratice Pad de Estudos 12" EVA Dupla Face Octogonal PAD 12 Liverpool Características do Produto: Material do Corpo: MDF Material do Pad: EVA Material doa Apoios: EVA Formato: Octogonal Comprimento: 290mm Largura: 290mm Espessura: 18mm Peso: 650g Cor: Preta Fosca Somos a HGZ Music Store, uma empresa totalmente focada em e-commerce no ramo de Instrumentos Musicais, sempre oferecendo as melhores marcas de equipamentos do mercado e com a devida expertise ao implementa-los ao nosso catálogo. Sua experiência será a de uma compra segura e garantida pelas melhores tecnologias de operação do mercado e entrega rápida! Caso tenha ficado alguma dúvida, nossa equipe estará pronta para te atender! HGZ Music Store', 78.9, 49.9, NULL, 'Hobbies & Collections > Musical Instruments & Accessories > Percussion Instruments', 'https://cf.shopee.com.br/file/sg-11134201-7rd6u-lub0i7uxidy283', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F340675874%2F21699244936', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
