INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29136586036', 'Pré-Treino Sem Cafeína 300g – Frutas Amarelas – Caffeine Free, Natural, 30 Doses', 'Biogens agora é Bigens! O Workout Clean Label da Bigens é um pré-treino desenvolvido para quem busca alto desempenho físico com saúde e pureza. Sua fórmula inovadora é livre de cafeína sintética, corantes artificiais e adoçantes químicos, sendo ideal para treinos diurnos ou noturnos, sem causar agitação ou interferir no sono. Disponível em dois sabores naturais e refrescantes: 🍓 Morango com Abacaxi – com corante natural de beterraba 🍍 Frutas Amarelas – com corante natural de cúrcuma. Cada dose fornece uma combinação eficaz de aminoácidos e compostos energéticos como L-Arginina, Beta-Alanina, L-Tirosina, Taurina e Isomaltulose, promovendo foco, resistência e energia de liberação gradual para potencializar seus treinos. Diferenciais do Produto: ✔ Sem cafeína sintética ✔ Fórmula clean label ✔ Adoçado com stevia ✔ Pode ser tomado à noite ✔ Ingredientes selecionados ✔ Sabor natural e agradável ✔ Rende 30 porções por embalagem Sugestão de uso: Diluir 10g (2 dosadores) em 200ml de água gelada ou suco. Consumir preferencialmente antes do treino ou conforme orientação profissional. Ingredientes principais: L-Arginina, Beta-Alanina, L-Tirosina, Taurina, Isomaltulose, Stevia e corantes naturais. Não contém glúten. Produto indicado para adultos ≥ 19 anos.', 78.96, 78.96, NULL, 'Health > Food Supplement > Fitness', 'https://cf.shopee.com.br/file/sg-11134201-7rfh8-m9rq1mh9xizd30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1059419518%2F29136586036', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
