INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '27733416810', 'Sutiã Plus Size Mãe Nayane Rodrigues Pós-Parto e Amamentação Confortável Rendado com Fecho Fácil', 'Sutiã Mãe Plus Size Rendado Ref . NRSP111 Sutiã Mãe Plus Size é perfeito para oferecer conforto e praticidade durante a amamentação, gestação e pós-parto. Confeccionado em tecido rendado de alta qualidade, combina elegância e delicadeza com a resistência necessária para o dia a dia da mamãe. Seu design foi pensado para garantir um suporte ideal, fecho fácil que facilita a abertura e fechamento com uma mão, ideal para as mães que amamentam. A alça ajustável proporciona ainda mais conforto, e o modelo foi desenvolvido para se ajustar perfeitamente ao corpo, promovendo um encaixe confortável sem apertar. Ideal para quem busca praticidade sem abrir mão do estilo. - Abertura Para Amamentação. - Acompanha o Crescimento dos Seios - Click Versátil. - Amamentação Com Segurança. Composição Tecido: Poliamida 91% e Elastano 9% Renda: Poliamida 90% e Elastano 10% Forro: Algodão 100%', 116.98, 70.19, NULL, 'Women Clothes > Maternity Wear > Breastfeeding Wear', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8kl9tw1jfgx9b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800864347%2F27733416810', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23093623752', 'Jogo de Chave Allen Torx T10 á T50 Com 9 Peças (702686) - Onsite', 'O Jogo de Chave Allen Torx T10 á T50 Com 9 Peças (702686) - Onsite, é uma ferramenta versátil projetada para apertar e soltar parafusos com cabeças do tipo Torx (também conhecidas como estrela). Esses parafusos são frequentemente usados em diversos tipos de aplicações devido à sua capacidade de suportar maior torque sem danificar a cabeça do Parafuso. Finalidade: • Manutenção Automotiva: É amplamente usado em veículos, como em sistemas de freios, suspensão e componentes internos. • Montagem de Móveis: Muitos móveis modernos usam parafusos Torx para montagem devido à sua segurança e resistência. • Eletrônicos: Aplicado em aparelhos como computadores, eletrodomésticos e outros dispositivos que utilizam parafusos Torx. • Indústria: Usado em máquinas, equipamentos industriais e ferramentas. Características do Jogo: • Tamanhos T10 a T50: Abrange uma ampla gama de tamanhos de parafusos, tornando o conjunto útil para diferentes tarefas. • 9 Peças: Oferece uma variedade para atender diferentes necessidades, do menor ao maior tamanho. • Durabilidade: Feitas de aço CRV, suportam altos níveis de torque e uso intensivo. • Design Compacto: Organizadas em um suporte para fácil transporte e armazenamento. Esse conjunto é ideal para profissionais e entusiastas que trabalham com equipamentos e móveis que exigem precisão e ferramentas específicas. Código: 702686. Marca: Onsite. Tamanho: T10 á T50. Ean: 1000011005291.', 26.93, 26.93, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7ra0o-m4osxmx7maoyb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F674110767%2F23093623752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
