INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '29383098306', 'Kemei 1747 Sem Fio Zero Gaped Trimmer Acabamento Elétrico Máquina De Corte Cabelo Cortar Profissional Recarregável Barba', '1. Aparador de cabelo kemei adota um motor com alta velocidade, baixo ruído, alta vida útil e longa vida útil. Funções de proteção contra sobrecarga/corrente constante/velocidade do motor é 7500PRM, e a placa de circuito possui sobrecarga e sobrecarga/saída de tensão constante/carga de corrente constante/carga sobrecorrente/carga de carregamento sobretensão sobretensão tem sobrecarga e sobrecarga/saída de tensão constante/carga de corrente constante/carga sobrecorrente/funções de proteção de carregamento sobretensão. Aparador de cabelo kemei usa carregamento USB TYPE-C 3. Aparador de cabelo branco FA1T com cerca de 2,5-3 horas para carregar completamente e pode ser usado continuamente com uma bateria de cabelo branco de 1500mAh, que leva cerca de 2,5-3 horas para carregar e pode ser usado continuamente por 180 minutos. Capa indicadora de cortador de cabelo está equipada com luz indicadora, 4. Os aparadores de cabelo KEMEI são feitos de lâmina de aço inoxidável 5. O processo de pintura aparador de cabelo kemei é feito de novo material ABS e o processo de pintura spray de carro esportivo garante efeito de pintura em spray uniforme e firme Nome da marca kemei ​ ​Tipo de alimentação de energia: Recarregável ​ ​Aparador de barba Uso: cabelo, aparador de barba ​ ​Voltagem: 100-240V ​ ​Tempo de carregamento: 2,5-3 horas ​ ​Tempo de trabalho: 180 minutos ​ ​Potência de 7500RPM muito poderosa ​ ​Número do modelo KM-1747 ​ ​Motor de ação: muito poderoso, 5w ​ ​Cor da imagem no show da página do produto: como a imagem na página do produto ​ ​Conteúdo da Embalagem ​ ​1 x Máquina ​ ​1 x Pincel ​ ​1 x cabo de carga (sem adaptador) ​ ​1 x manual ​ ​3 x pentes de limite ​ ​O óleo não está incluído', 174.0, 87.0, NULL, 'Beauty > Men''s Care > Shaving & Grooming', 'https://cf.shopee.com.br/file/cn-11134207-7ras8-m8h3e6cjn6cy0f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F450997010%2F29383098306', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
