INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26041434736', 'Sandália Vizzano Tamanco Salto Alto Quadrado Original 6464 Capuccino', '👡 Sandália Vizzano Tamanco Salto Alto Quadrado Original 8cm Se você busca elegância, atitude e conforto num só tamanco, essa Sandália Vizzano é a escolha certa. Salto robusto e bico quadrado proporcionam estabilidade, enquanto a palmilha com tecnologia Confy traz maciez para seus pés. Ideal para eventos, sair à noite ou compor looks poderosos com vestido, saia ou calça flare. Temos também esse modelo disponível em outras cores, acesse o link para conferir: https://shopee.com.br/product/324536294/28691364180/ ✅ Benefícios 🪶 Palmilha Confy: conforto prolongado, ideal para longas horas sem apertos. 📏 Salto alto quadrado de aproximadamente 8 cm: sobe a silhueta com estabilidade. 🛡️ Material sintético resistente, acabamento premium Vizzano. 🚶‍♀️ Solado emborrachado antiderrapante para segurança ao caminhar. 📑 Ficha Técnica 🏷 Marca: Vizzano 👠 Modelo: Tamanco Salto Alto Quadrado 📏 Altura do Salto: ~8 cm 🌟 Palmilha: Confy, acolchoada e confortável 🔧 Material: Sintético de alta qualidade 🛠 Solado: Emborrachado antiderrapante ✅ Produto original 🧼 Dicas de Limpeza Limpe com pano úmido e sabão neutro; nada de produtos químicos agressivos. Seque sempre à sombra, longe de calor direto. Evite molhar demais ou deixar imerso em água. Guarde em local ventilado; deixar muito tempo sem uso pode gerar cheiro – areje com frequência. 📏 Tabela de Medidas (aproximada) 34 → 22,5 cm 35 → 23,0 cm 36 → 23,5 cm 37 → 24,0 cm 38 → 24,5 cm 39 → 25,0 cm 40 → 25,5 cm', 119.9, 109.9, NULL, 'Women Shoes > Heels', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meinbnl3aio28e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F324536294%2F26041434736', NULL, NULL, '2026-07-28T02:11:31.708458+00:00'