INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693982581', 'Guerra e paz: Texto Adaptado | Liev Tolstói', 'Guerra e paz é a obra-prima de Liev Tolstói e retrata a sociedade russa antes e durante a invasão de Napoleão Bonaparte e seu exército à Rússia. Os reflexos da guerra são aprofundados em duas famílias aristocratas: Rostov e Bolkónski. O medo e a miséria do povo se contrastam com bailes realizados pela nobreza. Em um cenário bélico, religioso e incerto, o enredo disseca as jogadas de poder e seus impactos na sociedade, enquanto deixa transparecer as fraquezas da humanidade. 16x23cm 368 Páginas', 20.95, 15.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rfg0-m9nmgszbuu6x41', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F22693982581', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
