INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47456780594', 'Devocional Tesouros De Davi | Ornamento Azul', 'Devocional Tesouros de Davi Ornamento Azul Este devocional é projetado para facilitar a manutenção de uma rotina devocional consistente, essencial para desenvolver intimidade com Deus. Através de uma estrutura prática, você pode registrar orações, estudos bíblicos, pedidos e gratidão. Ele promove o crescimento espiritual contínuo, permitindo que você acompanhe a evolução da sua fé e reconheça as bênçãos ao longo da sua jornada. Não adie mais: seu tempo com Deus começa agora! 192 páginas 11x15 cm', 16.9, 10.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8261z-mlfhh9j7djpe3a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F47456780594', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '16905319850', 'Livro Samuel Morris | Lindley Baldwin', 'Samuel Morris é a prova de que qualquer pessoa pode exercer um ministério transcultural de grande impacto. Sequestrado na África por uma feroz tribo rival, o jovem Samuel foi miraculosamente liberto e depois guiado pela selva por uma estranha luz até um acampamento de libertadores de escravos, onde ouviu pela primeira vez o evangelho de Jesus Cristo. Foi então que a luz que brilhou na floresta como lâmpada para seus pés tornou-se também luz para sua vida. Numa busca constante de crescimento espiritual, Samuel embarcou como tripulante num veleiro que ia para os Estados Unidos. A princípio sofreu nas mãos de um capitão ímpio e de sua cruel tripulação, mas antes de chegarem a Nova Iorque, já havia conquistado o coração de seus perseguidores. Nos Estados Unidos, Samuel foi o instrumento simples e iletrado que Deus usou para despertar cristãos adormecidos e mudar o destino de uma prestigiosa faculdade evangélica, transformando-a em celeiro de missionários. A vida de Samuel Morris é comovente e instrutiva: nela você vai aprender como ser usado por Deus em meio a qualquer classe de pessoas. 10x17cm 96 Páginas', 21.9, 19.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/1dffc2feed14b992c54dd285d46bda2a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F16905319850', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44900959607', 'Coquetel Infantil | Picolé 15 | Passatempos Educativos', 'Concentração e paciência: desafios graduais promovem persistência e disciplina, criando hábitos de foco em cada página. Aprendizado divertido: design vibrante e níveis de dificuldade ajustados fazem do estudo um jogo prazeroso. Portátil e inclusivo: perfeito para casa, escola ou viagens, mantém as crianças próximas ao papel e longe das telas! Invista em um entretenimento educativo de qualidade: adicione agora mesmo Picolé ao carrinho e transforme o tempo de tela dos pequenos em horas de passatempos lúdicos e educativos! 15x27cm 32 páginas', 14.9, 13.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-821ez-mgrag3s9y0i744', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F44900959607', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
