INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57102372789', 'Suzy Consegue se Expressar | Quando Você for Tímido | Aaron Sironi', 'A coelhinha Suzy deveria estar animada para passar a noite com sua prima Alice. Mas, em vez disso, ela está nervosa. E se os amigos de Alice não gostarem dela? E se ela não conseguir falar nada? Depois de um encontro casual com uma professora de piano que parecia assustadora, Suzy aprende, por meio das palavras do Grande Livro, que Jesus pode ajudar mesmo aqueles que são tímidos. Editado pelo conselheiro Aaron Sironi, Suzy consegue se expressar ensinará às crianças que Deus está com elas mesmo quando se sentem ansiosas ao conhecerem novas pessoas. 22x22cm32 páginas', 32.9, 32.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8225w-mhpk183jsmiwc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F57102372789', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53354612357', 'As Perguntas Certas | Phillip E. Johnson', 'Phillip E.Johnson busca estimular o debate público, sempre suprimido pela elite intelectual da nossa sociedade. Indo bem além de assuntos referentes a evolução e criação, o autor convoca os vedadeiros educadores e líderes a preocupar-se com questões últimas, sobre o significado da História humana, verdade e liberdade, educação e religião em nossa sociedade pluralista. Questões sobre Deus e sobre Jesus Cristo, o Verbo de Deus. Johnson demonstra de que modo o filosofia naturalista dominante não apenas sufoca o debate público como também compele nossas discussões a formular as perguntas erradas. Porque, a menos que comecemos com as perguntas certas, as conclusões resultantes serão limitadas pela própria filosofia que desejamos desafiar. Provocante, pessoal, persuasivo e profético, o livro As Perguntas Certas nos ajudará a nos libertarmos do cativeiro intelectual e espiritual. 21x14 cm 176 Páginas', 16.9, 11.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8260c-mjfnqsl1ge0z12', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F53354612357', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
