INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '13950122250', 'Creme Dental Colgate Sensitive Pro-Alívio Imediato Original 90g', 'O creme dental para sensibilidade Colgate Sensitive Pro Alívio funciona como um escudo protetor (com o uso regular) e tem ação imediata (com aplicação direta, massageando por 1 minuto em cada dente sensível), cobrindo os canais que levam ao centro do dente, proporcionando alívio imediato à sensibilidade. Benefícios para você: Alívio imediato: com o creme dental para sensibilidade Colgate Sensitive Pro Alívio você tem alívio da sensibilidade 2x mais rápido (comparado com pastas de dente com nitrato de potássio). Tecnologia poderosa: com o poder da arginina, que cobre os canais que levam ao centro do dente, bloqueando a sensibilidade nos seus dentes. ? Escudo contra a sensibilidade: esse creme dental para sensibilidade cria uma barreira de longa duração contra a sensibilidade nos dentes (com o uso regular). Proteção: é uma pasta de dente para sensibilidade que funciona como um escudo protetor (com o uso regular) para os dentes sensíveis. Resultados: pasta de dente com ação clinicamente comprovada.', 26.89, 26.89, NULL, 'Health > Personal Care > Oral Care', 'https://cf.shopee.com.br/file/sg-11134201-7rd65-m7wd7nj5g5uv76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F557242410%2F13950122250', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
