INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23598717739', 'Guarda-Roupa Casal 6 Portas 4 Gavetas Mozart Caemmun', 'O Guarda-Roupa Casal Mozart Caemmun é a escolha ideal para quem busca organização, praticidade e um design moderno para o quarto. Com excelente aproveitamento interno, ele oferece amplo espaço para acomodar roupas, acessórios e objetos do dia a dia com muito mais praticidade. Produzido com estrutura resistente e acabamento de qualidade, o guarda-roupa garante durabilidade e estabilidade no uso diário. O modelo conta com 6 portas com dobradiças metálicas e 4 gavetas amplas, proporcionando melhor organização para roupas dobradas, acessórios e peças menores. Seu espaço interno é bem distribuído, com cabideiro e prateleiras, permitindo organizar diferentes tipos de roupas de forma prática e funcional. Características do Produto: Marca: Caemmun Modelo: Mozart Portas: 6 com puxadores resistentes Gavetas: 4 Material: MDP Corrediças: Telescópicas Espaço: Colmeia com 6 nichos Repartições: 14 internas amplas Cabideiros: 4 em alumínio Espaço de: Maleiros superiores Dimensões do produto: Altura: 234 cm Largura: 250 cm Profundidade: 57 cm Peso: 179,5 kg Garantia: 3 meses ⚠️ Observações Importantes: - As imagens são meramente ilustrativas e não acompanham objetos de decoração e eletros. - Pode haver alguma diferença de tonalidade entre a imagem e o produto, por conta do tratamento de imagens e a calibração de cores da sua tela. - Confira as dimensões do produto no momento da compra e certifique-se de que passará normalmente por elevadores, portas, escadas e/ou corredores, evitando assim futuros desagrados ou imprevistos com a entrega do produto. - A Lojas MM não se responsabiliza por montagens e instalações dos produtos.', 1999.9, 1888.0, NULL, 'Home & Living > Furniture > Wardrobes', 'https://cf.shopee.com.br/file/br-1