INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23191413965', 'Kit Eico Pro Força Crescimento Fortalecimento Antiqueda Antiquebra Shampoo Condicionador Máscara', 'Contém: 1- Shampoo Eico Professional Shampoo Força&Crescimento 300ml 1- Condicionador Eico Professional Força&Crescimento 300ml 1- Tratamento Eico Professional Máscara Força&Crescimento 300ml Sem Sal, Sem Parabenos, Sem Petrolatos, Sem Corante - Linha Liberada A linha Tratamento Força&Crescimento Eico Professional foi desenvolvida para aqueles cabelos com queda, enfraquecidos e quebradiços. Tratamento eficaz combatendo a queda fortalecendo da raiz até as pontas e estimulando muito o crescimento deixando seus cabelos cumpridos e fortes. Ativos: Biotina, Giseng, Pantenol e ProForce Complex Shampoo :Com o cabelo úmido, aplique uma pequena quantidade do Shampoo Tratamento Força&Crescimento sobre a palma das mãos e massageie suavemente por toda a extensão dos fios, da raiz até as pontas. Enxágue completamente e repita a operação. Remova todo o produto dos fios. Para um melhor resultado utilize a linha completa de tratamento EICO PROFESSIONAL Tratamento Força&Crescimento. Condicionador :Após lavar o cabelo com o shampoo EICO Tratamento Força&Crescimento 300ml. Enxágue completamente e retire o excesso de água com uma tolha. Aplique uma pequena quantidade do condicionador EICO Tratamento Força&Crescimento sobre a palma das mãos e massageie suavemente por toda a extensão dos fios evitando a raiz. Enluve mecha por mecha e deixe agir por 3 minutos. Enxágue completamente. Para um melhor resultado utilize a linha completa de tratamento EICO Tratamento Força&Crescimento. Tratamento:Após lavar o cabelo com o shampoo EICO PROFESSIONAL Tratamento Força&Crescimento 300ml. Enxágue completamente, retire o excesso de água com uma tolha. Aplique uma pequena quantidade do tratamento EICO Tratamento Força&Crescimento sobre a palma das mãos e massageie suavemente por toda a extensão dos fios evitando a raiz. Enluve mecha por mecha e deixe agir por 10 minutos. Enxágue completamente. Utilize o tratamento ao menos uma vez por semana. Para um melhor resultado utilize a linha completa de tratamento EICO Tratamento Força&Crescimento.', 214.7, 139.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-820lr-mnm047tr8gea70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F385344228%2F23191413965', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22292458234', 'Kit 4 Driver + 4 Cornetas Longas + 2 Super Tweeter Orion 720w 120Rms + Capacitor para Corneteira Caixa Trio Bob', 'Mais de 15 anos de experiencia no mercado com os melhores produtos e o melhor atendimento! KIT 4 DRIVERS + 2 SUPER TWEETERS + 4 CORNETAS LONGAS + CAPACITORES Este kit contem 4 drivers, 2 tweeters e 4 cornetas no total de 720W de potencia RMS, ideal para reproduzir frequencias medias e agudas, com total definicao sonora para o seu projeto de som. Carcaca super resistente e duravel, qualidade e desempenho reunidos em um so kit. Especificacoes tecnicas do Driver: Potencia: 120W RMS (cada) Impedancia Nominal: 8 ohms Sensibilidade driver: 109 Db Resposta de frequencia driver: 800 a 20000Hz Carcaca em Polipropileno Diagrama Fenolico Ima Ferrite de Bario Especificacoes tecnicas do Tweeter: Potencia: 120W RMS (cada) Impedancia Nominal: 8 ohms Sensibilidade tweeter: 111 Db Resposta de frequencia tweeter: 4000 a 20000Hz Bobina Simples Carcaca em Polipropileno Ima Ferrite de Bario Especificacoes tecnicas da Corneta: Corneta Longa 25 cm Fabricado em polipropileno Bocal Redondo Eficiencia de Dissipacao de Frequencias Medias Diametro aproximado da Garganta: 3,5 cm Diametro aproximado da Boca: 15 cm Conteudo da Embalagem: 4 Drivers, 2 Super Tweeter e 4 Cornetas LONGAS. FABRICANTE: ORION AUDIO', 249.99, 249.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/sg-11134201-7rbk9-lm3czejzwl6z0a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F22292458234', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14930445976', 'Caixa Amplificada Hiken GTX 8 Universal Subwoofer Mala Saveiro Montana Strada', 'Mais de 15 anos de experiencia no mercado com os melhores produtos e o melhor atendimento! Caixa Amplificada Hiken GTX 8 Universal Subwoofer Se voce e apaixonado por um grave mais profundo e nao quer comprometer o espaco em seu carro, vai se surpreender com a resposta final desta caixa. Temos no tamanho compacto que vem com um alto-falante de 8" - 400 Wmus - acompanha conector plug in play (somente as ativas). INDICADO PARA: Reforçar o grave do seu carro, mantendo a originalidade. Amplificador Digital / 200 Wrms - com contador de ganho independente / entrada alta e baixa. Caixa Compacta com baixo volume interno Excelente resposta nas faixas de subgraves Resposta de frequencia @-6db 30 ~ 150 hz Entrada Alta (High Level) e Baixa (RCA) Amplificador Mosfet com controle de ganho ajustavel Potencia de 90 WRMS Baixo Consumo de Energia Especificacoes Tecnicas: Impedancia de Entrada (Low Input) RCA 10KOhms Impedancia de Entrada Convencional: 680 Ohms Tensao de Alimentacao.: 14,4V (nominal), 12,0V (minimo), 16,0V (maximo) Fusivel Automatico de Protecao: 2,5 Amperes (maximo), 100mA (sem sinal) Altura.: 28,5 CM Largura.: 34,5 CM Comprimento.: 23 CM Peso.: 5KG', 599.99, 599.99, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/15db818e1734806b52be3b4da3ca003c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F625420381%2F14930445976', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
