INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8270279233', 'Livro - Noites brancas - Capa comum - Principis', 'Noite branca é um fenômeno comum na Rússia, em especial em São Petersburgo, em que o sol permanece um pouco abaixo da linha do horizonte ao se por, deixando a madrugada clara. É nesse cenário de atmosfera lírica que dois jovens sonhadores se conhecem em uma ponte. Ao longo de quatro noites, os dois combinam de se ver para falar sobre suas vidas e compartilhar sonhos, angústias e reflexões, até o desfecho inesperado ao final do quarto encontro. Editora: Principis Edição: 1, 2019 Autor: Fiódor Dostoiévski Idioma: Português Páginas: 80 Dimensões: L 16.00 x A 23.00 x E 0.70 ISBN: 9786550970284', 19.9, 13.93, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/54025676ae95af2ea88450d57a8bad10', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F8270279233', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
