INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50461778534', 'Chuteira Society Umbro Manchester Costurada Adulto Original', 'Chuteira Society Umbro Manchester para Grama Sintética A Chuteira Society Umbro Manchester foi desenvolvida para jogadores que buscam conforto, resistência e excelente desempenho nos gramados sintéticos. Com design esportivo e construção robusta, oferece estabilidade, controle e segurança para quem deseja elevar o nível das partidas. Seu cabedal em material laminado de alta resistência suporta o desgaste natural do jogo, enquanto o padrão de costuras proporciona maior flexibilidade e acompanha os movimentos dos pés, garantindo conforto durante toda a partida. A palmilha em EVA com acolchoamento proporciona amortecimento eficiente, reduzindo o impacto a cada passada. Já o solado em PVC com cravos para grama sintética oferece excelente tração, aderência e estabilidade, favorecendo dribles, arrancadas e mudanças rápidas de direção. Ideal para treinos e jogos de society, a Umbro Manchester combina qualidade, durabilidade e o desempenho que todo atleta procura. Características do Produto Marca: Umbro Modelo: Manchester Contém: 1 par de chuteiras Indicação: Society / Grama Sintética Cabedal: Material laminado de alta resistência Palmilha: EVA com acolchoamento Entressola: Costurada Solado: PVC com cravos para grama sintética Produto nacional Garantia contra defeito de fabricação Diferenciais Cabedal resistente e flexível Costuras reforçadas para maior durabilidade Palmilha macia com excelente amortecimento Solado com ótima aderência em gramados sintéticos Estabilidade e controle durante as jogadas Ideal para treinos e partidas de society Indicação de Uso Futebol Society Gramado sintético Treinos Jogos recreativos e competitivos Ao adquirir produtos na Sloth, você garante qualidade, durabilidade e originalidade. Todos os produtos são comercializados com autorização da marca e acompanhados de nota fiscal. Seu pedido será processado e enviado em até 24 horas após a aprovação do pagamento. Caso ocorra qualquer imprevisto, você será informado imediatamente. O produto conta com 90 dias de garantia contra defeitos de fabricação após o recebimento. 7 dias para devolução por desistência após o recebimento do produto.', 179.9, 164.9, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-823ri-mp58cqq6clxncd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F322737721%2F50461778534', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
