INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193247593', 'Kit 2 Unidades Ventosas Duplas Para Vidro Mármore Espelho Porcelanato Capacidade De 50kg', 'Kit 2 Ventosas Duplas Capacidade 50kg Bramix Esta ventosa é projetada para ser fácil de manusear, o que torna o trabalho mais rápido e menos cansativo, ideal tanto para profissionais quanto para DIY. Funciona em diversos tipos de superfícies e materiais, oferecendo a flexibilidade que você precisa para diferentes projetos. Com capacidade para suportar 50kg, você pode mover e instalar vidros e outros materiais pesados, evitando acidentes e danos. Características: > Produzida em plástico ABS com borracha; > Com capacidade de até 50kg, você garante maior segurança para as peças e agilidade de trabalho; > Ideal para facilitar o transporte de peças lisas e planas, como vidro, porcelanatos, pisos, espelhos, e outros. - Marca: Bramix - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 71.5, 68.64, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rdwg-lz9gslk1pnck2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F22193247593', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '54708959994', 'Macaco Hidráulico 2 Ton Vonder Reforçado Compacto P/ Carro Oficina Profissional', 'Macaco Hidráulico Garrafa 2 Toneladas Vonder O Macaco Hidráulico Tipo Garrafa 2 Toneladas Vonder é ideal para quem busca eficiência e segurança em serviços automotivos. Compacto, resistente e fácil de usar, ele é perfeito para elevação de veículos em trocas de pneus e manutenções rápidas. Conta com sistema hidráulico de alta performance, válvula de segurança e ajuste de altura por rosca, garantindo mais precisão e confiabilidade durante o uso. Características: >Capacidade de até 2 toneladas (2.000 kg); > Válvula de segurança contra sobrecarga; > Fuso com rosca ajustável (maior alcance e precisão); > Estrutura robusta e compacta; > Cabo bipartido (facilita armazenamento); > Base reforçada para maior estabilidade; > Fácil operação e transporte. Especificações: > Marca: Vonder; > Tipo: Hidráulico (garrafa); > Capacidade: 2 toneladas (2 tf); > Altura mínima: 181 mm; > Altura máxima: 345 mm; > Curso hidráulico: 116 mm; > Curso do fuso: 48 mm; > Base: 88 mm x 92 mm; > Peso aproximado: 2,5 kg; > Volume de óleo: 80 ml. - Marca: Vonder - Garantia: 90 dias contra defeitos de fabricação Vantagens de comprar na Brester: - Produto a pronta entrega. - Produto novo, com garantia de fábrica. - Nota fiscal para Pessoa Física e Pessoa Jurídica.', 156.06, 95.89, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Lift', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-mn4uauclf2maee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F442506479%2F54708959994', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
