INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21344948752', 'Engate Rápido com Aqua Stop para Mangueira 1/2" Karcher', 'Engate Rápido com Acqua Stop para Mangueira 1/2 que deve ser colocado na ponta de mangueiras, para conexão em torneiras, esguichos e Lavadoras de Alta Pressão. Com acqua stop, que não deixa a água espirrar quando for retirá-lo. Compatível com todas as lavadoras de alta pressão da linha residencial Karcher. Este anúncio contém: 1 Engate rápido Marca: Kärcher > Todos os nossos produtos são novos e originais. > Confirme sempre o modelo do seu aparelho na etiqueta que se localiza embaixo ou atrás do produto. > Verifique nossa lista de aplicações e utilize somente o modelo para confirmar a compatibilidade. > Imagens meramente ilustrativas Empresa fundada em 1935, a Kärcher sempre foi caracterizada por sua engenhosidade e pensamento inovador. Com sede na Alemanha, em Winnenden, perto de Stuttgart e no Brasil, na cidade de Vinhedo-SP, o grande marco da empresa líder mundial em soluções de limpeza aconteceu em 1950, com a invenção da primeira lavadora de alta pressão de água quente da Europa. A Kärcher é a única empresa do segmento com mais de 1200 postos de assistência técnica autorizada no Brasil, e tem como meta oferecer produtos e serviços de alta qualidade e performance, e que não agridam o meio ambiente. Está sempre inovando tecnologicamente com novos instrumentos, máquinas e ferramentas. Quando se trata de qualidade e tecnologia, nós somos a líder de sistemas de limpeza!', 19.9, 16.92, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-822z0-mo8j4u5ounswcd', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F848951954%2F21344948752', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58258355465', 'Teclado Dell Inspiron 14 3421 5421 90.4wt07.s1b V137225ar1', 'Teclado compatível com Dell Inspiron 14 3421 5421 90.4WT07.S1B / V137225AR1 O teclado compatível com Dell Inspiron 14 3421 5421 90.4WT07.S1B / V137225AR1 foi aprovado em rigorosos testes de qualidade e atende todas as exigências do seu equipamento, apresenta encaixe perfeito com o notebook, possui a mesma fixação da peça original. Além de 12 meses de garantia contra defeitos de fabricação. Atenção! Esse é um teclado bringIT, portanto não é um produto original da fabricante Dell. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Marca: bringIT Modelo: 14 3421 5421 90.4WT07.S1B / V137225AR1 Moldura: Com Moldura Idioma/Layout: ABNT2 Backlight: Sem Iluminação Pointing Stick: Sem Pointingstick Cor: Preto Referência: TC435-DE-0436 Atenção: Para que esse teclado seja compatível com seu notebook, deverá ter as mesmas especificações de encaixe, layout e moldura. Esse produto é compatível com os notebooks: 14-3421, V137225AR1, 14R-3421 3437 5421 5437 3660, 3440, 14R-5437, NSK-L90SW, P37G, 14-2620, 14R-5421, 90.4WT07.S1B, MB310-006, 14-2640, 14Z-5421, 14-2620 5421, 9Z.N8VSW.001, 15Z-5523, 14R-3440S Ficou na dúvida da compatibilidade ou precisa de mais informações? Deixe sua pergunta que nosso time técnico especializado está preparado para auxiliar! A bringIT é líder de mercado com o maior mix de produtos e peças para notebook: Baterias, telas, teclados e carregadores compatíveis com notebooks Dell, Lenovo, Acer, HP, Asus e muito mais!', 76.87, 44.0, NULL, 'Computers & Accessories > Desktop Computers > Others', 'https://cf.shopee.com.br/file/sg-11134201-8258k-mqtoiwllf85fee', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F58