INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20099357712', 'Cooler para Notebook Hp G4-1315BR', 'Cooler compatível com Hp G4-1315BR Interno Este é um Cooler bringIT compatível com o notebook Hp G4-1315BR. Os coolers para notebook da bringIT são a solução definitiva para possíveis problemas de ventilação e resfriamento do seu equipamento. Também conhecidos como “fans”, “ventiladores” ou “resfriadores”, os coolers são responsáveis pela retirada do máximo de calor gerado pelo processador e por outros componentes eletrônicos. Para evitar problemas de compatibilidade, compare as fotos deste anuncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu cooler. Atenção: Esse é um cooler bringIT, portanto não é um produto original da fabricante Hp. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Quantidade de vias: 3 vias Corrente (Amperagem): 0.4A Tensão (Voltagem): 5V Garantia: 3 meses de garantia contra defeitos de fabricação Referência: CL008-HP-0631', 49.88, 44.89, NULL, 'Computers & Accessories > Desktop & Laptop Components > Fans & Heatsinks', 'https://cf.shopee.com.br/file/sg-11134201-825ap-mqs1vwexam8f64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F20099357712', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22891642225', 'Parafusadeira FuradeiraBateria 12V Mandril 3/8" Polegadas Carregador Torque 24Nm 1350rpm - Lith', 'Loja do Mecânico - O que você precisa, nós temos Parafusadeira/Furadeira à bateria 12V é indicada para aperto e desaperto de parafusos, como também realizar perfurações de forma precisa e com ótimo resultado. Possui mandril 3/8" (10mm) de aperto rápido facilitando o ajuste da broca/bit na ferramenta. Seu LED auxilia na iluminação, para facilitar o trabalho em locais com pouca iluminação. Função de 2 velocidades mecânicas, indicador de carga de bateria. Características - Controle de Velocidade - Rotação Reversível Especificações Técnicas - Tensão da Bateria: 12V 1.5Ah - Bateria de Lítio - Mandril: 3/8" (10 mm) de Aperto Rápido - Rotação: 1ª Vel. 0 - 350 / 2ª Vel. 0-1350 RPM - Torque máximo: 24Nm - Controle de torque: 25+1 - Tempo de Recarga: 3h Conteúdo da Embalagem - 01 Parafusadeira/Furadeira - Bateria 12V - Carregador Bivolt Importante - Garantia 3 meses; - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 135.99, 135.99, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-7qve8-ljbith69jx8t94', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F22891642225', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594181344', 'Conector DC Jack para Notebook LG S43', 'Conector DC Jack compatível com Lg S43 Este é um DC Jack bringIT compatível com o notebook Lg S43. Ele é ideal para acabar com os problemas de alimentação de energia em um notebook. O DC Jack — ou DC Power Jack — é um conector interno responsável por intermediar a alimentação de energia entre a fonte (carregador) e o laptop. Este produto é um de alta qualidade e cumpre todas as especificações de segurança dos notebooks. Para evitar problemas de compatibilidade, compare as fotos deste anúncio com seu equipamento original. Assim você consegue verificar as principais informações de compatibilidade e demais especificações do seu notebook. Atenção: Esse é um dc jack bringIT, portanto não é um produto original da fabricante Lg. Caso seja necessário, todo o suporte e garantia do produto serão oferecidos pela nossa equipe. Informações Técnicas Tamanho do Conector: 6.0mm x 4.0mm Cabo: Com Cabo Garantia: 3 meses de garantia contra defeitos de fabricação Referência: DC017-LG-0013', 43.27, 41.11, NULL, 'Computers & Accessories > Desktop & Laptop Components > Power Supply Units', 'https://cf.shopee.com.br/file/sg-11134201-825am-mqt1cicplrm372', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F801641954%2F22594181344', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
