INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19397678509', 'ASSASSINATO NA CASA DO PASTOR', 'ASSASSINATO NA CASA DO PASTOR St. Mary Mead. Um pacato vilarejo onde há quinze anos não ocorre um homicídio e onde as pessoas discutem a vida alheia tomando chá. Quando um sangrento crime acontece em plena casa do pastor, o alvoroço é grande. O arrogante inspetor Slack é escalado para investigar o caso. O mistério também intriga uma discreta moradora que gosta de jardinagem e de observar pássaros de binóculo, mas cujo principal hobby é o estudo do comportamento humanoMiss Marple. A estreia da sagaz velhinha, o aparecimento de personagens inusitados e a engenhosidade da trama fazem deste romance de 1930 um dos clássicos de Agatha Christie.. Informações Adicionais Autor: CHRISTIE, AGATHA Data Publicação: 30/12/1899 Tipo de capa: BROCHURA Condição do Item: Novo Subtitulo: ASSASSINATO NA CASA DO PASTOR Idioma: PORTUGUES Páginas: 264 Edição: 1 ISBN-13: 9788525432261 ISBN-10: 8525432261', 54.9, 54.9, NULL, 'Books & Magazines > Books > Action, Crime & Thrillers', 'https://cf.shopee.com.br/file/sg-11134201-7rblf-lp9a1psjehlm1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F826663787%2F19397678509', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23393005820', 'Suporte Para Boina Prato Disco Rotativa 1'' Rosca 5/8 Vonixx', 'SUPORTE FLEXÍVEL ROTATIVA 1'''' – ROSCA 5/8” DESCRIÇÃO: Projetado para promover acabamento fino e resultados mais rápidos nas etapas de polimento na pintura automotiva. Garante melhor aderência, durabilidade, praticidade e resistência que os velcros comuns, é um produto bastante versátil e que confere perfeito balanceamento à Politriz Rotativa. CARACTERÍSTICAS: - CONFERE BALANCEAMENTO PRECISO - GARANTE MELHOR ACABAMENTO NA PINTURA AUTOMOTIVA - PRODUZIDO EM POLIURETANO FLEXÍVEL DE ALTA QUALIDADE - PERFEITO PARA POLIMENTO EM PINTURA AUTOMOTIVA, PARTES PLÁSTICAS, VIDROS E METAIS POLIDOS - TECNOLOGIA V-FLEX COM ANGULAÇÃO DE 45°, PERFEITA PARA ATENDER TODAS AS CURVAS E CONTORNOS DO AUTOMÓVEL', 68.92, 68.92, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Pads', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lvdaxifdnogw11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316945044%2F23393005820', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
