INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20920779498', 'Tampa Lateral Moto Honda Bros 125 150 2003 2004 2005 2006 2007 2008 Modelo Original Par Cromo Forte', 'As carenagens e peças plásticas Cromo Forte são produzidas nos moldes das peças originais da moto, descartando qualquer tipo de adaptação. Fabricadas em ABS 100% virgem, as carenagens Cromo Forte são extremamente resistentes aos raios UV, tornando-se assim o melhor custo-benefício do mercado. Características: - Marca: Cromo Forte; - Modelo: Original; - Tonalidade de cores semelhante ao original; - Valor referente ao par; - Moto compatível: NXR 125 Bros 2003 a 2005 e NXR 150 Bros 2003 a 2008 (Confira a relação de cores e anos abaixo). Aplicação: - Azul Penedo: Bros 125/150 2003 e 2004; - Branco: Bros 125/150 2003/2004 e 2007; - Vermelho Caucaia: Bros 125/150 2003/2004/2007 e 2008; - Preto: Bros 150 2004 a 2008; - Azul Buriti: Bros 150 2005e2006; - Vermelho Clívia: Bros 125/150 2006; - Amarelo Trancoso: Bros 150 2008. Atenção! - Devido ao desgaste da pintura da motocicleta com o passar do tempo, pode haver uma pequena divergência na tonalidade das cores. Instalação: - A instalação deve ser feita por um profissional especializado. A Sportbay não se responsabiliza por instalação mal realizada.', 84.11, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m90kugzr9zwiaa', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F436682589%2F20920779498', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
