INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22694421148', 'Sapatênis Denim Mike Cinza Cloudy', 'O Sapatênis Denim Mike é confeccionado em couro na cor Cinza Cloudy com recortes nas laterais. Possui fechamento em cadarço de elástico, facilitando o calce, logo da marca na língua e detalhe de couro marrom no calcanhar com puxador de tecido. Seu solado é de borracha na cor bege com detalhe preto no calcanhar e blaqueada na lateral, além de contar com uma palmilha macia de p.u com forro de tecido e bico arredondado.Linha Denim - Liberdade para transitar de uma reunião de trabalho para um happy hour e estar bem vestido. Contemporâneo, despojado, confortável e leve, perfeito para o uso no dia a dia.', 289.9, 289.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-8260l-mjslgumtjdhj40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1618027254%2F22694421148', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19121171390', 'Macaquinho Ciclismo Feminino Forro Gel Macacão Manga Curta Preto Way Fresh Roupa Bike Pedal Mtb', 'Macaquinho de Ciclismo Feminino com Forro em Gel Manga Curta – Conforto, Durabilidade e Leveza para Seus Pedais! Principais Características: • Forro em Gel D100: reduz as dores no bumbum e na pelve durante pedais curtos ou longos (até 10 horas). • Tecido leve e respirável: mantém o corpo fresco, mesmo nos dias mais quentes. • Proteção UV: segurança extra contra raios solares. • Barrinha dupla: não enrola durante o pedal. • Dois bolsos traseiros: para mais praticidade durante o uso. • Poliéster de compressão: alta elasticidade e sem transparência. Benefícios do Forro em Gel: • Reduz dores no bumbum e na pelve. • Ideal para pedais de até 10h. • Facilita o movimento e melhora o desempenho. Tamanhos Disponíveis: • P (36/38) | M (38/40) | G (40/42) | GG (42/44) • Confira a tabela de medidas nas imagens para uma escolha assertiva. Sobre a Loja Para Ciclistas: • Especialistas em artigos para ciclismo. • Produtos de qualidade e pronta entrega. • Atendimento de segunda a quinta, das 8h às 18h e as sextas das 8h às 17h. LOJA PARA CICLISTAS – O que faltava para o seu pedal está aqui!', 169.9, 79.9, NULL, 'Sports & Outdoors > Sports & Outdoor Apparels > Sets', 'https://cf.shopee.com.br/file/br-11134207-820l6-mphz1ufpq2gy93', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379576060%2F19121171390', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
