INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799607524', 'Sandália Usaflex Feminina Bico Redondo Couro Tira Trançada Casual AE32035', 'Combinando elegância e conforto, a Usaflex apresenta a Sandália Bico Redondo Tira Trançada AE32035, com acabamento sofisticado e prático. Este modelo possui o cabedal confeccionado em couro, material de qualidade e resistência. Seu design inclui uma tira frontal com uma delicada tira trançada, além de uma tira em elástico que proporciona calce fácil e firmeza, auxiliando na adaptação do calçado à ergonomia dos pés. O forro é feito de tecido resistente, macio e sedoso, além de prevenir a propagação de bactérias e fungos, evitando alergias e odores. O solado bloco baixo emborrachado garante maior aderência e durabilidade ao calçado. Aproveite!', 379.89, 224.88, NULL, 'Women Shoes > Flat Sandals & Flip Flops > Others', 'https://cf.shopee.com.br/file/sg-11134201-81zvq-mmj2r1ntczkfa4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920605202%2F18799607524', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
