INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23791518122', 'Defletor Calha de Chuva Chevette 1983 a 1993 2 Portas Ecoflex', 'Defletor Calha de Chuva Chevette 1983 a 1993 2 Portas Ecoflex A Ecoflex possui uma vasta linha de calhas defletores automotivas para os mais diversos modelos. Utiliza matéria-prima de primeira, 100% acrílico, com tecnologia 3M e instalação simples. Os produtos comercializados pela Ecoflex têm como objetivo trazer conforto e segurança em seu automóvel nos dias de chuva. Com a calha de chuva a água da chuva não entrará no interior do veículo e evita que os vidros embacem. Compatibilidade: • Chevette 1983 a 1993 2 Portas Especificações: • 100% Acrílica; • Proteção e Design; • Contra chuva e sol; • Fixada por Fita Dupla Face 3M; • Não deixa os vidros embaçarem. Conteúdo da Embalagem: • 2 Calhas Defletores de Chuva • 1 Primer (anti-aderente) Garantia: • 5 Anos (defeito de fabricação) Se tiver alguma dúvida a equipe Renovaccio estará pronta para lhe atender.', 118.71, 115.9, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7qvf4-li0a46fkpx0251', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1013208711%2F23791518122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997760149', 'Rack Madesa Cancun e Painel para TV até 58 Polegadas com Pés - Preto 8ND8', 'Renove sua sala com o que há de mais moderno em design. Conheça o conjunto do Rack Cancun com Pés e Painel 2185 da Madesa. O rack possui um tamanho ótimo, com uma porta de correr que permite fechar o lado esquerdo ou direito da abertura central. Além disso, são vários nichos de tamanhos variados. Assim, cabe tudo de maneira organizada, dos aparelhos eletrônicos até objetos decorativos, livros e revistas. Para completar, os pés dão mais firmeza e aumentam a altura do móvel. O painel tem design que mistura padrões verticais e horizontais. Comporta TV de até 58 polegadas e possui uma abertura central que facilita na passagem dos fios. Por ser separado do rack, pode ser fixado na altura desejada, conforme sua preferência ou necessidade. O acabamento combina é todo preto e os pés do rack são em amadeirado Rustic. O processo é feito em Poliéster Protetor com 7 camadas, detalhe que confere mais durabilidade e qualidade aos produtos. Além disso, é ecológico, isento de vapores prejudiciais à atmosfera. Imagens meramente ilustrativas. Itens inclusos: - Um (1) Rack de 64 cm de altura x 180 cm de largura x 32 cm de profundidade com pés em PVC - Um (1) Painel de 80 cm de altura x 136 cm de largura Código do produto: MDES0200218ND8 Obs: A Madesa não disponibiliza serviço de montagem. O produto segue com manual e todas as ferragens necessárias para a instalação. A Madesa possui compromisso com a sustentabilidade. Geramos energia limpa em nossa própria usina, priorizamos fornecedores responsáveis e utilizamos plástico reciclado em nossa produção. Além disso, reinserimos sobras no ciclo de reciclagem e investimos no desenvolvimento de nossos colaboradores e da comunidade. Garantia: Este produto conta com 1 ano de garantia total, sendo 3 meses de garantia legal e 9 meses de garantia contratual. A garantia cobre exclusivamente defeitos de fabricação e vícios ocultos. Não estão cobertos: problemas decorrentes de montagem incorreta, uso inadequado, exposição à umidade, calor ou luz solar direta, modificações no produto ou desgaste natural.', 609.99, 521.73, NULL, 'Home & Living > Furniture > Shelves & Racks', 'https://cf.shopee.com.br/file/sg-11134201-22110-5fxhncsyxljv39', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F872473112%2F23997760149', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
