INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14911806140', 'Auto Radio Mp3 Carro Com Bluetooth Controle Remoto Entrada Usb Sd Som Automotivo', 'Rádio MP3 Automotivo FP IMPORT FP 100 Bluetooth 7 Cores 2 USB FM 4x25W + Controle Remoto Aproveite toda a praticidade e qualidade do Rádio MP3 FP 100 da FP IMPORT. Um modelo completo, com Bluetooth, 2 entradas USB e visual moderno com iluminação em 7 cores. Ideal para quem quer melhorar o som do carro com ótimo custo-benefício. Especificações: - Bluetooth integrado - Potência 4x25W RMS - 2 Entradas USB (1 para músicas / 1 para carregamento) - 4 Saídas RCA - Rádio FM com memória de estações - Display com LED e botões com 7 cores RGB - Reproduz músicas por pastas - Controle por aplicativo (App Control) - Funções de áudio: INTRO / Pause / Repeat / EQ / BASS / TRE / FAD / CLASSIC / ROCK / POP Conteúdo da Embalagem: - 1 Rádio MP3 FP 100 - 1 Chicote de ligação 16 vias - 1 Controle remoto - 1 Manual do usuário Produto novo, com envio rápido, garantia e nota fiscal. Compre com confiança na loja oficial OESTESOM na Shopee!', 84.03, 72.86, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mbcni7r22589a3', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F14911806140', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18997971852', 'Rádio Bluetooth Automotivo Usb Sd Card Fm 4x25w 100w rms Som Rca Carro 4 Saidas RCA', 'Rádio Automotivo Bluetooth FP IMPORTS 4x25W - Exclusivo OESTESOM Compatível com Diversos Sistemas de Som Ideal para quem busca um rádio automotivo completo, com tecnologia avançada e funcionalidades que atendem tanto aos exigentes como aos que buscam praticidade no dia a dia. Potência e Qualidade de Som Este rádio automotivo oferece 4 saídas de 25W cada, garantindo som potente e claro para seu carro. Equipado com equalizador completo (EQ, Bass, Tre, Fad, Ba) e predefinições de som (Classic, Rock, Pop), proporciona a melhor experiência de áudio personalizada. Conectividade Bluetooth e Controle por App Ouça suas músicas favoritas sem fios através do Bluetooth. Controle o rádio diretamente pelo aplicativo no seu celular, proporcionando praticidade e facilidade de uso. Multimídia Completa Além do Bluetooth, o rádio possui entrada USB, leitor de cartão SD e 4 saídas RCA para conexão com amplificadores e subwoofers. Reproduz músicas direto de pastas organizadas, permitindo total controle do conteúdo. Rádio FM Estéreo e Mais Funções Aproveite a função Rádio FM Estéreo e outras funcionalidades como intro, pause, repeat, e controle remoto para uma experiência completa. Carregue seu celular pela porta USB disponível. Display em LED Moderno Com um display em LED, o design moderno e funcional do rádio garante fácil visualização em qualquer condição de luz.', 84.03, 72.86, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/br-11134207-7r98o-mc22vsbffidh6e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F18997971852', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
