INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21998140213', 'SHAMPOO PARA CABELOS DANIFICADOS – JOICO K-PAK 300 ml', 'O Joico K-PAK Shampoo To Repair Damage limpa os fios de forma eficaz e delicada, ao mesmo tempo que inicia o processo de reconstrução capilar logo no primeiro passo da lavagem. Desenvolvido especialmente para cabelos danificados por químicas, calor ou outros fatores externos, ele é ideal para restaurar a saúde e vitalidade dos fios. ESPECIFICAÇÕES TÉCNICAS: Marca: Joico Cor: Amarelo translúcido Textura: Líquida Peso líquido: 300ml Origem: Importado (EUA) Indicação: Cabelos danificados e quimicamente tratados Fórmula: Complexo Quadramínico™, queratina hidrolisada, extrato de Aloe Vera, proteína de trigo Ação: Limpeza reconstrutora que fortalece os fios Frequência de uso: Uso diário ou conforme a necessidade Tipo de uso: Profissional e home care Produto lacrado e com selo de originalidade Benefício: Inicia a reconstrução capilar durante a lavagem Benefício: Restaura força e resistência aos fios Benefício: Prepara o cabelo para os tratamentos seguintes Garantia: Produto original com garantia de procedência CUIDADOS Evite contato com os olhos. Manter fora do alcance de crianças. Uso externo. Armazenar em local fresco e ao abrigo da luz.', 200.9, 126.57, NULL, 'Beauty > Hair Care > Shampoo', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m94peggcni2hff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F525611242%2F21998140213', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22199048612', 'Tênis Everlast Climber Ultra Feminino Verde e Preto', 'Tecnologias E-Shield: Tecido tecnológico que evita o odor nos pés. E-Grip: Solado projetado para uma melhor aderência durante os percursos mais difíceis. Ener-G: Entressola composta por super polímero de alta densidade que garante estrutura e amortecimento ao calçado. Ever Capsule: Peça feita em TPU, que fornece estruturação, projetando o pé para frente, trazendo mais estabilidade. Everknit: Tecido tramado através de um combinação de fios com áreas de maior abertura em pontos estratégicos para melhorar a respirabilidade do pé, fornecendo um calce ajustado, além de muito conforto. OrthoLite: Palmilha com amortecimento duradouro, leve e respirável. Garante conforto, controle de umidade e combate odores durante o uso. Composição cabedal (parte superior): Material Têxtil com parte em sintético Palmilha: EVA forrado e removível, facilita na higienização Forro: Material têxtil com acolchoamento reforçado Solado: Borracha antiderrapante Lingueta: Macia e flexível Cor predominante: Verde Entressola: EVA macio Origem: Nacional Gênero: Feminino Ajuste: Cadarço Peso aproximado: 670g o par nº 37', 350.9, 350.9, NULL, 'Sports & Outdoors > Sports Footwear > Training Shoes', 'https://cf.shopee.com.br/file/sg-11134201-825b5-mfu1pjzhepze8f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1337527569%2F22199048612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
