INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23494509945', 'Usado: Galaxy S23 512GB Creme Excelente - Trocafy - Samsung', 'Celular Seminovo Trocafy A Trocafy é especializada na venda de celulares Recondicionados (Seminovos). Aqui todos os aparelhos passam por revisão minuciosa de técnicos especializados e certificados pelos fabricantes para reparo. Condições: Excelente: Aparelhos com pouquíssimos sinais de uso, risco e/ou arranhões quase imperceptíveis tanto na tela quanto tampa traseira; Muito Bom: Aparelho com alguns sinais de uso como arranhões, riscos e/ou amassados na lateral perceptíveis, porém leves, tanto na tela quanto tampa traseira; Bom: Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Bom Bateria 70%:Aparelhos com sinais de uso nítidos/visíveis tanto na tela quanto na tampa traseira como por exemplo: riscos, arranhões, pequenos amassados e manchas na tela. Mínimo da bateria é 70%. IMPORTANTE: - Trabalhamos apenas com PEÇAS ORIGINAIS. Não utilizamos peças alternativas ou paralelas; - Aparelhos DESBLOQUEADOS para todas as operadoras e homologados pela ANATEL; - IMEI verificado garantindo originalidade e procedência legal do aparelho; - Por serem usados, os aparelhos não são resistentes a água (IP68/IP67); - Não acompanha acessórios; - NOTA FISCAL - Emitida em nome do comprador; GARANTIA - Aceita devoluções por arrependimento em até sete (7) dias corridos após o recebimento do pedido. Oferece 90 dias de garantia contra defeitos técnicos. CONTEÚDO EMBALAGEM: Aparelho adquirido em uma caixa personalizada da Trocafy;', 2429.0, 2307.55, NULL, 'Mobile & Gadgets > Mobile Phones', 'https://cf.shopee.com.br/file/sg-11134201-824j6-mfl95quzp4wc45', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1608031728%2F23494509945', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
