INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22698944724', 'Capa Absorvente para Cadeirinha de Carro SafePad Safety 1st', 'Capa lavável e absorvente: a proteção inteligente para os imprevistos da rotina — do desfralde aos passeios mais agitados. Durante o desfralde, acidentes acontecem. Mas eles não precisam complicar a rotina. A Capa Absorvente SafePad para Cadeirinhas é uma solução prática, criada para proteger o assento da cadeirinha e evitar a necessidade de higienização completa a cada escape. -Absorve vazamentos e pequenos acidentes, mantendo o assento seco e protegido. -Cobertura reforçada com absorção extra, pensada para os momentos mais críticos, como escapes ou mal-estares inesperados. -Design anatômico e flexível, adapta-se ao formato da cadeirinha sem atrapalhar o uso do cinto. -Mais fácil de remover que o forro original, agiliza a limpeza e economiza tempo. -Lavável à máquina, pronta para o reuso no dia a dia. -Compacta e leve, ideal para viagens e deslocamentos rápidos. Especificações: Material: Poliéster, Poliamida Peso: 1,55kg Medidas: 45,5 x 48,5 x 1 Garantia: 3 Meses Conteúdo da embalagem: 1 capa absorvente', 119.9, 99.0, NULL, 'Mom & Baby > Others', 'https://cf.shopee.com.br/file/sg-11134201-824hy-mf2waaipx823d4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1207408200%2F22698944724', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
