INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45804650143', 'KIT ELSEVE COLÁGENO LIFTER SHAMPOO ENCORPADOR + MÁSCARA EFEITO TEIA', 'ESTE KIT CONTÉM: 1 SHAMPOO ELSEVE COLÁGENO LIFTER ENCORPADOR 200ML 1 MÁSCARA ELSEVE COLÁGENO LIFTER EFEITO TEIA RESGATE DE MASSA 300G O Shampoo Encorpador Elseve Colágeno Lifter é um shampoo desenvolvido para cabelos finos, afinados e sem volume, que necessitam de encorpamento, densidade e aumento imediato da espessura dos fios. Sua fórmula contém um complexo exclusivo com peptídeos de colágeno vegetais, capazes de mimetizar os peptídeos naturalmente presentes no colágeno, ajudando a reconstruir massa capilar enquanto amplia o volume das raízes às pontas. O resultado são cabelos mais cheios, densos e volumosos desde o primeiro uso. O Tratamento Condicionante Efeito Teia Resgate de Massa Elseve Collagen Lifter é um tratamento capilar altamente encorpado que repõe massa perdida, fortalecendo e reconstruindo cada parte do fio. Sua tecnologia com peptídeos de colágeno vegetais mimetiza o colágeno natural, oferecendo volume, brilho e maciez desde o primeiro uso. Ideal para quem busca recuperação intensa, fios encorpados e toque leve sem pesar. Benefícios - Aumenta o volume dos fios finos desde o 1º uso - Reconstrói massa capilar e proporciona encorpamento visível - Oferece 72 horas de volume saudável - Controla a oleosidade, mantendo as raízes soltinhas - Fórmula enriquecida com peptídeos de colágeno vegetais - Ideal para quem busca fios mais espessos, encorpados e com mais densidade - Efeito teia que facilita distribuição e maximiza a performance do tratamento', 69.9, 59.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-82604-mjg32u9lf09039', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F45804650143', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
