INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15047431857', 'Sérum Antiacne 30ml PhálleBeauty Tratamento e Prevenção', 'Sérum Antiacne 30ml PhálleBeauty Tratamento e Prevenção O Mais novo lançamento do Mercado, O Sérum Antiacne 30ml PhálleBeauty foi desenvolvido especialmente para auxiliar na melhora da textura e aparência das peles oleosas e com acnes. Seus compostos bioativos possuem propriedades adstringentes, onde ajudam na regularização da oleosidade e redução da acne. Além disso, conta também com propriedades tonificantes e hidratantes, evitando o ressecamento e auxiliando na melhora da elasticidade da pele. Possui uma fórmula vegana, livre de parabenos e livre de petrolatos. Item essencial para uso diário para pessoas com pele oleosas e com acnes. Característica do Produto: - Apresentação: Frasco com conta-gotas - Volume: 30 ml - Tipo: Sérum Facial - Local de aplicação: Face - Função: auxilia no controle da oleosidade e previne acnes', 14.99, 14.99, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/c52dd605ca567baad8fb6acd15ed6679', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F434200296%2F15047431857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
