INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097787501', 'Colete Puffer Infantil Unissex Com Bolsos Hering Kids', 'Colete Puffer Infantil Unissex Com Bolsos. Para um look urbano e descolado, esse colete é perfeito! Com modelagem mais justinha ao corpo, bolsos funcionais e fechamento em zíper. Esse colete é feito em tecido plano de nylon com enchimento, super leve e confortável. Novidades que vão tirar 10 da prova do conforto e da praticidade! Volta às aulas com a Hering kids! Depois das férias, é hora de voltar às aulas! Diversão, cores e muito conforto! Por isso, a Hering Kids traz novidades em básicos e acessórios que vão tirar nota 10 na prova do conforto e da praticidade. Bora escolher os preferidos? Escolha os looks e acessórios mais estilosos para deixar a volta às aulas dos pequenos ainda mais divertida. Aproveite a seleção que preparamos! Clicando aqui', 179.99, 179.99, NULL, 'Baby & Kids Fashion > Boy Clothes > Outerwear', 'https://cf.shopee.com.br/file/sg-11134201-7rdyi-lzeyi7i2d10iea', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1281598928%2F21097787501', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
