INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '53206739528', 'Panelinha Max Com Tampa 1,5l Bluestar Rosa Bebê', 'A Panelinha Max Rosa Bebê Com Tampa da Bluestar é a escolha perfeita para quem busca praticidade, segurança e um toque de sofisticação na cozinha. Ideal para derreter chocolate, fazer misturas de bolo e tudo mais que o cake designer desejar, foi desenvolvida para uso no micro-ondas, permitindo aquecer e preparar alimentos sem bagunça. Seu design inteligente possibilita despejar líquidos e preparos sem precisar remover a tampa, garantindo mais higiene e conveniência. Além disso, é fabricada com material BPA Free, garantindo total segurança para seus alimentos, livre de substâncias tóxicas. Funcionalidade, estilo e segurança em um só produto! Leve mais praticidade para sua rotina com a Panelinha Max Rosa Bebê! Capacidade de 1,5 litros.', 45.36, 34.47, NULL, 'Home & Living > Kitchenware > Others', 'https://cf.shopee.com.br/file/sg-11134201-8262m-mlfaqb5sl2ird7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1507942655%2F53206739528', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
