INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58202346645', 'Bronzina Biela Medida 075 KS Para Kombi Brasilia Fusca Gol 1600 A AR', 'IDEAL AUTO PARTS Desde 1990 IDEAL PARA SEU CARRO Bronzina De Biela Medida 075 KS APLICAÇÃO VOLKSWAGEN Brasilia 1600 A Ar De 1973 A 1982 Brasilia 1300 A Ar De 1980 A 1982 Fusca 1300 A Ar De 1968 A 1986 Fusca 1500 A Ar De 1970 A 1976 Fusca 1600 A Ar De 1969 A 1997 Gol 1.300 A Ar De 1980 A 1981 Gol 1600 A Ar De 1982 A 1986 Kombi 1.600 A Ar 1980 A 2007 Kombi1500 A Ar 1967 A 1975 Kombi 1300 A Ar De 1981 A 1981 Saveiro 1600 A Ar De 1982 A 1986 OBS: BRONZINA BIELA MEDIDA 075 CODIGO DO FABRICANTE KS 87998634075 CONTEÚDO DA EMBALAGEM 01 JG BRONZINA BIELA QUALIDADE Produto Novo GARANTIA 03 Meses De Garantia NOTA FISCAL Sim SUPORTE PÓS VENDA Sim SOBRE A IDEAL AUTO PARTS Fundada em 1990, somos uma empresa do ramo de comércio e varejo de peças novas para veículos automotores. São mais de 30 anos oferecendo peças reconhecidas nacionalmente e internacionalmente com os melhores preços do Brasil. A paixão por automóvel e o crescimento do mercado, contribuiu para a expansão da marca e hoje contamos com quatro endereços físicos, localizados em pontos estratégicos na cidade de Limeira, Artur Nogueira e Rio Claro, no interior de São Paulo. Contamos com uma equipe especializada para prestar o melhor atendimento e oferecer exatamente o que nosso cliente precisa. São mais de 35 mil Itens de diversas montadoras a disposição em nossas lojas. CASO TENHA ALGUMA DÚVIDA USE O CAMPO DE PERGUNTAS, ESTAREMOS A DISPOSIÇÃO PARA TE ATENDER', 49.9, 49.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-81zvs-mikn7las2qrl3b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616290090%2F58202346645', NULL, NULL, '2026