INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21398141522', 'Sika Primer 206 G+P 250ml - SIKA', 'PRIMER DE ADESÃO PARA SUBSTRATOS - SIKA® PRIMER-206 G+P - PRETO - FRASCO 250 ml - SIKA O Sika® Primer-206 G+P é um primer preto à base de solvente, desenvolvido para melhorar a adesão de adesivos de poliuretano monocomponente da Sika em diversos substratos. Este produto forma uma fina camada que atua como elo entre os substratos e os adesivos, garantindo uma fixação mais eficaz. Características do Produto: - Base Química: Solução de poliuretano à base de solvente - Cor: Preto - Método de Aplicação: Pincel, feltro ou espuma - Consumo: Aproximadamente 50 ml/m², dependendo da porosidade do substrato - Tempo de Secagem: ≥ 15 °C: 10 minutos < 15 °C: 30 minutos Secagem total: 24 horas Áreas de Aplicação: O Sika® Primer-206 G+P é ideal para melhorar a adesão em uma ampla variedade de substratos, incluindo: - Vidro - Vidro serigrafado - Primers de pintura - Superfícies pintadas - Alguns plásticos - Metais Instruções de Aplicação: - Preparação da Superfície: A superfície deve estar limpa, seca e livre de graxa, óleo, poeira e contaminantes. - Aplicação: Agite bem o frasco até que as esferas de mistura chacoalhem livremente. Aplique uma camada fina e contínua com pincel, feltro ou espuma.', 672.9, 672.9, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9hn61hytr7mb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1501367141%2F21398141522', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42501038942', 'Hinário Cantor Cristão Com Letra | Grande | Capa Brochura Candy Tiffany', 'Hinário Cantor Cristão Com Letra Com pauta musical Hinos e cânticos estão na base da liturgia cristã e expressam a devoção e a espiritualidade do povo de Deus. Publicado pela primeira vez em 1891, o Cantor cristão é uma coedição da GEOGRÁFICA EDITORA e da Junta de Educação Religiosa e Publicações da Convenção Batista Brasileira (Juerp). Trata-se de uma tradição dos batistas e de diversas denominações que usam suas belas composições para adorar ao Senhor. Em mais esta edição da coletânea de louvores, estão 581 obras, de variados autores, nacionalidades e épocas, sendo alguns dele: Olavo Bilac; Martinho Lutero; Mario Barreto França... Hinos centenários, que têm inspirado gerações -, sempre com foco na elevação da alma do fiel, no convite ao não salvo para que conheça a Cristo e na proclamação do Evangelho por meio da arte. Especificações do Hinário Cantor Cristão Com Letra Título: Hinário Cantor Cristão Com Letra Subtítulo: Com Pauta Musical Ano de Edição: 2005 Capa: Brochura Acabamento: Laminação Fosca Miolo: Papel Bíblia Páginas: 448 Dimensões: Altura: 21 cm Largura: 14 cm Profundidade: 1 cm Peso: 0,210 kg ISBN: 9786556553597 Editora: Geográfica', 32.31, 32.31, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134275-7r98o-m9ks4vkn85j66e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F42501038942', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
