INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22594417903', 'Mala American Tourister Sun Break Média Preto', 'Prepare-se para viver histórias inesquecíveis com a mala Sun Break! Ideal para quem busca aliar estilo e praticidade, ela é a companheira perfeita para suas aventuras. Expansível e equipada com cadeado TSA, oferece maior segurança e garante viagens tranquilas e confortáveis. O design, com detalhes em cor contrastante, adiciona ainda mais autenticidade a cada jornada. Desfrute de todos os diferenciais desta mala e surpreenda-se com a sua American Tourister! CARACTERÍSTICAS Exterior - Sistema de 8 rodas - Cadeado TSA - Expansível - Bolso frontal Interior - Cintas cruzadas - Bolso de malha interno ESPECIFICAÇÕES TÉCNICAS Cor: Preta Capacidade: 67 L Capa de Mala: De tecido Garantia: 5 Anos Tamanho: M Tipo de Produto: Mala Material: 100% poliéster Coleções: Sun Break Modelo: Spinner M Tsa Exp Rodas: Duplas SKU: 14483210411 U Marca: American Tourister Peso: 3.3 Kg Expansível: Sim Cadeado: TSA Profundidade: 28 cm Largura: 45 cm Altura: 68 cm Limite de Peso: 23 kg', 659.0, 461.3, NULL, 'Travel & Luggage > Luggage', 'https://cf.shopee.com.br/file/sg-11134201-824iv-meorldl0q0ao5a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1118619903%2F22594417903', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
