INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11690438734', 'Box Salmos Vol. 1 e 2 | Comentários Expositivo | Hernandes Dias Lopes', 'Salmos Vol. 1 e 2 Vol. 1 (1-72): 784 p. Vol. 2 (73-150): 832 p. Total de páginas: 1.616 Salmos não é apenas o livro mais lido da Bíblia, mas também o mais extenso. É o livro das canções e orações do povo de Deus. Salmos é um livro para ser lido, cantado e pregado. Inspirado pelo Espírito Santo, esse livro é um reservatório inesgotável de refrigério para o povo de Deus ao longo dos séculos. Os salmos ensinam, exortam, confrontam e consolam. A eles recorremos nas noites sombrias da alma e no alvorecer das celebrações mais festivas. Eles não apenas falam a nós, mas falam por nós, e no espelho deles vemos a nós mesmos, em nossa jornada rumo à glória. Que esta obra ilumine sua mente e aqueça seu coração. Que estas exposições do Livro de Salmos sejam lidas com profunda reflexão e que sejam praticadas com zelo ardente, a fim de que, por meio delas, a igreja seja fortalecida, e a glória de Deus, manifestada.', 261.53, 261.53, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/4f60c5546f47cc93c9a2f08488b03161', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F11690438734', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
