INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21899380546', 'Livro Devocional Cheios da Graça | Claudio Duarte', 'Claudio Duarte Em um mundo saturado de informações superficiais, "Cheios da Graça" oferece 21 devocionais diários do Pastor Claudio Duarte para ajudar você a se conectar com Deus. Cada meditação é uma pausa enriquecedora que promove reflexão e crescimento espiritual, guiando-o através de revelações profundas com uma linguagem acessível. Dedique alguns minutos do seu dia a essas meditações e experimente a transformação da graça divina em sua vida. Altura: 23 cm Largura: 15,5 cm Profundidade: 1 cm Páginas: 116 Peso: 200 g', 34.41, 34.41, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m04k23duigfxf6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F400905650%2F21899380546', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997671939', 'Conjunto 6 Pratos Fundo 22,5 cm Ryo Maresia Porcelana Oxford', 'Prato Fundo 22,5 cm Ryo Maresia Porcelana Oxford Valorizar o imperfeito, o processo de criação até o seu acabamento. Este é o conceito wabi-sabi, uma visão de mundo japonesa praticada desde o século XV e que tem como base os ideais de uma estética que exalta o irregular, o impermanente e o incompleto. Seguindo essa tendência amplamente utilizada em vários itens de decoração, a Oxford apresenta a coleção Ryo: peças únicas que valorizam o trabalho manual e as composições imperfeitas. A aposta da coleção Ryo Maresia é a valorização das belezas das praias, do toque da areia e do frescor do mar. As peças desta coleção recebem também pigmentos de tintas que as tornam únicas e especiais. A aplicação de esmalte com pigmentação e de um filete reagente aplicado de forma manual garante exclusividade. A coleção Ryo Maresia dispõe ainda de peças complementares, como canecas, travessas e tigelas para deixar sua mesa mais completa. Descrição do produto Marca: Oxford Modelo: Ryo Coleção: Maresia Material: Porcelana Largura: 22,5 cm Imagens meramente ilustrativas, todos os itens que ambientam o produto não estão inclusos.', 297.73, 207.46, NULL, 'Home & Living > Dinnerware > Plates', 'https://cf.shopee.com.br/file/sg-11134201-7rdyx-ly8foow64jucdc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F638399297%2F22997671939', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11121855912', 'Livro - Minidicionário escolar Língua Portuguesa (papel off-set) - Capa comum - Ciranda Cultural', 'A língua portuguesa ao alcance das suas mãos onde e quando quiser! • Mais de 30.000 verbetes • Definições claras • Separação silábica • Indicação de classe gramatical E mais! • Aprenda a usar: ç, s, ss, j, g e x • Orientações para o uso do hífen • Quadro de substantivos coletivos Editora: Ciranda Cultural Edição: 1, 2017 Autor: Ciranda Cultural Idioma: Português Páginas: 352 Dimensões: L 10.00 x A 13.50 x E 1.50 ISBN: 9788538067245', 14.9, 10.43, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/7883838080c7c5c48e4c0b033d33fceb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F11121855912', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '6292634883', 'Livro - O Castelo Azul - Capa comum - Principis', 'Valancy Stirling tem 29 anos, é solteira e nunca se apaixonou. Sua vida é um marasmo. Vive com a mãe autoritária e a tia intrometida, numa rotina exasperante. Sua fuga é ler os livros proibidos de John Foster e seus devaneios sobre o Castelo Azul um lugar onde todos os seus sonhos se tornam realidade e ela pode ser quem realmente quer ser. Depois de receber do médico o diagnóstico de que tem uma doença terminal, ela se rebela contra a família e descobre um mundo novo e surpreendente, cheio de amor, alegria e aventuras, muito além de seus sonhos mais secretos. Editora: Principis Edição: 1, 2020 Autor: Lucy Maud Montgomery Idioma: Português Páginas: 256 Dimensões: L 15.50 x A 22.60 x E 1.50 ISBN: 9786555522037', 29.9, 29.9, NULL, 'Books & Magazines > Books > Classic Literature', 'https://cf.shopee.com.br/file/dacd8586b30d86b6345524724b75232f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F458071934%2F6292634883', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998574606', 'Filtro de combustível Wega para Chevrolet Spin 1.8 8V NLEV 2013 até 2024 - Cod. FCI1660', 'Protege o sistema de injeção eletrônica; Prolonga a vida útil do motor; Tecnologia avançada de retenção de impurezas; Maior durabilidade em relação a outros filtros; Garante o bom funcionamento do motor; Fácil instalação e substituição do produto.; Somos a Dispemec! Nossa trajetória começou em 1988. De lá para cá trabalhamos muito para evoluir e buscar excelência nos nossos serviços. Nosso segredo sempre foi cuidar de cada detalhe com muita dedicação e flexibilidade, pois é isso o que esperam os nossos parceiros e clientes com os quais compartilhamos os mesmos valores. Os desafios que superamos para acompanhar as mudanças do mercado automotivo sempre foram grandes, mas seguimos firmes, buscando soluções inovadoras para oferecer um atendimento ágil e prestativo. Se alguém solicita uma peça, seja no balcão ou na loja online, ela está sempre à mão. Nosso estoque conta com mais de 20.000 peças e acessórios, com qualidade e garantia asseguradas. Além de tudo, nossa equipe está sempre pronta para primeiro avaliar a causa e os danos no veículo, e aí, sim, sugerir as peças realmente necessárias e adequadas. Este tipo de cuidado você encontra aqui, na Dispemec. Um atendimento desses só é possível graças ao Programa de Capacitação Continuada da Dispemec, que prepara nossos especialistas com o que há de mais moderno no mercado. Isso significa ir além de “cumprir pedidos”, é prestar uma verdadeira consultoria. Há mais de 36 anos é assim, e sempre será. Para conquistar o reconhecimento dos maiores peritos no assunto. É isso o que torna a Dispemec uma das melhores autopeças do Brasil. ITENS INCLUSOS: 1 Filtro de combustivel; DESCRIÇÃO: O filtro de combustível Wega FCI1660 é um produto de alta qualidade e performance para garantir o bom funcionamento do motor do seu veículo. Esse filtro é ideal para quem busca manter a limpeza do combustível e proteger o sistema de injeção eletrônica, prolongando a vida útil do motor. Com tecnologia avançada, o filtro de combustível Wega FCI1660 é capaz de reter as impurezas e partículas presentes no combustível, impedindo que elas cheguem ao motor e causem danos. Além disso, o produto tem durabilidade superior, garantindo uma troca menos frequente em relação a outros filtros disponíveis no mercado. VEÍCULOS COMPATÍVEIS: Chevrolet: • Spin 2013 1.8 8V NLEV • Spin 2014 1.8 8V NLEV • Spin 2015 1.8 8V NLEV • Spin 2016 1.8 8V NLEV • Spin 2017 1.8 8V NLEV • Spin 2018 1.8 8V NLEV • Spin 2019 1.8 8V NLEV • Spin 2020 1.8 8V NLEV • Spin 2021 1.8 8V NLEV • Spin 2022 1.8 8V NLEV • Spin 2023 1.8 8V NLEV • Spin 2024 1.8 8Vundefined DADOS TÉCNICOS: similar kl582; GARANTIA: 2 meses Somos a Dispemec! A mais confiável loja de Autopeças que continua atendendo com excelência desde 1988. Dispemec, quem conhece, confia e compra.', 23.9, 23.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rash-mashzs4t6ltfae', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F819107232%2F23998574606', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
