INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799472398', 'Kit 3 Fitas Corretivas Deli 5mm x 12m Secagem Imediata Silenciosa Azul Verde Rosa', 'O Kit com 3 Fitas Corretivas Deli 5mm x 12m é ideal para correções rápidas, limpas e precisas no dia a dia. Com secagem imediata, permite escrever logo após a aplicação, sem borrões e sem necessidade de esperar. É indicado para uso escolar, escritório, estudos e anotações diárias. O produto possui estrutura silenciosa, aplicação suave e boa aderência ao papel, proporcionando uma correção mais uniforme e prática. A fita é resistente e não quebra com facilidade, oferecendo mais estabilidade durante o uso. Seu corpo leve e compacto facilita o manuseio, sendo uma ótima opção para estudantes, profissionais e uso doméstico. O kit inclui 3 cores em combinação: azul, verde e rosa, trazendo mais praticidade e um visual delicado e moderno. Marca: Deli Tipo: fita corretiva Medida: 5mm x 12m Quantidade: kit com 3 unidades Características: secagem imediata, estrutura silenciosa, correção suave, boa aderência Cores: azul Indicação: escola, escritório e uso diário Conteúdo da embalagem: 3 fitas corretivas Deli 5mm x 12m', 39.9, 26.9, NULL, 'Stationery > Writing & Correction > Eraser & Correction Supplies', 'https://cf.shopee.com.br/file/sg-11134201-823oc-mokl46whyd58ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1747380222%2F22799472398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41865044434', 'Tênis Feminino New Balance 460 V4 Original Confortável Estiloso', 'Tênis New Balance 460 V4 Modelo: W460V4 Foi desenvolvido para oferecer leveza, suporte e durabilidade no seu dia a dia e treinos. Sua entressola macia com amortecimento proporciona máximo conforto a cada passo, enquanto as sobreposições de sela garantem um suporte adicional para maior estabilidade. O cabedal possui uma estrutura sem costura, oferecendo um ajuste preciso e uma sensação elegante. Além disso, a sola de borracha durável proporciona excelente tração e resistência para acompanhar sua rotina com segurança e desempenho. Características: - Leve e Confortável: Ideal para o dia a dia e treinos. - Entressola Macia: Amortecimento que proporciona conforto a cada passo. - Sobreposições de Sela: Suporte adicional para mais estabilidade. - Cabedal Sem Costura: Ajuste preciso e sensação elegante. - Sola de Borracha Durável: Maior tração e resistência. - Drop Aproximado de 10 mm: Desenvolvido para melhor desempenho. Composição: - Cabedal: Têxtil e material sintético sem costura para conforto e ajuste preciso. - Entressola: EVA macio para amortecimento e suporte. - Palmilha: EVA para maior conforto durante o uso. - Solado: Borracha durável para tração e resistência. O Tênis New Balance 460 V4 pode ser encontrado aqui na Usee Brasil! Sobre a Usee Brasil: A Usee Brasil é uma empresa brasileira que oferece uma variedade de produtos de alta qualidade, desde roupas e acessórios até itens para casa. Tenha uma experiência conosco!', 399.99, 305.99, NULL, 'Sports & Outdoors > Sports Footwear > Running Shoes', 'https://cf.shopee.com.br/file/br-11134207-820lj-mo40gged5fr6ab', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1559054473%2F41865044434', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
