INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22096087014', 'Extensor p/Bit Magnético e Impacto 1/4 x 76mm - 48-32-4508 - Milwaukee', 'SHOCKWAVE 3 pol. Guia de acionamento magnético As guias de acionamento magnético Milwaukee SHOCKWAVE Impact Duty são projetadas para extrema durabilidade e vida útil de até 30x. Elas apresentam um shockzone otimizado que absorve o pico de torque e evita que elas se quebrem. A luva de aço inoxidável desliza sobre o fixador para maior estabilidade, enquanto o cano possui medidor de profundidade gravado a laser para maior controle do fixador. O guia de acionamento é magnético para segurar o fixador, enquanto um c-ring retém o bit de acionamento. CARACTERÍSTICAS: O SHOCKWAVE otimizado absorve o pico de torque e evita a quebra A manga de aço inoxidável se estende para maior estabilidade do fixador Medidor de profundidade gravado a laser para maior controle do fixador O ímã prende os fixadores ao guia de acionamento C-ring retém a broca de inserção O aço Alloy76 personalizado maximiza a resistência ao desgaste e ao choque Para uso com bits de driver de estilo de inserção de 1 pol. Não achou o que procurava ou ficou com dúvidas em relação ao produto? Entre em contato conosco.', 143.09, 143.09, NULL, 'Computers & Accessories > Network Components > Repeaters', 'https://cf.shopee.com.br/file/sg-11134201-7qvg1-libsvz4f5q7e70', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F998294051%2F22096087014', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
