INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '14372269496', 'Encosto de Espuma Nasa Viscoelastica Triangular Travesseiro Antivarizes Com Capa BF Colchões', 'O encosto de espuma visco elástica foi desenvolvido para quem precisa de um suporte firme sem perder a sensação de extrema maciez e conforto. Feito com uma camada superior de espuma Visco Elástica, a espuma criada pela NASA, com gomos massageadores que eliminam os pontos de pressão proporcionando uma instantânea sensação de conforto e relaxamento, suporte e durabilidade. A Almofada em formato de triangulo anatômico, ajuda a alinhar a coluna e a melhorar a postura ao ler amamentar ou simplesmente descansar. Virada ao contrario como apoio para os pés ajudará na circulação das pernas, evitando varizes e inchaço. Tecido respirável na parte de cima e nas laterais, que mantém uma temperatura agradável. Espuma Densidade 23 Com Selo Pró-Espuma de qualidade. Espuma superior de Viscoelástica com gomos massageadores. Revestimento: Parte superior e lateral 100 Poliéster E parte inferior 87 PVC, 13 Poliéster Contém: 01 Encosto Travesseiro 01 Capa Removível Dimensões: Altura: 32 cm Largura: 45 cm Profundidade 55 cm', 292.37, 219.0, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/br-11134201-7r98o-m1e6hhg8bucg09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F412482669%2F14372269496', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
