INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098110842', 'Tênis Olympikus Fitness Day Feminino Adulto Original', 'Tênis Day Caminhada Olympikus Modelo: 43927547 O Tênis Olympikus Day tem cabedal em tecido macio e sem costuras, fitas elásticas sobre o calcanhar e desenho com recortes na sola. A palmilha Feetpad, que memoriza o formato dos pés, e o solado com tecnologia Evasense garantem mais conforto e maciez. Onde usar seu Tênis Day da Olympikus? - Treinos; - Academia; - Caminhadas esportivas; - Atividades do dia a dia. Composição: cabedal em tecido macio e sem costuras, fitas elásticas sobre o calcanhar e desenho com recortes na sola. Palmilha com tecnologia Feetpad e solado com Evasense. Mas o que é EVASENSE? É uma tecnologia em EVA que gera alto nível de maciez e maior sensação de conforto. E o que é Feetpad? Palmilha composta por PU com memória viscoelástica, garantindo sensação de conforto. Adquira já o seu Olympikus Day Caminhada na Usee Brasil e experimente a diferença em cada passo!', 257.0, 229.99, NULL, 'Sports & Outdoors > Sports Footwear > Hiking Shoes', 'https://cf.shopee.com.br/file/br-11134207-820lg-mqnc78ue6nswc7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F349198275%2F22098110842', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58200173740', 'Cubo Roda Traseiro Com Rolamento Uno 1984 a 2009 Hipper Freios', 'Este anúncio contém: 01 - Cubo de roda traseiro com rolamento. Medidas: Diâmetro do furo do rolamento: 30mm; Quantidade de furos de fixação: 4. Aplicável nos seguintes veículos: Montadora: Fiat; Veículo: Uno; Motor: 1.0, 1.3, 1.5, 1.6 (Fire, Fiasa, Argentino); Ano de fabricação: 1984, 1985, 1986, 1987, 1988, 1989, 1990, 1991, 1992, 1993, 1994, 1995, 1996, 1997, 1998, 1999, 2000, 2001, 2002, 2003, 2004, 2005, 2006, 2007, 2008, 2009. Informações do produto: Marca: Hipper Freios; Número de peça: HFCT31. Sobre o produto: O cubo de boda é utilizado para fixação das rodas, discos e tambores, além de transmitir o movimento da junta homocinética para as rodas. Prevenção e Manutenção: As peças devem ser substituídas de acordo com as instruções do fabricante, sempre verificando as condições dos demais componentes do sistema, lembrando que choques mecânicos podem comprometer o funcionamento. Recomendações: Procure profissional especializado para instalação do produto adquirido; Não nos responsabilizamos por má instalação, uso inadequado do produto ou adaptações que não são compatíveis com a aplicação correta do produto segundo o fornecedor; Estamos à disposição para qualquer esclarecimento. Observações e condições da Loja: Antes de efetuar a compra, tire todas suas dúvidas no campo perguntas; Para peças mecânicas, confirme a aplicação com seu mecânico; Todos os nossos produtos são novos com garantia e nota fiscal; Todos os produtos anunciados estão disponíveis em nosso estoque; Para devolução de produtos, somente com embalagem original e Nota Fiscal. Sobre a Empresa: Somos autopeças especializada em linha leve, estamos localizados na zona sul de São Paulo capital. Visando a satisfação e bom atendimento para