INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21898886340', 'Kit Paleta de Sombras Power Glow + Brilho Labial Rosa Océane Edition (2 Produtos)', 'Quer Uma Maquiagem com Muito Brilho e Sofisticação? o Kit Paleta de Sombras Power Glow + Brilho Labial Rosa Océane Edition É Perfeito para Isso! a 4 Palette Edition Power Glow Foi Feita para Te Acompanhar Nas Makes Mais Básicas e Nas Mais Elaboradas, com Cores Elegantes, Muita Pigmentação e Fixação. o Glossy Me Océane Edition É Incrível para Completar a Sua Maquiagem em Qualquer Ocasião, a Fórmula Contém Esqualano para Você Cuidar Dos Lábios Enquanto Arrasa com Um Look Incrível. O Kit Paleta de Sombras Power Glow + Brilho Labial Rosa Océane Edition Contém: - 1 Paleta de Sombras – 4 Eyeshadow Palette Power Glow Océane Edition 4,5g - 1 Brilho Labial Rosa - Glossy Me Rose Océane Edition 4g 4 Palette Power Glow Océane Edition: Uma Paleta de Sombras com Cores Que Iluminam o Olhar É Um Item Indispensável No Nécessaire de Toda Mulher. Seu Formato Compacto É Ideal para Ser Levado com Você em Qualquer Cantinho, Na Bolsa, Na Mochila ou Na Mala de Viagem. Por Ser Pequena, Resistente, e Conter Um Espelho Embutido, Ela Também É Uma Ótima Aliada para Aqueles Retoques de Última Hora No Visual. Conheça As Cores da Paleta de Sombras Power Glow: Pearl Vanilla: O Charme e a Sutileza da Baunilha em Um Tom Cintilante Que É Perfeito para Criar Um Olhar Iluminado ou Bem Marcado. Eletric Pink: Uma Tonalidade Solar e Deslumbrante, Formulada com Pigmento Prensado. Um Furta-Cor Que Combina Bem com Os Tons Terrosos Que Acompanham a Paleta. Terracota: Para Uma Make Quente, Suave e Marcante, Essa Tonalidade Matte Que Mistura Tons de Laranja e Marrom Traz Vida e Requinte para a Make. Peach: Um Tom de Nude em Acabamento Matte, Indispensável em Qualquer Nécessaire para Garantir Uma Make Discreta, Natural e Iluminada. Brilho Labial Glossy Me Rose: Ótimo Aliado para Ter em Seu Nécessaire, o Brilho Labial É Aquele Item Perfeito para Dar Um Up Nos Lábios em Qualquer Ocasião. Seja para Deixar o Seu Look Ainda Mais Versátil e Sedutor, ou para Acrescentar Aquela Cor Natural Aos Lábios, Aposte Neste Gloss Océane! Quer Chamar a Atenção para Os Seus Lábios Na Make? Opte Por Brilho, Cor e Luminosidade! Glossy Me Océane Entrega Tudo Isso e Ainda Tem Mais: a Fórmula Contém Esqualano, Um Ativo Hidratante, para Você Cuidar Dos Lábios Enquanto Arrasa com Um Look Incrível. Sua Tonalidade Rose É Clássica e Versátil. Glossy Me É Aquele Tom de Rosa Coringa Que Realça a Sua Personalidade Marcante. e o Melhor: Combina com Toda Make!', 159.9, 149.9, NULL, 'Beauty > Beauty Sets & Packages', 'https://cf.shopee.com.br/file/sg-11134201-824h4-mpe61ixxkqgxc2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F842559166%2F21898886340', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
