INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198209814', 'Par Palheta Limpador Parabrisa Bosch Ranger 2017 A 2019 Chuva', 'JOGO DE PALHETA AEROFIT MULTICLIP BOSCH 01 - Palheta Bosch lado motorista 24"/ 60CM 01 - Palheta Bosch lado passageiro 15"/38CM Alta Performance e Segurança Garantidas com Palhetas BOSCH Compatível com os seguintes modelos: FORD RANGER 2017 A 2022 Experimente o melhor em eficiência, segurança e durabilidade com as palhetas BOSCH Aerofit Multiclip. Projetadas para proporcionar uma visibilidade clara em todas as condições climáticas, estas palhetas oferecem um desempenho superior que você pode confiar. Especificações: -Kit composto por 1 Palheta Multiclip lado direito e 1 Palheta Multiclip lado esquerdo BOSCH Aerofit Original. -Até 5 adaptadores inclusos para fácil instalação em diversos modelos de veículos. -Livre de partes metálicas expostas, evitando desgaste de pintura e corrosão. -Spoiler aerodinâmico para distribuição uniforme de força e estabilidade em altas velocidades. -Funcionamento ultra suave com tratamento de grafite, sem ruídos ou trepidações. -Embalagem moderna e atrativa. Perguntas Frequentes: Quando devo trocar as Palhetas do meu carro? Troque ao primeiro sinal de desgaste para manter a visibilidade ideal. Quais os sinais de desgaste da palheta? Barulhos durante o uso, falhas na limpeza do para-brisa, entre outros. Qual o prazo para a substituição das Palhetas? Recomenda-se trocar anualmente para garantir a eficiência. Nota: As Palhetas BOSCH são originais, adquira com confiança e acompanhe com Nota Fiscal. Em caso de dúvidas sobre o modelo correto, pergunte abaixo. Garanta a segurança da sua família. Compre Palhetas Originais BOSCH Aerofit. Esse anúncio revisado foca em destacar os benefícios do produto, fornece informações claras sobre a compatibilidade com diferentes modelos de veículos e responde às perguntas frequentes dos potenciais compradores.', 159.97, 159.97, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rcbs-m6cohia13oyf08', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F372102753%2F23198209814', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22098035716', 'Colchão Casal 138cm Mola Texas Gazin', 'O Colchão Casal 138cm Mola Texas Gazin com molas ensacadas soft pillow, possui o revestimento superior é confeccionado em malha, um tecido mais poroso que favorece uma ventilação aprimorada, proporcionando conforto térmico e uma sensação macia ao toque. O revestimento superior também é elaborado em tecido plano, que não propicia o acúmulo de poeira e materiais orgânicos, sendo de fácil higienização. Este produto apresenta excelente custo-benefício. Os lados são revestidos com tecido suede linho, caracterizado por sua elevada resistência, durabilidade e beleza. Características: Estrutura em matelassê malha, fibra siliconada, manta D28 e matelassê tecido plano Molas ensacadas soft pillow Revestimento Superior em malha Revestimento Lateral tecido suede linho Revestimento Inferior em malha EPS Suporta peso até 120kg Dimensões: Altura: 29 cm Largura: 138 cm Profundidade: 188 cm Peso: 22,35 kg Garantia do fornecedor de 3 meses', 939.9, 855.9, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7ren6-m2axbpv6l60wb6', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1329429906%2F22098035716', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
