INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '24433794979', 'AMPLE:N Ampola De Ceramida /100ml, 30ml', 'Ampola de tiro de ceramida 30ml / 100ml Sobre este item Enriquecido COM Cera Complex: O Sérum Coreana Ceramida Shot contém Cera Complex 50.000ppm que dá energia hidratante à pele baixa e sensível. Este soro de ceramida é absorvido pela pele para incentivar a biossíntese lipídica e hidratar a pele por dentro. Acompanha BARRIA DE UMIDADE: Este soro hidratante com Ceramida e a alantoína fortalece a barreira de umidade da pele para evitar a perda de umidade. O nosso soro facial suaviza e protege a pele do ambiente externo para mantê-la macia, flexível e hidratada. Sérum de barreira cutânea com Arctigenin não MAIS SECAGEM: Este sérum de barreira cutânea intensiva com Arctigenin mantém a pele nutrida e hidratada ao longo do dia. O blend de nutrientes essenciais em nosso soro de confirmação facial ajuda você a se livrar de sinais de envelhecimento e impede que a pele fique seca e flexível. Para TODOS OS TIPOS DE PELE: Este ingrediente hidratante antienvelhecimento para cuidados com a pele é formulado sem fragrâncias e cores artificiais, parabenos ou óleos essenciais, tornando-a perfeita para qualquer tipo de pele. A fórmula não oleosa torna-o ideal para peles sensíveis e irritadas. Modo DE USAR: Após o uso do toner, pegue uma quantidade adequada do Sérum Coreana Ceramide Shot e espalhe suavemente em todo o rosto para absorção. O soro facial leve e não pegajoso ajuda a manter o equilíbrio do pH e prepara-o para melhor absorção de nutrientes.', 118.66, 118.66, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-7rdwj-lxvxlhgxm1l6eb', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F24433794979', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
