INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '10642336588', 'Rolo para Pintura Lã Master Plus 22MMx23CM s/cabo - Castor', 'O Rolo para Pintura Master Plus 22 mm x 23 cm sem cabo Castor, apresenta alto rendimento e eficiência no alastramento da tinta, ótimos resultados na cobertura das superfícies porosas e irregulares, boa absorção e retenção da tinta, é super-resistente e durável. CARACTERÍSTICAS Superfície Indicada: Rugosas, Semirrugosas e Texturas Tipo de Tinta: Latéx PVA e Acrílicas Acompanha Cabo: Não Altura da Lã: 22 mm Instruções de Limpeza: Após o uso, retire o excesso de tinta em água corrente. Tintas látex pva ou acrílicas, lavar com água e sabão. Secar à sombra. Guardar em local arejado. Ambiente: sala de estar e jantar, quarto, hall, escritório e garagem. Código do fabricante: 431 FERRAMENTAS QUE TRANSFORMAM Transformar qualquer ambiente de forma rápida e sem muita sujeira, é isso que a linha de rolos para pintura da Castor traz para você. SEGURANÇA Compre com segurança! Nossa equipe de suporte estará à disposição caso tenha algum problema ou dúvida. Aguardamos seu pedido!', 29.81, 29.81, NULL, 'Home & Living > Tools & Home Improvement > Wall Paints & Coatings', 'https://cf.shopee.com.br/file/05598ecd0a784a69e1cd5913d3df6e57', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F524472372%2F10642336588', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
