INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23398146202', 'Cubo Roda Traseira Titan Fan 150 160 Start 150 160 Fabreck/Unibreq Primeira Linha Modelo Original', 'TAMBOR DE FREIO TRASEIRO - FABRECK/UNIBREQ CÓDIGO: 324 Compatível: Titan 150 Titan 160 Fan 150 Fan 160 Start (Todos os anos) Sendo líder de mercado, os cubos são confeccionados em liga de alumínio especial e com pintura no padrão da original, além de serem produzidos em modernos equipamentos de usinagem, proporcionam grande durabilidade e resistência do produto. Conservação Os cuidados para conservação tanto no seu aspecto quanto na prevenção contra a oxidação, devem considerar a limpeza frequente com água e sabão neutro aplicados com pano ou esponja macia. A montagem e desmontagem do pneu deve ser realizada por profissional experiente e com equipamento adequado. Nunca utilize materiais abrasivos ou produtos químicos para limpeza.', 154.9, 139.41, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Motorcycle Wheels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m54maq09ilki4f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1421013142%2F23398146202', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
