INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '44756013127', '3 CAKE BOX PÁSCOA CENOURA C/ TAMPA (750 mL) CRISTAL- (BLUE STAR)(CHOCO)', 'A CAKE BOX CENOURA 750ML FOI DESENVOLVIDA PARA TRANSFORMAR SOBREMESAS EM VERDADEIROS PRESENTES DE PÁSCOA. COM DESIGN TEMÁTICO E FORMATO ENCANTADOR, É IDEAL PARA MONTAR DOCES EM CAMADAS, BROWNIES RECHEADOS, BOLOS NO POTE E SOBREMESAS CRIATIVAS. SUA TRANSPARÊNCIA VALORIZA CADA DETALHE DA PRODUÇÃO, AUMENTANDO O VALOR PERCEBIDO NO PONTO DE VENDA. POSSUI TAMPA ALTA, PERFEITA PARA ACABAMENTOS MAIS ELABORADOS, E ENCAIXE SEGURO QUE FACILITA O TRANSPORTE E O DELIVERY. UMA EMBALAGEM PENSADA PARA ENCANTAR, DIFERENCIAR E IMPULSIONAR AS VENDAS NA PÁSCOA.', 46.85, 44.51, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/br-11134207-81ztc-mkigg9cvzhtu09', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F44756013127', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
