INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '50456428330', '2 FONDUE CAKE BOX PETISQUEIRA COELHO PÁSCOA CREME (BLUE STAR) (CHOCO)', 'Petisqueira Coelho 1,3L Encante sua mesa com a Petisqueira Coelho Creme, perfeita para servir petiscos de forma prática e cheia de charme. Com design lúdico em formato de coelhinho, ela é ideal para ocasiões especiais como a Páscoa, festas temáticas, cafés da tarde ou até para uso no dia a dia. Produzida em material resistente e de fácil limpeza, a petisqueira possui divisórias internas, permitindo organizar diferentes tipos de petiscos, doces, chocolates, castanhas ou snacks sem misturar sabores. Sua cor creme neutra combina facilmente com diversas decorações, enquanto a tampa transparente com formato de coelho protege os alimentos e valoriza a apresentação. Uma peça funcional, decorativa e versátil, perfeita para quem busca unir praticidade e um toque especial na mesa. Ideal para: Petiscos e aperitivos Doces e chocolates Datas comemorativas (especialmente Páscoa) Presentes criativos e decoração de mesa.', 58.85, 55.91, NULL, 'Home & Living > Home Organizers > Storage Boxes, Bags & Baskets', 'https://cf.shopee.com.br/file/sg-11134201-8261t-ml4uct8c4zda30', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F455834389%2F50456428330', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
