INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22103778987', 'Lux Led Mini 20.000 Lumensh4 Hb4 Hb5 9006 9007', 'Par de Lâmpadas Super Led – 20000 Lumêns e 6500k Amplie a projeção e alcance de luz com a tecnologia LED, com o par de lâmpadas super LED de tecnologia Alemã, trazendo maior segurança e visibilidade durante a direção noturna com efeito Xenon. As lâmpadas não requerem utilização de reator, possui coloração branca e sistema de arrefecimento com dissipador de calor. PAR DE LÂMPADAS SUPER LED V10 Especificações Técnicas: • Tecnologia Alemã. • Design Compacto. • Tonalidade: 6500K (Kelvins) Extremamente Branca. • Resistente a Água. • Base e Corpo da Lâmpada em Metal. • Eficiência de 20000 Lúmens do Par. • Longa Vida Útil, Dura Até 2 Vezes Mais que as Lâmpadas LEDs Convencionais • Potência máxima de 30 Watts. • Economiza a Bateria • Resistente ao Calor • Excelente Resistência a Vibrações e Emissão de Luz Estável. • Opera em 12V. • Chip Importado de Alta Potência. • Mais Segurança e Eficiência. • Efeito Xenon • Fonte embutida Modelos: H4 HB4 / 9006 HB5 / 9007 Dimensões: Altura: 85mm (8,5cm) Largura: 35mm (3,5cm) Conteúdo da Embalagem: - Par de Lâmpadas Super Led V10 Min - 2 Chicotes', 63.84, 54.72, NULL, 'Spare Parts and Accessories for Vehicles > External Accessories for Automobiles > Tuning', 'https://cf.shopee.com.br/file/sg-11134201-22110-45t9rhuyogjv6d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F22103778987', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '11912382369', '01 Driver Triton 505 Trio 320w 160w Rms 8 Ohm Fenólico 405', '# OESTESOM # 01 Drivers Triton 505 trio 320w 160w Rms 8 Ohms Fenólico 4 polegadas Seu conjunto magnético especiamente projetado para tirar o máximo de desempenho da bobina de voz de cobre com tamanho de 4 polegadas. Além disso, é montado com uma carcaça toda em alumínio, que garante uma melhor dissipação do calor e consequentemente melhor desempenho em sua utilização por diversas horas. A Triton projetou este driver fenólico pensando não só no exelente desempenho, mas também na praticidade de uso e custo x benefício do produto, por isso conta com um reparo de troca rápida e fácil de se encontrar no e um valor exelente para quem quer um driver de alto desempenho. Informações Técnicas: Diâmetro da boca: 50mm ( 2”) Resposta em frequência: 300Hz a 6.5kHz Impedância nominal: 8 Ohms Potência de pico: 320 W PMPO Potência nominal: 160 W RMS Sensibilidade: 110 dB SPL Frequência de corte mínima: 500Hz (12dB/8ª) Bobina: Material do fio: CCAW Seção do fio: Redondo Material da forma: Kapton® Re: 6,1 Ohms Diâmetro: 4’’ Material da estrutura: Aço Material da tampa Alumínio Volume Total: 2,5 L Peso Total: 7,81 kg Material do imã: Ferrite Dimensão do imã: 200 x 24 mm Peso do imã: 2,65 kg Densidade de Fluxo no gap: 1,59 T OESTESOM A MELHOR LOJA DE PRODUTOS AUTOMOTIVOS NA INTERNET!', 1013.33, 901.87, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > Car Audio System', 'https://cf.shopee.com.br/file/2ff8c36e4fcefeef89aaac092572fc19', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F328179142%2F11912382369', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22793204901', 'Kit Sortido 6 Peças de Roupas Infantil Bebê Menino(3 Camisas + 3 Calças)Kit 3 Conjuntos Meia Estação', 'Kit Sortidos 3 Conjuntos Meia Estação para Bebê Menino! 👕🩳 Ideal para manter seus pequenos confortáveis e estilosos em qualquer ocasião! ✅ Conjunto Meia Estação Completo: 3 camisetas manga longa + 3 calças. ✅ Camisetas Manga Longa: Meia malha 100% algodão, maciez e conforto ao toque. ✅ Calças: Mínimo 60% Algodão, com punho elástico na barra e elástico na cintura. ✅ Estampas variadas e encantadoras: Muita praticidade e estilo em uma única compra. Sugestão de Tamanho por Idade: Tamanho 1: Indicado para 6 a 12 meses Tamanho 2: Ideal para 1 ano Tamanho 3: Ótimo para 2 anos Tamanho 4: Excelente para 3 anos Tamanho 6: Ideal para 4/5 anos Tamanho 8: Perfeito para 6/7 anos Tamanho 10: Excelente para 8/9 anos Os tamanhos podem variar de acordo com o biotipo/tamanho de cada criança. 👉 Consulte a tabela de medidas nas imagens, ou na guia de tamanho da Shopee. IMPORTANTE! ⚠️ Não há opção de escolha dos modelos. ⚠️ Os modelos enviados serão sortidos conforme a disponibilidade em estoque. ⚠️ Na compra de múltiplos kits do mesmo tamanho, poderá haver repetição de cor ou estampa. Envios em 24 horas 🚛 - Para todos os pedidos realizados antes das 13h. Garanta já o seu kit e proporcione o máximo de conforto e estilo para seu príncipe!', 205.9, 72.9, NULL, 'Baby & Kids Fashion > Baby Clothes > Sets', 'https://cf.shopee.com.br/file/br-11134207-820ma-mmkgyvn5m1vq87', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F341167297%2F22793204901', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
