INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22093731007', 'Kit Embreagem - Fiat Uno 1.0 8V 2010 2011 2012 2013 2014 2015 2016 2017 2018 2019 2020 2021 2022', 'CONTEÚDO DA EMBALAGEM (KIT): 01 KIT EMBREAGEM 190MM/20ESTRIAS, COM PLATÔ, DISCO E ROLAMENTO - SACHS CÓD. 6586 PRODUTOS NOVOS, ORIGINAIS, COM GARANTIA E NOTA FISCAL. APLICAÇÃO: FIAT PALIO FIRE E EVO 1.0 8/16V 1996/2022 FIAT PALIO FIRE 1.3 8V TODOS MODELOS FIAT PALIO 1.4 8V FIRE EVO 2010/2022 FIAT SIENA 1.0 8/16V 1996/2016 FIAT SIENA 1.3 8/16V TODOS MODELOS FIAT SIENA 1.4 2004/2016 FIAT STRADA 1.3 8V FIRE TODOS MODELOS FIAT STRADA 1.4 8V 2004/2022 FIAT UNO 1.0 8V 1996/2022 FIAT UNO 1.4 2010/2022 FIAT MOBI 1.0 8V TODOS MODELOS FIAT IDEA 1.4 8V 2006/2016 FIAT DOBLO 1.3 16V TODOS MODELOS FIAT DOBLO 1.4 8V TODOS MODELOS FIAT FIORINO 1.3 FIRE TODOS MODELOS FIAT FIORINO 1.4 8V TODOS MODELOS FIAT PUNTO 1.4 8V FIRE FIAT GRAND SIENA 1.0 8V REFERÊNCIAS: 619301500 LUK / 6586 SACHS / 46743928 FIAT OEM / 46810287 FIAT OEM / 828102 VALEO ATENÇÃO: A RESPONSABILIDADE DA COMPATIBILIDADE DO PRODUTO E SUA APLICAÇÃO É DO COMPRADOR; NÃO NOS RESPONSABILIZAMOS POR PREJUÍZOS ADVINDOS DA APLICAÇÃO INCORRETA DO PRODUTO. CONSULTE O FABRICANTE DO SEU EQUIPAMENTO E CONFIRME A COMPATIBILIDADE COM O INSTALADOR. A MARTINS AUTOPEÇAS DISPÕE DE PEÇAS AUTOMOTIVAS PARA TODA A LINHA LEVE E MÉDIA DE VEÍCULOS, SE NÃO ENCONTRAR O QUE PROCURA, DEIXE UMA PERGUNTA E RESPONDEREMOS O MAIS BREVE POSSÍVEL.', 431.72, 431.72, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Transmission', 'https://cf.shopee.com.br/file/sg-11134201-7rccm-m6cjm2a9ty0b8a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F538200526%2F22093731007', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '42978984319', 'Como Evitar Preocupações e Começar a Viver | Dale Carnegie', 'Como Evitar Preocupações e Começar a Viver, de Dale Carnegie, é um clássico atemporal que ajuda o leitor a lidar melhor com as preocupações do dia a dia e a desenvolver uma vida mais leve e equilibrada. A obra apresenta técnicas comprovadas para superar a ansiedade e o estresse, oferecendo caminhos práticos para alcançar maior bem-estar mental e emocional. Com uma abordagem clara e acessível, o livro ensina métodos simples para mudar a forma de pensar, enfrentar desafios com mais serenidade e focar no que realmente importa na vida. Uma leitura transformadora para quem deseja viver de forma mais plena, tranquila e consciente. Título: Como Evitar Preocupações e Começar a Viver Autor: Dale Carnegie Número de páginas: 416 Acabamento: Capa brochura Dimensões: 14 x 21 cm Editora: Pé da Letra', 17.9, 17.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-8262e-mlc2buyx9ngi71', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F42978984319', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23898061441', 'Amortecedor Mola a Gás Do Capo Sandero Logan 2013 14 A 22 2023', 'ATENÇÃO: Valor Referente a 1 peça, caso queira solcitar um anúncio com o par de amortecedores, nos contate atraves do campo de perguntas!! O amortecedor a gás é uma peça importante do sistema de amortecimento de um veículo, responsável por apoiar e controlar o movimento da tampa do porta-malas, capô (motor) ou vidro traseiro Ele absorve as vibrações e efeitos, garantindo a segurança e estabilidade da tampa do capô, além de evitar ruídos indesejáveis durante a condução. Como instalar amortecedor a gás: Preparação: Antes de começar a instalação, você precisará apenas de uma chave de fenda. Além disso, verifique se o amortecedor que você adquiriu é compatível com o modelo e ano do seu veículo. Remoção do amortecedor antigo: para remover o amortecedor antigo, você precisará folgar as travas dos encaixes com a chave de fenda. Em seguida, retire o amortecedor antigo e guarde-o. Instalação do novo amortecedor: para instalar o novo amortecedor, basta posicioná-lo na mesma posição do antigo e fazer o encaixe com pressão. Certifique-se de que os encaixes estão seguros e corretos. Teste: após instalar o novo amortecedor, teste se ele está funcionando corretamente, abrindo e fechando o porta-malas, capô ou vidro traseiro várias vezes. Verifique se o porta-malas, capô ou vidro traseiro abre e fecha de maneira controlada e segura. Finalização: caso tudo esteja funcionando corretamente, basta fechar o porta-malas, capô ou vidro traseiro e verificar se ele está preso de maneira segura. Pronto, sua instalação de amortecedor a gás está concluída! Obs.: Tenha cuidado ao manusear as peças e ferramentas durante a instalação. Se você tiver dúvidas ou inseguranças, é sempre recomendável procurar ajuda de um profissional especializado em manutenção automotiva. Renault Sandero 2014 Renault Sandero 2015 Renault Sandero 2016 Renault Sandero 2017 Renault Sandero 2018 Renault Sandero 2019 Renault Sandero 2020 Renault Sandero 2021 Renault Sandero 2022 Renault Sandero 2023 Renault Logan 2014 Renault Logan 2015 Renault Logan 2016 Renault Logan 2017 Renault Logan 2018 Renault Logan 2019 Renault Logan 2020 Renault Logan 2021 Renault Logan 2022 Renault Logan 2023 Características: Marca; Cinoy Cor: Preto Fixação: Por encaixe Produto: Novo', 31.8, 30.21, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > External Parts', 'https://cf.shopee.com.br/file/sg-11134201-7rd4h-m7gvyb5bxc8l1f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F800059202%2F23898061441', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28944776857', 'Bebedouro De Coluna Esmaltec EGC35B 1,8 Litros 127V Branco Com Compressor E Termostato', 'O Bebedouro de Coluna Esmaltec EGC35B Branco 127V é um aparelho projetado para fornecer água refrigerada de forma prática e eficiente. Ideal para diversos ambientes, ele garante acesso facilitado à água em temperatura agradável. Este bebedouro conta com um sistema de refrigeração por compressor, que assegura a manutenção da temperatura da água gelada entre 5°C e 15°C. Sua capacidade de reservatório de 1,8 litros atende às necessidades diárias de consumo. Com um design funcional, o bebedouro Esmaltec EGC35B oferece facilidade de uso e contribui para a hidratação contínua em residências, escritórios ou áreas de convivência. A temperatura da água pode ser ajustada por um termostato frontal. BENEFÍCIOS Sistema de refrigeração por compressor para água sempre gelada Controle gradual de temperatura para ajuste personalizado Reservatório de 1,8 litros para abastecimento contínuo Bandeja coletora removível para facilitar a limpeza Design de coluna que otimiza o espaço Fornecimento de água em temperaturas ideais para consumo Operação eficiente para uso diário CARACTERÍSTICAS TÉCNICAS Marca: Esmaltec Modelo: EGC35B Tipo de produto: Bebedouro de Coluna Capacidade Total: 1,8 litros Voltagem: 127 V Cor: Branco Tipo de instalação: Coluna RECURSOS E FUNCIONALIDADES Sistema de refrigeração: Compressor Temperatura da Água Gelada: Entre 5°C e 15°C Controle de Temperatura: Termostato frontal com controle gradual de temperatura Sistema Easy Open: Removível Bandeja coletora: Removível CAPACIDADE E ORGANIZAÇÃO INTERNA Capacidade do reservatório: 1,8 litros Temperaturas disponíveis: Água gelada Tipo de galão: Compatível com galões padrão INSTALAÇÃO E REQUISITOS Voltagem: 127 V Tipo de instalação: Coluna Ponto de energia: Próximo ao local de instalação Local de instalação: Superfície plana e nivelada CONTEÚDO DA EMBALAGEM 1 Bebedouro de Coluna Esmaltec EGC35B 1 Manual de instruções CUIDADOS COM O PRODUTO Realizar a limpeza externa regularmente com pano úmido Higienizar o reservatório de água periodicamente Manter o aparelho afastado de fontes de calor Garantir espaço para ventilação na parte traseira Seguir as instruções do fabricante para manutenção Desligar o bebedouro da tomada antes de qualquer limpeza DIMENSÕES DO PRODUTO Altura: 100 cm Largura: 31 cm Profundidade: 32 cm Peso do produto: 11.58 kg DIMENSÕES DA EMBALAGEM Altura da embalagem: 101 cm Largura da embalagem: 32 cm Profundidade da embalagem: 34 cm Peso bruto: 12.6 kg INFORMAÇÕES IMPORTANTES Verificar a voltagem (127V) antes da instalação Instalar o produto em local nivelado Não utilizar produtos abrasivos na limpeza', 1059.9, 879.9, NULL, 'Home Appliances > Kitchen Appliances > Water Filters, Coolers & Dispensers', 'https://cf.shopee.com.br/file/sg-11134201-820my-mnzsce1g3eh22f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1296760327%2F28944776857', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23096715749', 'Toalha De Secagem Ultra Vonixx 70x120 400gsm Cor Azul', 'TOALHA DE SECAGEM ULTRA VONIXX 70x120cm 400GSM Descrição Geral A Toalha de Secagem Ultra Vonixx é composta por microfibras que evitam atrito com a superfície. Sua gramatura maior proporciona alto poder de absorção ao tecido. TAMANHO 70x120cm GRAMATURA 400GSM MATERIAL 80% Poliéster/ 20% Poliamida INFORMAÇÕES ADICIONAIS Pensando em uma melhor proteção para o produto, a fim de evitar contato com diversas sujidades e melhor armazenamento, desenvolvemos uma embalagem prática em zip lock com fecho hermético. NÃO RISCA SUPER MACIA ALTA ABSORÇÃO', 71.19, 71.19, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Towels', 'https://cf.shopee.com.br/file/br-11134207-7r98o-ll1368o8nble11', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F23096715749', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22123127114', 'Composto Polidor para Corte Fast Cut 1KG Autoamerica', 'Composto Polidor para Corte Fast Cut 1KG Autoamerica PRONTO PARA USO O Composto Polidor para Corte Fast Cut 1KG Autoamerica é um polidor composto de corte que remove marcas de lixa 1200. Com composição à base de água, produz ótimos resultados quando usado com lã agressiva ou boinas híbridas, de lã ou de espuma. Adequado para pintura original e repintada. Corte rápido e limpo. - À base de água; - Fácil remoção; - Corte 10; - Brilho 8; Fácil de aplicar, não embaça, alto brilho, alto rendimento, baixo desgaste do disco, não mancha plásticos e borracha. Para usar, trabalhe em superfície fria e limpa, escolha uma boina de estágio de corte para polidora rotativa ou roto orbital, aplique em áreas de 50x50 cm, após o polimento retire o excesso com Autoamerica IPA e um pano de microfibra limpo, se ainda houver marcas repita o procedimento processo. _________________________________________________________________ OBSERVAÇÕES: - Confira o seu endereço de entrega cadastrado; - Produto original de excelente qualidade; - Compra 100% Segura; - Produtos bem embalados e protegidos. _________________________________________________________________ Há mais de 12 anos no ramo de RODAS, PNEUS E PEÇAS AUTOMOTIVAS. Atendimento 100% personalizado. CERIOLLI SHOP ______________________________________________________________', 68.9, 68.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Polisher', 'https://cf.shopee.com.br/file/sg-11134201-7rbkr-lnkg6j0agw1dbe', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F944273111%2F22123127114', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22992971475', 'MOLDURA PARA CENTRAL MULTIMIDIA MP5 7 POL 2 DIN MONTANA VECTRA CORSA 2002 A 2012 CORES', 'A nossa moldura Chevrolet possui um padrão 2 din e tamanho de 7 polegadas. É fabricada em plástico ABS (acrilonitrila butadieno estireno), o que garante maior resistência a impactos e a temperaturas extremas. Esta moldura 2 din Chevrolet está disponível nas cores preta com acabamento fosco, prata e cinza. É compatível com: -Chevrolet Corsa 2002 – 2012; -Montana 2003 – 2009; -Vectra 2007 – 2011.', 28.9, 28.9, NULL, 'Spare Parts and Accessories for Vehicles > Internal Accessories for Automobiles > GPS Navigators', 'https://cf.shopee.com.br/file/sg-11134201-7rd5s-lufc62144isw9d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F379659661%2F22992971475', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22693511611', 'Sofá Sala de Estar 02 Lugares Beny Suede Verde Madeira Estofados', 'Sofá Beny 02 Lugares Transforme sua sala em um ambiente ainda mais acolhedor e sofisticado com o Sofá Beny. Desenvolvido para unir design moderno, conforto e durabilidade, ele é a escolha ideal para quem busca um móvel elegante sem abrir mão da resistência e da qualidade. Sua estrutura em madeira de eucalipto garante alta durabilidade e excelente sustentação, enquanto a base com pés em formato trapézio proporciona estabilidade e um visual contemporâneo que valoriza qualquer ambiente. O assento com espuma de densidade D26 oferece conforto equilibrado para o uso diário, e o encosto com almofadas macias proporciona uma experiência relaxante, ideal para momentos de descanso, leitura ou para receber visitas com muito mais comodidade. O sofá acompanha almofadas decorativas, que acrescentam charme e sofisticação ao ambiente, deixando sua sala ainda mais elegante. Seu revestimento em linho de alta qualidade garante um acabamento refinado e agradável ao toque, além de maior durabilidade. O Sofá Beny é perfeito para quem busca um móvel bonito, resistente e confortável para compor a decoração da casa. DIMENSÕES DO PRODUTO Altura total: 77 cm Largura total: 140 cm Profundidade total: 80 cm Altura do assento (do chão): 46 cm Profundidade do assento: 63 cm Largura do assento: 110 cm Altura do encosto: 34 cm Espessura do assento: 17 cm Altura dos pés: 13 cm Altura do braço (do chão): 70 cm Espessura do braço: 15 cm Altura interna do braço: 25 cm Peso total: 30 kg ESPECIFICAÇÕES DO PRODUTO Estrutura: Madeira de Eucalipto Espuma: Densidade D26 Tipo de pés: Trapézio Peso suportado: Até 180 kg Garantia: 90 dias contra defeitos de fabricação Montagem: Produto enviado praticamente montado, sendo necessário apenas rosquear os pés. Instruções de Limpeza: Para a limpeza, utilize apenas pano levemente úmido com sabão neutro. Evite produtos químicos abrasivos para preservar o tecido. Conteúdo da Embalagem: 01 Sofá Beny enviado em 01 volume OBSERVAÇÕES IMPORTANTES: Os produtos são cuidadosamente embalados para garantir segurança no transporte. As cores podem variar dependendo das configurações do seu monitor. Não garantimos a mesma tonalidade de cor para futuras compras devido à variação de lote do fabricante. As imagens são ilustrativas e não acompanham objetos de decoração ou eletrodomésticos. Certifique-se de que as dimensões do produto são compatíveis com escadas, elevadores, portas e corredores de sua residência. Por ser um produto estofado, as medidas podem ter variação de até 3 cm. A montagem, desmontagem ou instalação do produto não estão inclusas no serviço de entrega. A entrega não contempla subir escadas, elevadores ou uso de guinchos para pisos superiores. A entrega é realizada em todo o território nacional, conforme acessibilidade por rodovias; entregas fluviais ou aéreas devem ser cotadas à parte. Seguindo essas orientações, evitam-se contratempos com a entrega. Custos adicionais, se houver, são de responsabilidade do cliente. FAQ – PERGUNTAS FREQUENTES • O STATUS DO MEU PEDIDO APARECE COMO ENVIADO, MAS NÃO CONSIGO RASTREAR Após a confirmação da compra, todos os pedidos passam pelo nosso processo de produção. O prazo pode variar conforme o volume de pedidos e períodos de maior demanda, como datas comemorativas. Assim que o produto for despachado, o link de rastreamento será atualizado. Basta acessar o link disponibilizado para acompanhar o andamento da entrega. • ACABEI DE COMPRAR E COLOQUEI O ENDEREÇO ERRADO. PRECISO CANCELAR A COMPRA PARA ALTERAR? Não é necessário cancelar a compra. Conseguimos alterar o endereço em até 48 horas após a confirmação do pedido. Basta enviar pelo chat da sua compra o endereço completo com CEP para que possamos realizar a atualização. • QUAIS SÃO AS CORES E TECIDOS DISPONÍVEIS? No tecido Suede temos: Preto, Vermelho, Terracota, Bege, Azul Marinho, Rosa, Amarelo, Verde e Cinza. No tecido Linho temos: Bege, Grafite, Cinza, Azul Marinho, Preto, Terracota e Verde. No tecido Corino (pode haver diferença de valor): Bege, Marrom, Preto e Terracota. • VOCÊS FAZEM PRODUTOS COM MEDIDAS DIFERENTES DO ANÚNCIO OU PERSONALIZADOS? No momento, não fabricamos produtos sob medida e não realizamos personalização com outros materiais ou medidas diferentes das informadas no anúncio. • COLOQUEI MEU CEP E APARECE COMO ENDEREÇO NÃO SUPORTADO Infelizmente ainda não conseguimos realizar entregas em algumas regiões. Estamos trabalhando para ampliar nossa área de atendimento e, em breve, atender mais localidades em todo o Brasil.', 755.0, 755.0, NULL, 'Home & Living > Furniture > Sofas', 'https://cf.shopee.com.br/file/br-11134207-820lj-mnmzt6wqvnr8f0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1344250083%2F22693511611', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '45057143187', 'Aspirador 3 em 1 WDL1 150mBar 10L 1500W 110V Karcher', 'Loja do Mecânico - O que você precisa, nós temos! Aspirador de Pó e Água WDL1 Karcher, Potência e Versatilidade em um só produto. Ideal para limpezas domésticas e profissionais. Com seu design compacto e leve, ele oferece alto desempenho em diversas situações. Equipado com um motor potente de 1500W, este aspirador é capaz de remover eficientemente sujeiras secas e úmidas, tornando-o versátil para qualquer tipo de limpeza. Sua capacidade de 10 litros permite mais tempo de uso sem interrupções para esvaziamento. Com o aspirador você terá alcance total de 7,5 metros, incluindo cabo elétrico de 5 metros e três prolongadores. Com essa extensão generosa, você terá mais liberdade de movimento e poderá alcançar áreas mais distantes sem precisar trocar o equipamento de tomada. O WDL1 possui um sistema de filtros de fácil remoção e lavagem, garantindo maior durabilidade e economia. Além disso, suas rodas robustas e a prática alça de transporte proporcionam mobilidade, facilitando o uso em diferentes ambientes. O acessório de bocal para cantos e frestas garante uma limpeza detalhada até mesmo nos lugares de difícil acesso. Pó: Pode ser utilizado como aspirador de sujeira fina ou grossa, oferecendo excelente resultado de limpeza graças aos acessórios especiais e a alta capacidade de sucção. Líquido: Líquidos e sujeira úmida não são mais um problema, o aspirador WDL 1, é seu parceiro ideal devido a excelente capacidade de sucção, podendo ser utilizado em ambientes internos e externos. Sopro: Com a função soprador, esse equipamento é perfeito para afastar folhas, encher colchões de ar, boias de piscina, balões, acender churrasqueira, entre outros. Com essa característica, você terá um parceiro perfeito e eficiente para todas as funções do dia a dia. Especificações Técnicas - Modelo: WDL 1 - Tensão: 127V - Capacidade: 10L - Potência: 1500W - Vácuo máx.: 150mbar / 15kPa - Cabo elétrico: 5m - Alcance máx.: 7,5m Conteúdo da Embalagem - 01 Aspirador Pó e Água - 01 Bocal de Piso - 01 Bocal de Canto com escovas - 03 Tubos prolongadores - 01 Filtro de espuma - 01 filtro de pano lavável - 01 Mangueira de 1,5m Importante - Enviamos em até 24 horas úteis; - A embalagem pode variar de acordo com o estoque do fabricante; - A cor do produto pode variar de acordo com a tela do seu smartphone/computador; - Qualquer dúvida, utilize o campo "Perguntas e Respostas" e converse com o nosso SAC.', 413.99, 389.15, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-8260h-mlqkbh4drbi8e5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F902146556%2F45057143187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22893489289', 'Guarda-Sol 1,60m em Bagum e Alumínio Azul Marinho Bel', 'O Guarda-Sol em Bagum e Alumínio 1,60m Azul Marinho é indispensável para quem gosta de curtir os dias de sol e calor! Seja na praia, piscina, camping, jardim ou parque, esse guarda-sol irá proporcionar sombra e proteção para toda a família. Sua cobertura em bagum reforçado com FPS 100 vai garantir a diversão das crianças e adultos enquanto se protegem dos raios solares. Fácil de transportar e montar, sua haste é produzida em alumínio frisado de alta qualidade, garantindo maior segurança e facilidade para fixar na areia ou grama. O guarda-sol ainda conta com extra ventilação no topo, proporcionando mais resistência ao vento e maior estabilidade ao produto. O Guarda-Sol em Bagum e Alumínio 1,60m Azul Marinho é a escolha perfeita para te acompanhar nos seus momentos de férias e lazer! Informações: · Cobertura em bagum reforçado · Haste em alumínio frisado (alta qualidade) · Extra ventilação · Proteção real contra os raios solares: FPS 100 · Fabricação 100% nacional Medidas: · Altura total: 1,90 metros · Envergadura: 1,60 metros · Comprimento da haste: 1,01 metros', 216.72, 216.72, NULL, 'Sports & Outdoors > Sports & Outdoor Accessories > Umbrellas', 'https://cf.shopee.com.br/file/sg-11134201-7rase-maiskamv5bv440', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F22893489289', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22297171218', 'Soleira Dianteira Uno 84 a 2010 Prêmio Elba 84 a 96 4 Portas Acabamento De Porta', '🚀 ENVIO IMEDIATO — PRODUTO EM ESTOQUE NO BRASIL! ⚡ Produto disponível no Brasil com envio rápido após a confirmação do pagamento. 🛡️ A soleira da porta dianteira protege contra riscos e desgastes no uso diário, além de renovar o acabamento interno do veículo com encaixe perfeito e visual original. 🚗 Compatível com: Fiat – Uno (4 Portas) 1984 a 2010 Fiat – Prêmio / Elba (4 Portas) 1984 a 1996 Exceto Novo Uno ℹ️ Mais Informações: Cor: Preto Material: Plástico ABS de alta resistência Comprimento: 70 cm Aplicação: Porta dianteira Alta durabilidade Encaixe perfeito Excelente acabamento Ideal para reposição Produto novo, embalado e protegido 90 dias de garantia e suporte ao cliente 🏷️ Tags: #soleira #soleiraporta #soleirauno #soleirapremio #soleiraelba #pecasfiat #autopecas #reposicaoautomotiva #acabamentointerno #kyodaiacessorios', 21.61, 18.81, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rblh-loodhr88b3zre1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F22297171218', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41909445624', 'Polaina Parachoque Corce 2 Belina 2 1978 a 1986 Ponteira Traseira Preta Modelo Longo', 'Revise modelo, ano e lado nas fotos e tabela. Caso tenha qualquer dúvida ou note divergência, fale conosco pelo chat para ajustarmos seu pedido antes do envio e evitar devoluções. A Kyodai Acessórios é a número 1 em variedade e agilidade no segmento automotivo. Aqui você encontra produtos selecionados com a melhor qualidade e o MELHOR custo-benefício do mercado. Tudo pensado para quem exige confiança, eficiência e resultado. PRODUTO 1ª LINHA (NÃO É ORIGINAL) ** Compare o produto com a peça original de seu veículo antes de realizar a compra ** VISÃO GERAL: Polaina Ponteira Preta do Parachoque Traseiro Modelo Longo Para Ford Corcel 2 e Belina 2, Apenas Versões LDO COMPATÍVEL: Ford - Corcel 2 / Belina 2 (LDO) 1978 a 1986 ESPECIFICAÇÕES TÉCNICAS: Cor: Preta Aplicação: Traseira Modelo Longa Excelente Acabamento Revestimento Texturizado Não Acompanha Kit de Instalação A instalação deve ser feita por um profissional, pois a loja não se responsabiliza por uso inadequado ou montagem incorreta. As imagens são ilustrativas, e o uso de fotos ou vídeos da loja por terceiros não é permitido. Em caso de devolução, siga corretamente o processo dentro do prazo da plataforma e não encerre por conta própria, pois após o vencimento, os custos serão de responsabilidade do comprador.', 86.79, 81.59, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-820m4-mqp4n0n48g7403', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373280378%2F41909445624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18757312861', 'Boia Inflável Gigante Arco-Íris Bel', 'Boia Arco-Íris Inflável Bel – A Sensação do Verão! Com um design divertido e cheio de personalidade, ela é perfeita para relaxar e curtir momentos na água. ✔️ Design colorido e moderno em formato de arco-íris ✔️ Válvula de enchimento até 5x mais rápida ✔️ Produzida em Premium Vinyl, resistente e durável Transforme qualquer momento na água em uma experiência ainda mais divertida com a Boia Arco-Íris Inflável Bel! 🌈✨', 85.09, 85.09, NULL, 'Mom & Baby > Toys > Sports & Outdoor Play', 'https://cf.shopee.com.br/file/sg-11134201-824jk-mpmq0065mj9d64', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F757094384%2F18757312861', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22498854373', 'Lubrificante para Corrente de Moto Chain Lub City – 400ml – Sieger SL110', 'Top de Linha para Uso Diário. Alta aderência. Lubrificação precisa. O Chain Lub City SL110 é a graxa adesiva ideal para motos urbanas, garantindo proteção duradoura e desempenho consistente no vai e vem da cidade. Aplicações: - Correntes - Cabos - Alavancas de câmbio e freio - Rolamentos - Cavaletes - Pedais Não indicado para: motos com transmissão por eixo cardã ou correia dentada (nesse caso, o sistema não usa graxa). Benefícios: - Lubrifica e protege - Reduz desgaste - Resiste à água e ao calor - Evita falhas e travamentos Modo de uso: Agite bem, aplique na peça limpa e seca, e aguarde alguns minutos para secagem. Dica: Use o Chain Cleaner SC110 antes da aplicação para resultados superiores. Na nossa loja tem mais produtos campeões. Te esperamos!', 59.9, 39.9, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Care > Degreasers', 'https://cf.shopee.com.br/file/br-11134211-81z1k-mdxaqghi4n43ff', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1449962409%2F22498854373', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21097973929', 'Discos de Freio Fz15 150 Abs 2023 2024 + Pastilhas Diafrag Trail Cerâmica', 'Discos de Freio + Pastilhas Compatível com: YAMAHA FZ15 150 ABS 2023 FZ15 150 ABS 2024 Conteúdo da Embalagem: 01 Disco de Freio Dianteiro GP7 01 Disco de Freio Traseiro GP7 01 Par de Pastilhas de Freio Dianteira DIAFRAG Trail (Cerâmica, Sinterizada) 01 Par de Pastilhas de Freio Traseira DIAFRAG Trail (Cerâmica, Sinterizada) Disco Dianteiro: - Espessura 4mm - Código Original (OEM): 44C-F5805-00 Disco Traseiro: - Espessura: 4mm - Código Original (OEM): B97-F582W-00 Características dos Discos de Freio: - Produzidos em Aço Carbono de alta resistência ao desgaste; - Excelente frenagem e equilíbrio; - Discos ventilados que evitam o superaquecimento; - Frenagem mais complexa; - Aumenta a frenagem mesmo em terrenos úmidos; - Bom funcionamento do sistema de freios; - Qualidade Original; Especificações Técnicas das Pastilhas: - Sinterizada - Material: Cerâmica - Não agride os discos; - Alta durabilidade comparada as pastilhas orgânicas ou kevlar; - Durabilidade e qualidade; - Maior qualidade na frenagem; - Melhor opção para uso em terreno molhado, seco ou arenoso. Importante Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto. Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto.', 379.9, 303.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdxx-m1hdmt6xs8dycc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F21097973929', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '46800040817', 'Disco de Freio Dianteiro P/ Honda Biz 125 Gp7', 'Garanta sua segurança e performance com nosso Disco de Freio – troque e rode sem preocupações! Manter o sistema de freios em dia é essencial para a sua segurança. A troca do Disco evita desgaste irregular, garante melhor desempenho na frenagem e aumenta a durabilidade das peças. Com tudo novo, sua moto fica pronta para rodar com confiança e sem riscos Compatível com HONDA: BIZ 125 2006 BIZ 125 2007 BIZ 125 2008 BIZ 125 2009 BIZ 125 2010 BIZ 125 2011 BIZ 125 2012 BIZ 125 2013 BIZ 125 2014 BIZ 125 2015 Conteúdo da Embalagem: 01 Disco de Freio Dianteiro Gp7 Os Discos de Freio Gp7 Proporcionam: - Aumento de segurança - Ganho de eficiência na frenagem - Menor aquecimento e desgaste. Características do Disco de Freio: - Espessura: - Diâmetro Externo: - Quantidade de Furos: - Produzidos no padrão Original; - Excelente frenagem e equilíbrio; - Discos ventilados que evitam o superaquecimento; - Alta resistência ao desgaste; - Aumenta a frenagem mesmo em terrenos úmidos - Bom funcionamento do sistema de freios Importante !! - Recomendamos que a instalação seja feita por profissional especializado. - Não nos responsabilizamos pelo mau uso do produto.', 149.9, 119.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-82589-mg6hhuir7j7u1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F46800040817', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43312968641', 'Kit Pastilhas de Freio Cg 160 Titan Abs 2025-2026 Diafrag', 'Kit Pastilhas de Freio Diafrag Urban Tech As pastilhas de freio Dia-Frag Urban Tech oferecem vários benefícios, incluindo ótima capacidade de frenagem em diferentes condições de pista, excelente custo-benefício e progressividade do freio, além de não apresentar "fade" (perda de frenagem) ou ruídos. Compatível com HONDA: CG 160 TITAN ABS 2025 CG 160 TITAN ABS 2026 Conteúdo da Embalagem: 01 Par de Pastilhas de Freio Dianteira Diafrag Urban Tech (Orgânica) 01 Par de Pastilhas de Freio Traseira Diafrag Urban Tech (Orgânica) Especificações: - Modelo: Urban Tech (Orgânica) - Material: ferro / lona - Produzido com melhores equipamentos garantindo segurança e durabilidade. - Oferecendo o melhor custo beneficio, unindo qualidade e eficiência na sua utilidade. - Possui medidas originais - Melhor dissipação de calor e atrito com o disco de freio - Ideal Para Reposição - Maior segurança ao motociclista - Alta Qualidade E Resistência Principais benefícios: Excelente resposta de frenagem: As pastilhas oferecem ótima capacidade de frenagem tanto em pistas secas quanto molhadas, proporcionando segurança ao condutor. Ótimo custo-benefício: A relação qualidade e preço das pastilhas Dia-Frag Urban Tech é considerada alta, tornando-as uma opção econômica e eficiente. Progressividade do freio: As pastilhas garantem uma frenagem gradual e suave, evitando travagens bruscas e aumentando a segurança. Ausência de "fade" e ruídos: As pastilhas não apresentam perda de capacidade de frenagem em altas temperaturas ("fade") e não emitem ruídos durante a frenagem. Baixo desgaste do disco de freio: As pastilhas são projetadas para minimizar o desgaste do disco de freio, prolongando a vida útil do sistema de freio. Alto conforto na frenagem: A frenagem com as pastilhas Dia-Frag Urban Tech é suave e confortável, proporcionando uma experiência mais agradável ao condutor. Importante !! - Verifique, antes da compra, se as medidas das pastilhas são compatíveis com a da sua moto. - Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 79.9, 63.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Chassis', 'https://cf.shopee.com.br/file/sg-11134201-7rdyj-mdf2gv32b4ysc0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F43312968641', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '47556712851', 'Kit Junta do Cilindro + Junta do Cabeçote P/ Bajaj Dominar 400 Vedamotors', 'O Kit de Juntas Vedamotors oferece vedação perfeita, evita vazamentos e assegura durabilidade e eficiência na sua moto. Escolha qualidade e rode com confiança! O Kit de Juntas é essencial para manter o motor bem vedado, evitando vazamentos de óleo, água ou compressão. Ele garante o bom funcionamento do motor, preserva o desempenho, evita superaquecimento e aumenta a vida útil das peças internas. Sem uma boa vedação, o motor pode perder potência e sofrer danos graves. Compatível com BAJAJ: DOMINAR 400 2023 DOMINAR 400 2024 DOMINAR 400 2025 Conteúdo da Embalagem: 01 Junta do Cilindro Vedamotors 01 Junta do Cabeçote Vedamotors 01 Junta do Acionador de Corrente de Comando Vedamotors 01 Anel de Vedação do Escape Vedamotors Vantagens: - Economia de tempo da desmontagem do motor; - Não causa danos a saúde do mecânico por não conter amianto; - Fácil remoção (Não gruda) - Evita maiores danos nas tampas e carcaça do motor durante sua remoção, pois não necessita de estiletes ou lixas; - Fibras de aramida - Alta durabilidade e resistências à temperaturas elevadas. - Absorção de fluídos lubrificantes e líquidos de arrefecimento. (Mesmo material utilizado em colete à prova de balas). - Não necessita de silicone (Não necessita de nenhum tipo de silicone, cola ou componente químico em sua aplicação). - Dupla camada anti-stick (Evita a aderência do papel na carcaça e tampas do motor). Juntas Vedamotors fabricadas com matéria-prima do grupo Athena, oferecendo alta durabilidade, resistência a altas temperaturas, absorção de fluídos lubrificantes e líquido de arrefecimento. Não necessita de nenhum tipo de silicone, cola ou componente químico na sua montagem. A juntas possuem uma cama anti-stick que evita a aderência do papel na carcaça e tampas do motor. Juntas 100% sem amianto. Características: - Produto 100% Nacional - Produto desenvolvido com os mesmos parâmetros e encaixes do original, substituindo o mesmo sem nenhum problema ou adaptação. - Elaborado com matéria-prima de alta qualidade. - Testado e aprovado dentro das normas de segurança. Importante !! Antes de comprar, verifique o modelo compatível a sua moto. Para a instalação do produto corretamente, leve ao mecânico de sua confiança! Não nos responsabilizamos pelo mau uso do produto.', 289.9, 246.42, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-8260b-mldnchgm172ce9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F47556712851', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '15761361019', 'Chave de Ignição Cg 125 Fan 2009 A 2013 Magnetron', 'Chave de Ignição MAGNETRON Conteúdo embalagem: 01 Miolo de Ignição 02 Chaves Código Original: 35100-KWG-601 Aplicação: HONDA CG 125 KS FAN (2009-2013) CG 125 ES FAN (2009-2013) A chave de ignição Magnetron é produzida com material de alta qualidade e garantia de funcionamento perfeito e maior segurança para a sua moto. Mantém o padrão de fabricação da montadora com as mesmas especificações da peça original. Responsável pela função de alimentação elétrica, a chave de ignição Magnetron permite o desligamento ou a partida (ignição) da moto. A chave também tem a função de fazer o travamento (bloqueio) do guidão, impedindo que moto seja movimentada com facilidade sem o uso da chave. Produto elaborado com material de alta qualidade, testado e aprovado dentro das normas de segurança. Instalação: Este produto possuí fácil instalação, não exige que mude a estrutura de sua moto, pois foi confeccionado seguindo as especificações do produto original, para encaixe e funcionamento perfeito. Vantagem: Agora você pode desfrutar de um produto com qualidade do original, para uma melhor reposição em sua moto e com baixo custo. Importante: Recomendamos que a instalação seja feita por profissional especializado e não nos responsabilizamos pelo mau uso do produto.', 48.9, 44.01, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Ignition', 'https://cf.shopee.com.br/file/br-11134207-7r98o-lxcl07rlxtxbf2', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F316500472%2F15761361019', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
