INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21598075106', 'Pneu Aro 17 Goodyear 215/60 R17 96H SL Efficientgrip Suv', 'Pneu Aro 17 Goodyear 215/60 R17 96H SL EfficientGrip SUV Sobre o pneu: O modelo EfficientGrip SUV foi criado para ser um dos principais pneus da Goodyear para caminhonetes e SUV, pois atende à medidas originais de fábrica, e tem características que garantem ótimo comportamento. Sua estrutura é reforçada, auxiliando a reduzir a resistência ao rolamento e a manter o pneu sempre em posição correta de trabalho, sem inclinações excessivas, fazendo com que a lateral não "dobre" em curvas com maior exigência, o que garante a segurança e alta aderência. Informações adicionais: - Marca: Goodyear - Modelo: EfficientGrip SUV - Medida: 215/60 R17 - Largura: 215mm - Perfil: 60% - Aro: 17 - Índice de peso: 96 - 710 Kg - Índice de velocidade: H - 210 Km/h - Sidewall: Letras pretas - Tipo de construção: Radial - Tipo de desenho: Simétrico - Tipo de terreno: HT - Garantia: 5 anos contra defeitos de fábrica Aplicação: - HONDA: HR-V, ZR-V - HYUNDAI: CRETA, CRETA GRAND, KONA - JEEP: AVENGER, COMPASS, RENEGADE - FIAT: E-ULYSSE - CITROËN: C3 AIRCROSS - CHEVROLET: CAPTIVA - CHERY: OMODA 5, TIGGO, TIGGO 3, TIGGO 3 PRO, TIGGO 4, TIGGO 4 PRO, TIGGO 5X Observações: IMAGEM MERAMENTE ILUSTRATIVA POR FAVOR, VERIFIQUE SEMPRE NO VEÍCULO QUAL É A MEDIDA EXATA DO SEU PNEU', 971.58, 913.58, NULL, 'Spare Parts and Accessories for Vehicles > Tires and Wheels > Automobile Tires', 'https://cf.shopee.com.br/file/sg-11134201-7rd5m-m7aui80efs3a04', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F882691919%2F21598075106', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
