INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '48502430960', 'Chuteira Umbro Futsal Fifty Vi League Verde Limão Preto e Prata - Masculino', 'Mais domínio e precisão nas quadras! Chuteira Umbro Futsal Fifty Vi League Verde Limão Preto e Prata - Masculino Parte superior do formulário Ficha Técnica: Marca: Umbro Cor: Verde limão com detalhes em preto, prata e branco Gênero: Masculino Cabedal: Laminado sintético com textura e alta frequência frontal Palmilha: EVA forrado em tecido Sola: Borracha monocolor antiderrapante Fechamento: Cadarço lateral (deslocado para o lado externo) Amortecimento: Leve Estabilidade: Adaptável para diferentes tipos de pé Tecnologias: HYPERGRIP – solado com tração avançada Entressola: EVA Indicação: Jogadores iniciantes e treinos em quadras indoor Detalhes: Design bicolor e área de chute livre de sobreposição Destaque-se nas quadras com a Chuteira Umbro Fifty VI League, perfeita para quem está começando no futsal e quer elevar seu jogo com conforto e controle. O design arrojado em duas cores proporciona estilo único, enquanto o ajuste lateral do cadarço oferece liberdade na área de chute. Porque investir: O cabedal laminado com textura e alta frequência frontal melhora o domínio da bola, e o solado com tecnologia HYPERGRIP garante tração e segurança durante os movimentos mais rápidos. Uma combinação ideal entre resistência e leveza para dominar o jogo do começo ao fim. Conteúdo da embalagem: 1 par de Chuteira Umbro Futsal Fifty Vi League Verde Limão Preto e Prata - MasculinoParte superior do formulário', 199.99, 172.99, NULL, 'Sports & Outdoors > Sports Footwear > Futsal Shoes', 'https://cf.shopee.com.br/file/sg-11134201-8225c-mhq87yyafj0k3e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1175741090%2F48502430960', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22799309526', 'Terminal Axial Astra Vectra Zafira Direção Hidráulica Nakata', 'Terminal Axial Astra Vectra Zafira Direção Hidráulica Nakata N 93004 Nakata altura da embalagem: 10 cm peso da embalagem: 20 g largura da embalagem: 30 cm comprimento da embalagem: 40 cm Garantia de fábrica Aplicação: Chevrolet Astra (Direção Hidráulica): 1998 até 2011Vectra (Direção Hidráulica - Caixa de Direção Saginaw DHB): 2006 até 2012Zafira (Direção Hidráulica): 2001 até 2012 A BOMPREÇO AUTOPEÇAS é uma empresa consolidada no estado de Goiás atuamos no ramo do comercio de autopeças desde 1963 com sede em Goiânia. Trabalhamos com mais de 100 fornecedores sendo todos produtos originais de linha de montagem dos maiores fabricantes de autopeças do país. DUVIDAS FREQUENTES: - O PRODUTO É NOVO? Sim. Nós trabalhamos apenas com produtos novos com nota fiscal e com garantia. - O PRODUTO É ORIGINAL? Sim. Nós só trabalhamos com distribuidores homologados pelo fabricante gerando confiança da originalidade do produto nós compramos e vendemos com nota fiscal. - TEM GARANTIA? Sim. Todos nossos produtos tem 90 dias de garantia contra defeitos de fabricação. - TEM NOTA FISCAL? Sim. Emitimos nota para CONSUMIDOR FINAL (CPF) em nossas vendas. - COMO FAÇO PARA SABER SE ESSE PRODUTO SERVE NO MEU CARRO? Na descrição do anuncio tem as informações das aplicações corretas se a informação que precisa não está na descrição do anuncio deixe sua pergunta que nossa equipe é treinada e está preparada para solucionar qualquer duvida não hesite em nos questionar estamos aqui para servir. - TEM ALGUMA DUVIDA SOBRE O PRODUTO OU A COMPRA? Deixe sua pergunta abaixo que responderemos prontamente. BOMPRECO AGRADECE SUA VISITA TENHA UM ÓTIMO DIA E BOAS COMPRAS!', 59.4, 59.4, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Suspension and Steering', 'https://cf.shopee.com.br/file/sg-11134201-8262v-mjpo89uhrfgm37', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1704733855%2F22799309526', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
