INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22394711743', 'Almofada Decorativa FOM Charm Edge - Turquesa', 'Elegância moderna com o aconchego que abraça. A Almofada Decorativa FOM Charm Edge – Turquesa foi criada para transformar ambientes com estilo e conforto, trazendo o toque macio e acolhedor que é assinatura da FOM. Ideal para decorar sofás, camas, poltronas ou espaços de leitura, ela une beleza e funcionalidade em uma peça que convida ao relaxamento. Seu toque suave proporciona bem-estar imediato, enquanto o enchimento de micropérolas de poliestireno se molda ao corpo, acompanhando os movimentos e garantindo conforto leve e envolvente. Na cor turquesa, oferece um visual sofisticado, versátil e contemporâneo, perfeito para composições modernas e ambientes que pedem equilíbrio entre estilo e aconchego. Composição: Tecido: 78% Poliéster / 22% Elastano Enchimento: 100% micropérolas de poliestireno', 158.0, 158.0, NULL, 'Home & Living > Furniture > Cushions', 'https://cf.shopee.com.br/file/sg-11134201-8227q-mhqby6ez08w6bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1366041969%2F22394711743', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497672229', 'Correia Alternador Poly V TWINGO 1999 2000 2001 - 14475 - 4PK735', 'Correia Alternador Poly V TWINGO 1999 2000 2001 Produto novo, com garantia e Nota Fiscal! Correia Poly V - 4PK737/4PK735 TWINGO - Motor 1.0 8v Anos: 99 00 01 Utilização: Virabrequim / Alternador / Bomba D''água As correias Multi V permitem a transmissão não positiva de binários. A sua função: O acionamento do alternador, ventoinha, bomba de água, compressor do ar condicionado e direção assistida nos motores modernos. As correias Multi V estão sujeitas a envelhecimento e desgaste. Por essa razão, têm de ser controladas e substituídas a intervalos regulares. Os intervalos de controle e de substituição são sempre estabelecidos pelo fabricante do veículo e devem ser respeitados.', 46.69, 46.69, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Engine', 'https://cf.shopee.com.br/file/sg-11134201-7rfhu-m9jkbxmh7nfdad', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20497672229', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20699000397', 'Filtro Gasolina UNO 2002/2006 - 44003 - FCI1610', 'Filtro Gasolina UNO 2002/2006 Motor 1.0 8v Fire Gasolina - (Mecânico) (Plástico) O Filtro do combustível retém impurezas contidas no combustivel. O Filtro possui um elemento de papel filtrante. Por este motivo, a direção de fluxo indicada no filtro deve ser obrigatoriamente mantida. O filtro é fixado na carcaça (de metal), através de uma placa de apoio. A troca do filtro deve ser feita integralmente, a sua vida útil depende da quantidade de impurezas contida no combustível e varia de acordo com as quilometragens indicadas nas publicações.', 26.93, 26.93, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rbkm-lmsvq4mh935l51', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F20699000397', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22492976457', 'Interruptor Cebolao Radiador PASSAT 1974/1991 - 68189 - 7059287', 'Interruptor Cebolao Radiador PASSAT 1974/1991 1.5/1.6/1.8 8v - 92º / 87º - 2 Pinos No trânsito é importante o acionamento da ventoinha do radiador. A peça responsável por isso é o Interruptor Térmico. São comutadores (Liga-Desliga) que acionam diversos produtos no sistema de arrefecimento em função da temperatura. Localizado no radiador, aciona a ventoinha quando a temperatura ultrapassa a temperatura ideal de trabalho, evitando assim o superaquecimento do motor.', 52.06, 52.06, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Injection', 'https://cf.shopee.com.br/file/sg-11134201-7rd6l-lufhq5wi4qtk26', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22492976457', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
