INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18098113263', 'Sonda Lambda Gm Vectra 1998 a 2004 - 1353216 - 781012040', 'Sonda Lambda Gm Vectra 1998 a 2004 1353216 781012040 2.2 8v - 1 Fio - Comprimento do Fio 40 cm - Pré Catalisador - Fio Violeta Esse sensor serve para coletar informações sobre a queima de combustível e enviar ao ECM do motor. Motores de combustão interna (Ciclo Otto, Diesel ou GNV) só conseguem funcionar se houver oxigênio, combustível e calor (combustão ou queima é uma reação exotérmica, ou seja, ocorre de dentro para fora). Sem esses elementos não é possível obter a explosão interna necessária para o seu funcionamento.', 141.3, 141.3, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Electrical System', 'https://cf.shopee.com.br/file/sg-11134201-7rffy-m3x6y4jlnpvq1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F18098113263', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497760910', 'KIT C/2 ELSEVE ÓLEO EXTRAORDINÁRIO LORÉAL PARIS 100ML', 'Óleo Extraordinário Tratamento Condicionante De Flores Preciosas Elseve Loréal Paris 100ml - 2 Unidades Formulado para uma hidratação profunda dos cabelos, o Óleo Extraordinário Elseve de L''Oréal Paris é um delicado óleo que proporciona tratamento profissional para a beleza dos seus cabelos. Penetrando as fibras capilares, o óleo da linha L''Oréal trata os fios em profundidade, além de proteger os fios do calor da chapinha e produzir brilho instantâneo. Além disso, pode ser usado antes da aplicação do shampoo, como finalizador, antes do uso do secador ou a qualquer momento do dia. Escolha sua maneira de usar e impressione! Benefícios: - Nutrição - Brilho - Leveza - Maciez - Hidratação - Suavidade Ação: A fórmula de Óleo Extraordinário é leve e não gordurosa e age adaptando-se a qualquer tipo de cabelo. Hidrata até os cabelos mais secos, fornecendo-lhes nutrição, maciez e brilho intenso. Modo de Usar: Aplique nos cabelos úmidos ou secos. Indicação: Todos os Tipos de Cabelos; Cabelos Secos e Ressecados. Resultados: Os cabelos secos ficam hidratados, nutridos e macios.', 99.9, 79.9, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m9rosgsja14pb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F20497760910', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22298942904', 'Maçaneta Externa Lado Esquerdo Scania 124 Série 4 e 5 S4 S5 Com Chave', 'Maçaneta Externa da Porta Dianteira Com 2 Chaves, Chapa Antifurto, Serve no Lado Esquerdo (Lado do Motorista) Compatível com os Caminhões Scania Série IV de 1998 a 2007 e Série V de 2008 a 2019 - Modelos de Aplicação: - SCANIA Série IV após 1998 até 2007 - SCANIA Série V 2008 até 2019 - Dimensões Aproximadas: Altura: 19,5cm X Largura: 27,5cm X Comprimento: 10cm - Grupo: Maçaneta Externa / Porta Dianteira - Peça fabricada em Plástico/Aço - Enviada na cor Preta - Com Chapa Antifurto - Acompanha 2 chaves - Valor referente a unidade do Lado Esquerdo - Em caso de dúvidas use o campo de Perguntas. Obs.: Peças não genuínas da montadora. CÓD. REFERÊNCIA: 018095 - 1423017', 148.51, 148.51, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Body', 'https://cf.shopee.com.br/file/br-11134207-81z1k-meyp5uvvltl24a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F843124271%2F22298942904', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '57656648631', 'Jogo Allen E Torx Curta CRV 1,5-10mm T10-T50 18 Peças MTX', 'Jogo de chaves Allen e Torx em versão curta, com 18 peças que cobrem tamanhos Allen de 1,5 a 10 mm e Torx de T10 a T50. Acabamento acetinado e fabricação em aço CRV garantem aparência profissional e resistência ao uso diário, ideal para trabalhos mecânicos e montagem de móveis. Conjunto compacto e prático para uso em espaços reduzidos, oferecendo variação de tamanhos que atende aplicações domésticas e profissionais. A marca MTX assegura padrão básico de qualidade e facilidade de identificação das chaves. Características: Modelo: 123149 Referência: 123149 Tipo: Jogo de chave Allen e Torx curta Acabamento: Acetinado Material: CRV Tamanhos Allen: 1,5-10 mm Tamanhos Torx: T10-T50 Peças: 18 Marca: MTX Código EAN: 7899612784827 Benefícios: Conjunto completo que reduz a necessidade de comprar peças avulsas Aço CRV oferece maior resistência e durabilidade Acabamento acetinado evita oxidação superficial e facilita limpeza Formato curto possibilita trabalho em espaços confinados Variedade de tamanhos atende múltiplas aplicações domésticas e profissionais Conteúdo da embalagem: 1 jogo com 18 peças (tamanhos conforme especificado)', 75.49, 59.6, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/sg-11134201-825zq-mlc46g7z49hkb8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F57656648631', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094274572', 'Cordoalha Para Curral 100M Com 7 Fios Vonder', 'A cordoalha para curral Vonder é ideal para construções rurais que exigem resistência e durabilidade. Com 100 metros de comprimento e 7 fios de aço carbono, é recomendada para montagem de currais e estruturas de contenção no manejo de gado. Seu acabamento com camada pesada de zinco garante maior proteção contra corrosão, mesmo em ambientes externos e com exposição constante às intempéries. A tripla galvanização assegura uma longa vida útil e confiabilidade no uso contínuo. Características: Modelo: 7491007100 Referência: 7491007100 Material da cordoalha: Aço carbono Acabamento da cordoalha: Camada de zinco pesada (tripla galvanização) Comprimento da cordoalha: 100 m Diâmetro: 1/4" Diâmetro da cordoalha: 6,4 mm Quantidade de fios da cordoalha: 7 fios Carga de ruptura: 2.500 kgf Massa aproximada (peso): 19,5 kg Benefícios: Alta resistência à tração e excelente durabilidade Tripla galvanização que aumenta a proteção contra corrosão Ideal para currais, cercas e manejo de animais de grande porte Rolo com 100 metros que facilita o transporte e a instalação Estrutura reforçada para uso em ambientes agressivos Conteúdo da embalagem: 1 Rolo de cordoalha para curral.', 588.51, 422.53, NULL, 'Home & Living > Tools & Home Improvement > Construction Materials', 'https://cf.shopee.com.br/file/sg-11134201-7rdxq-mc231m6rx3nn2c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F939446263%2F23094274572', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18699074182', 'Desodorante Rexona Clinical Extra Dry Feminino 58g', 'Desodorante Antitranspirante Em Creme Clinical Extra Dry Feminino 58g - 1 unidade Rexona clinical oferece proteção avançada e duradoura contra a transpiração e o mau odor, deixando você mais seguro e mantendo a sensação de refrescância o dia todo. Tecnologia que formam uma micro escudo que dura por 96 horas. Basta aplicar uma vez para ficar protegida o dia inteiro. Não é necessário reaplicar. Clinical é 3X mais forte contra o suor vs. um antitranspirante básico. Proteção contra o mau odor ativada pelo movimento graças a tecnologia MotionSense. Beneficios 3x mais Proteção superior tecnologia que forma uma blindagem contra o suor e mau odor que dura 96 horas. Dermatologicamente testado. Modo de Uso Para utilizá-lo pela primeira vez, gire a roda várias vezes até o produto aparecer. Se depois de usar algumas vezes o produto deixa de sair, gire várias várias vezes até que volte a sair. Dose recomendada: 2 cliques em cada axila. Aplique o produto nas axilas secas. Guarde tampado. Resultado 96 horas de proteção eficaz e você livre do suor e do mau odor.', 39.9, 37.9, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rbm5-loob0r6x10ju1c', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290598330%2F18699074182', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
