INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58210733458', 'Chuteira Mizuno Society Regent AS Masculina', 'Chuteira Mizuno Regent AS Masculina - A Chuteira Society Mizuno MZ Regent AS Adulto é a escolha certa para quem busca conforto, desempenho e durabilidade em cada jogada. Desenvolvida com cabedal sintético de alta qualidade, ela oferece resistência e ajuste perfeito ao pé, garantindo controle total da bola nos gramados artificiais. O solado emborrachado com travas baixas e fixas proporciona excelente aderência e estabilidade, permitindo arrancadas rápidas e mudanças de direção precisas. A palmilha forrada e o reforço acolchoado no calcanhar garantem conforto extra, mesmo nos jogos mais intensos, reduzindo o impacto e protegendo seus pés. A lingueta integrada contribui para um ajuste anatômico e seguro, deixando você livre para focar no jogo. Pronta para encarar qualquer desafio, essa chuteira combina design moderno com tecnologias que fazem a diferença em campo. Quer dominar o jogo? Com a Chuteira Society Mizuno MZ Regent AS Adulto, você estará sempre um passo à frente. Garantia do Fornecedor: Contra Defeito de Fabricação Material do Cabedal: Sintético Têxtil Tipo de Amarração: Cadarço Palmilha: Forrada Solado: Borracha Lingueta: Fina Integrada Material do Forro: Têxtil Reforço acolchoado Tipo de Trava: Fixa Estampa do Logo: Estampado no Cabedal Nível: Iniciante Características Gerais do Produto: • Gênero: Masculino Garantia: • 7 dias de garantia', 239.9, 239.9, NULL, 'Sports & Outdoors > Sports Footwear > Soccer Shoes', 'https://cf.shopee.com.br/file/sg-11134201-825am-mqdav85wvjf156', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1172340783%2F58210733458', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22997093612', 'Forth Orquídeas Manutenção 20-20-20 - 100g', 'Forth Orquídeas Manutenção 20-20-20 - 100g - Indicado para orquídeas; - Para aquela sua orquídea que está só com folhas ou então acabou o período de floração; - Proporciona as folhas bem nutridas; - Planta pronta para soltar a próxima florada; - Disponível em embalagem com 100g. Detalhes Forth Orquídeas Manutenção 20-20-20 - 100g. Esse adubo é para aquela sua orquídea que está só com folhas ou então acabou o período de floração. O Forth Orquídeas Manutenção 20-20-20 - 100g, vai deixar as folhas bem nutridas e a planta pronta para soltar a próxima florada. Dicas Especiais Atenção: Não aplicar sobre botões florais e flores, evitar aplicações nas horas mais quentes do dia. A cada 3 meses utilize FORTH Equilíbrio. Caso a orquídea esteja com fungos, não efetuar adubação até resolver o problema. Utilização: Aplicação via foliar: 1 colher de café em 1 Litro de água, a cada semana, pulverizar a parte de cima e de baixo das folhas. Utilização: Aplicação via fertirrigação: ½ colher em 1 Litro de água a cada 15 dias, Preparar a solução em um regador e regar o substrato. Indicação: Adubo Fertilizante Composição: Farelado mineral misto Apresentação: Embalagem 100g', 24.83, 20.88, NULL, 'Home & Living > Gardening > Fertilizer', 'https://cf.shopee.com.br/file/sg-11134201-7rbld-lnikbjvmk6pxb9', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F290073877%2F22997093612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
