INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23839410660', 'AHC Creme Real Para Olhos Para Rosto Temporada 10, 30ml', 'AHC Creme Real Para Olhos Para Rosto Temporada 10, 30ml AHC TEN Revolution Real Eye Cream For Face Season 10, 30ml Descrição do produto em inglês após português Contém colágeno e nutre a pele para torná-la animada e elástica. Creme para os olhos para o rosto anti-envelhecimento e elasticidade que ajuda a cuidar dos olhos. Para todos os rostos Creme para os olhos Real Real para rosto Creme para os olhos Anti-envelhecimento Anti-envelhecimento.Olho ************************************************** It contains collagen and nourishes the skin to make it lively and elastic. Eye cream for face that helps anti-aging and elasticity care. For all face Real Eye Cream For Face Anti-aging Eye cream.Eye', 40.29, 40.29, NULL, 'Beauty > Skincare > Eye Treatment', 'https://cf.shopee.com.br/file/sg-11134207-7renq-m82ztkcot5e965', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F23839410660', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '28404399299', 'VT COSMETICS Tiro de Procica Reedle (100/300/700) 3 Tipo', 'Tiro Reedle VT COSMETICS Pro Cica 50ml (100 / 300 / 700 Shot) 3Tipo Modo DE USAR 1. O Reedle Shot é um produto de cuidado noturno usado na primeira etapa após a limpeza. 2. O único produto que pode aumentar a frequência de uso é o tiro de reedle 100. 3. Mesmo que o tiro de remo 300 e 700 sejam eficazes após o uso, certifique-se de seguir os ciclos de 3 dias e 7 dias, respectivamente. 4. Não use tiro de reedle 100, 300 e 700 ao mesmo tempo. Não use tiro de reedle 100, 300 e 700 ao mesmo tempo. Certifique-se de que sua pele pode absorver totalmente o tiro da reedle com apenas um produto. Certifique-se de que sua pele possa absorver totalmente o tiro da reedle com apenas um produto.', 201.0, 191.0, NULL, 'Beauty > Skincare > Facial Serum & Essence', 'https://cf.shopee.com.br/file/sg-11134207-7rdyj-lxt1aq5wg8km76', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F920292999%2F28404399299', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
