INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '49850835265', 'Par/Un Carcaça Farol Corolla 2003 2004 2005 2006 2007 2008', 'Par/Un Carcaça Farol Corolla 2003 2004 2005 2006 2007 2008 DESCRIÇÃO DO PRODUTO Os faróis, sejam de luz baixa ou alta, tem como função iluminar o caminho de um veículo. Nesse sentido, é importante que os condutores saibam como fazer a regulagem correta dos faróis, pois um farol desregulado não ilumina adequadamente a rodovia ou ainda pode causar ofuscamento, perda de visão momentânea, no condutor do veículo que transita em sentido contrário. ESPECIFICAÇÕES DO PRODUTO: - Fabricado em Plástico Resistente - Carcaça Cor Cinza Compatível com: - Corolla 2003 - Corolla 2004 - Corolla 2005 - Corolla 2006 - Corolla 2007 - Corolla 2008 Especificação Técnica: • Produto Novo Importado • Não Acompanha Soquetes e Lâmpadas O QUE VEM NA EMBALAGEM Conteúdo da Embalagem: PAR: • 02 Carcaças de Farol OU UNIDADE: • 01 Carcaças de Farol FINALIZAÇÃO A imagens representam o real estado de conservação dos produtos. Mais detalhes e funcionalidades podem ser obtidos no chat! Compare o produto anunciado com o seu modelo de referência. Postaremos a sua mercadoria dentro de algumas horas após a confirmação da compra. Não esqueça! Tire todas as suas dúvidas conosco antes de comprar o seu produto. Auto Peças Nova Kennedy Agradece sua preferência!', 99.9, 84.92, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Lighting', 'https://cf.shopee.com.br/file/sg-11134201-821fb-mgnsqj2h1xcef8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F494312426%2F49850835265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
