INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43263329731', 'Mixer De Mão Inox 1000w Elétrico 2 Velocidades Misturador Mix Triturador Profissional CHEF D', 'O Mixer de Mão Inox é a solução prática e potente para preparar receitas com mais rapidez e qualidade. Com acabamento em aço inoxidável e design moderno, oferece alta durabilidade e resistência ao uso diário. Equipado com potência de 1000W e 2 níveis de velocidade, permite ajustar a intensidade de acordo com cada preparo, garantindo resultados mais homogêneos e consistentes. Suas lâminas em inox reforçado são precisas, seguras e eficientes para triturar frutas, legumes, temperos e preparar cremes, molhos e vitaminas. Com peso leve de apenas 0,7 kg e dimensões ideais de 37,5 cm de altura x 6 cm de largura, é fácil de manusear e armazenar. Funciona em 110V ou 220V, sendo ideal para uso doméstico ou profissional. (INDICADO PARA VITAMINAS, SUCOS e POLPAS) Especificações Técnicas: Potência: 1000W Material: Aço inoxidável Lâmina: Inox reforçado Velocidades: 2 níveis Peso: 0,700 kg Voltagem: 110V/220V Dimensões: 37,5 cm (A) x 6 cm (L) Conteúdo da Embalagem: 1 Mixer de Mão Inox 1000W (INDICADO PARA VITAMINAS, SUCOS e POLPAS) FAQ – Perguntas Frequentes 1. Posso usar o mixer para triturar gelo? Não é indicado para gelo, pois pode danificar as lâminas. 2. Ele funciona para bater claras em neve? Sim, é possível, mas o tempo pode variar de acordo com a quantidade. 3. É fácil de limpar? Sim, a haste é removível e pode ser lavada separadamente. 4. Funciona para receitas quentes? Sim, pode ser usado diretamente em preparos quentes como sopas e caldos. 5. Pode ser utilizado em recipientes de vidro? Sim, desde que o vidro seja resistente ao calor e impactos.', 228.99, 138.99, NULL, 'Home Appliances > Kitchen Appliances > Mixers', 'https://cf.shopee.com.br/file/br-11134207-820m9-mo0nvb99jvnl5b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F927963980%2F43263329731', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
