INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23997743924', 'Bicama Montessori Exclusiv Solteiro Fio de Luz e Voal Lilás', 'A Cama Montessoriana é ideal para o quarto do seu filho. Garanta comodidade, qualidade e muita diversão para as noites de sono da garotada. Cama acompanha grade lateral de proteção, cama auxiliar, voal, e cordão fio de luz LED com 10 bolinhas. (não acompanha pilhas). Dimensões cama superior: Altura: 188 cm Largura: 95 cm Comprimento: 200 cm Ideal para acomodar colchão de solteiro na medida de 88x188 cm(Colchão não incluso). Dimensões cama auxiliar: Altura: 20 cm Largura: 91,5 Profundidade: 189 cm Ideal para acomodar colchão de solteiro na medida de 12x88x188 cm(Colchão não incluso). Informações complementares: Tipo de cama: Montessoriana Solteiro Acompanha colchão: Não. Material Principal: MDF Cor principal: Branco Peso máximo suportado: 100kg Pés: Não Gavetas: Não Prateleiras: Não Nichos: Não Itens Inclusos: 01 Cama Montessoriana 01 Cama Auxiliar 01 Voal 01 Cordão fio de luz LED com 10 bolinhas. Kit completo para montagem, manual de instruções. Garantia: 3 meses contra defeito de fabricação Informações complementares: - Fotos meramente ilustrativas do produto no ambiente. - Verificar descrição e tamanho do produto antes da compra. - Avaliar a mercadoria no ato do recebimento e recusar em caso de divergência ou avarias. - Mantenha as informações de contato e endereço de entrega atualizados para entrarmos em contato caso necessário. - Limpar com flanela ou pano macio seco, não utilizar produtos abrasivos, desengordurantes, álcool ou solvente. Não expor o produto diretamente à luz solar e à umidade. * Apesar de fácil montagem, sugerimos a contratação de um montador profissional caso necessário. * Antes de comprar seu produto verifique as medidas do produto e do local onde pretende montar. * Não nos responsabilizamos pela montagem e desmontagem do produto no ato da entrega e devolução, assim como os custos gerados nestas situações. * A transportadora entregará o produto no andar térreo do endereço de entrega. * Objetos que compõem o ambiente das fotos não acompanham o produto.', 1432.99, 988.77, NULL, 'Home & Living > Furniture > Bed Frames & Headboards', 'https://cf.shopee.com.br/file/sg-11134201-7rdwu-mbsl29le2d2f40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F451273707%2F23997743924', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
