INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43965181276', 'Kit 2 Esmalte Impala A Cor Da Moda Semear Unhas Perolado', 'Semeie beleza por onde passar com o brilho delicado e sofisticado do Esmalte Impala Semear Perolado! Com um tom perolado elegante e atual, ele é a escolha perfeita para quem ama unhas com acabamento refinado, brilho suave e uma cor que transmite leveza, cuidado e atitude. Sobre o produto: - Marca: Impala. - Linha: A Cor Da Sua Moda. - Conteúdo: 7,5 ml. - Brilho intenso. - Alta cobertura. - Longa duração. - Secagem rápida. - Não testado em animais. - Dermatologicamente testado. O que faz: - Acabamento Elegante, Deixa suas unhas com um acabamento brilhante e sofisticado. - Durabilidade: Garante horas de esmaltação sem perder o brilho ou a cor. - Fácil de Retocar: Sua fórmula permite retoques fáceis e rápidos, mantendo as unhas sempre perfeitas. Indicado para: - Profissionais de manicure e pedicure. - Cuidados pessoais em Casa. Modo de uso: - Agite bem antes de usar. - Aplique o esmalte sobre as unhas após o uso de uma base da sua preferência. - Comece a esmaltação pelo centro e, em seguida, preencha as laterais. - Se desejar aplique uma segunda camada de esmalte. - Use um palito com algodão umedecido em removedor para limpar o excesso do esmalte. - Finalize com um secante da sua preferência. Precauções de uso: - Não expor ao calor/luz solar, não ingerir. - Manter fora do alcance das crianças. - Usar somente em adultos, não usar sobre a pele irritada ou lesionada. - Em caso de irritação, suspender o uso e procurar orientação médica. O esmalte Impala Semear é sinônimo de elegância, brilho na medida certa e facilidade na aplicação. Complete seu visual com esse toque de leveza e estilo. Garanta já o seu e floresça em cada detalhe! Surgiu alguma dúvida? Entre em contato com a gente! Boas Compras :)', 27.48, 21.98, NULL, 'Beauty > Hand, Foot & Nail Care > Nail Care', 'https://cf.shopee.com.br/file/sg-11134201-824j0-mdvuwv0vzyfb1e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F371678536%2F43965181276', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498453133', 'Par Pneu 26x1.5 Pirelli Phantom Street 2 Camara + Antifuro', 'KIT 02 PNEU BICICLETA ARO 26X1.5 PIRELLI PHANTOM STREET ROAD Obs: kit com 2 pneus e 2 câmaras + par de fita anti-furo. O Pneu Pirelli Phantom Street é uma excelente escolha para a sua bike no dia a dia sobre duas rodas na cidade. Seu desenho garante conforto e segurança em toda pedalada, graças a baixa resistência no rolamento. Produto certificado pelo Inmetro. Válvula Bico Grosso Especificação: Medida do pneu: 26x1.50 ERTO: 40-559 Peso: 715 gramas. Máximo Psi: 45 Tpi - Tramas por polegada: 30 Tipo do Talão: Arame. Tubeless: Não. Uso de Selante: Não. Composição: Single: Uma única camada de tecido de nylon de 30 Tpi. Leve e baixa resistência ao rolamento. Indicação: Pisos asfaltados e pavimentados. Marca: Pirelli. Garantia: 3 meses. Quantidade: 2 unidades.', 179.9, 179.9, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Cycling', 'https://cf.shopee.com.br/file/sg-11134201-7rfhw-m9dvupmmfh9131', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F23498453133', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
