INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20899832078', 'Chave Cone Cubo 13/15 14/16mm Roda Gta Aço Preto Durável', 'Chave de Cone para Cubo Roda GTA Medidas: 13/15mm e 14/16mm, versátil para diferentes tamanhos de cubos. Uso: Ideal para manutenções domésticas em bicicletas. Cor: Preto, oferecendo um visual sóbrio e profissional. Material: Fabricada em aço 65Mn, garantindo durabilidade e resistência. Marca: GTA, reconhecida pela qualidade em ferramentas para ciclismo. Esta chave de cone é essencial para ajustes precisos em cubos de roda, proporcionando facilidade e eficiência em manutenções e reparos. Compatível com a maioria dos cubos de bicicleta.', 18.97, 18.97, NULL, 'Spare Parts and Accessories for Vehicles > Vehicular Tools > Wrench', 'https://cf.shopee.com.br/file/sg-11134201-7ravm-mavsv3sdi7hede', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F333705502%2F20899832078', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
