INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43973949262', 'Lavadora de Alta Pressão Kala LK1305 1200W 127V/220V', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** Lavadora de Alta Pressão Kala LK1305 1200 W 127 V ou 220 V – Compacta, prática e econômica para limpezas do dia a dia A Kala LK1305 reúne 1200 W de potência em um corpo leve e compacto para tornar a limpeza de áreas externas mais rápida e eficiente. Indicada para uso doméstico, ajuda a remover sujeiras do cotidiano em pisos, muros, portões, móveis de jardim e veículos, proporcionando economia de água em comparação à mangueira tradicional. O design pensado para o dia a dia facilita o transporte, o armazenamento e o manuseio durante a lavagem. Informações técnicas: Marca: Kala Modelo: LK1305 Tipo: lavadora de alta pressão elétrica Lança ajustável Potência nominal: 1200 W Tensão: 127 V ou 220 V (verificar a versão escolhida no momento da compra) Frequência: 60 Hz Vazão: 5,5L/min Pressão máxima: 9 Mpa 1305 lb/pol² Pressão nominal: 6 Mpa 870 lb/pol² Dupla isolação elétrica Sistema de segurança com desligamento automatico Conteúdo da embalagem: 1 Lavadora de Alta Pressão Kala LK1305; Mangueira; Pistola Recipiente para detergente Manual do usuário Manutenção e garantia Manutenção básica: utilize água limpa; após o uso, alivie a pressão do sistema, drene mangueiras e mantenha o equipamento seco; verifique periodicamente conexões e vedantes conforme o manual Garantia: 3 meses Observações importantes Verifique a tensão (127 V ou 220 V) antes da compra e do uso Use EPIs adequados e não direcione o jato a pessoas, animais ou componentes elétricos Respeite as orientações de uso e os intervalos de descanso para maior vida útil Finalize sua compra e ganhe praticidade: potência de 1200 W em um equipamento compacto para deixar sua área externa sempre limpa.', 399.0, 343.9, NULL, 'Home & Living > Tools & Home Improvement > Tools', 'https://cf.shopee.com.br/file/br-11134207-820la-mnyn4b4bcfeoc8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F43973949262', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23792893200', 'Lixeira Inox Slim 5 Litros com Pedal para Banheiro Powermaid', '***PRODUTO A PRONTA ENTREGA COM ENVIO IMEDIATO*** Lixeira de Inox Slim 5 Litros Para Banheiro Com Pedal Experimente a praticidade e sofisticação da Lixeira Slim 5L em Aço Inox, uma adição elegante e funcional para qualquer espaço. Com dimensões cuidadosamente projetadas de 20,3 cm x 26,2 cm, esta lixeira se encaixa perfeitamente em ambientes compactos, proporcionando uma solução eficiente para o descarte de resíduos. Construída com materiais de alta qualidade, a composição em Aço Inox e Polipropileno garante durabilidade e resistência, tornando-a uma escolha confiável para o seu dia a dia. Destaque-se pelos benefícios exclusivos, como o balde interno removível, facilitando a limpeza e a manutenção da higiene.', 66.9, 61.9, NULL, 'Home & Living > Home Care Supplies > Trash & Recycling Bins', 'https://cf.shopee.com.br/file/sg-11134201-7rcev-lsx5fpdfjkx7db', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F23792893200', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23594961801', 'Kit Mix de Melancia e Uva com Creme para Pentear e 2 Óleos Reparador', 'O kit contém 1 Creme para Pentear Tratamento Óleo Extraordinário 1kg, 1 Óleo de Tratamento Melancia Multy Poderosos 50ml e 1 Óleo de Tratamento Uva Multy Irresistível 50ml, a combinação perfeita para hidratar, nutrir e reparar os fios. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos Ondulados, Cacheados e Crespos. Qual a indicação? Cabelos ressecados, desnutridos, sem definição, fragilizados, com frizz e sem brilho. Pode usar a partir de quantos anos? A partir de 12 anos. <>ATIVOS$& Quais os principais ativos? Óleo Multy Melância e Uva Óleo de semente de uva: potencializa a hidratação dos fios. Óleo de melancia Óleo de Argan: Evita a perda de água natural dos fios, promove hidratação e nutrição. Creme Melância e Uva Mix de Óleo de Argan: evita a perda de água natural dos fios, promove hidratação e nutrição. Óleo de semente de Melancia: nutre e hidrata os fios e controla o frizz. Óleo de semente de uva: potencializa a hidratação dos fios. <>MODO DE USO$& Qual a melhor forma de usar? Creme de tratamento Melância e Uva Com os cabelos limpos e úmidos, aplique o Creme para Pentear mecha a mecha, no comprimento e nas pontas. Desembarace os fios e, em seguida, amasse-os das pontas até a raiz. A aplicação ideal pode variar de acordo com o comprimento e o volume dos fios. Não enxágue. Óleo Multy Melância Óleo Multy Uva Com o cabelo seco ou úmido, aplique algumas gotas do óleo reparador na palma das mãos e espalhe bem do comprimento às pontas. Finalize como preferir. Sem enxágue. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos são veganos. É liberado? Nenhum produto é liberado.', 81.0, 70.47, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/br-11134207-820md-mo796lhw32m97f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F23594961801', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18799358324', 'Kit Creme para Pentear Morango + Melão', 'O kit conta com um Creme para Pentear Cachinhos Sem nós e Creme para Pentear Cachinhos Poderosos. Juntos são especialmente formulados para cuidar dos fios delicados, oferecendo hidratação, definição e controle do frizz. <>INDICAÇÕES$& Para quais tipos de cabelo? Cabelos ondulados, cacheados e crespos. Qual a indicação? Cabelos finos, brilho, definição e redução de frizz. Pode usar a partir de quantos anos? A partir de 3 anos. <>ATIVOS$& Quais os principais ativos? Creme para Pentear Morango Óleo de coco: poderoso ativo hidratante para os cabelos que proporciona maciez e suavidade aos cachinhos das crianças. Óleo de macadâmia: promove brilho e hidratação dos cachinhos. Óleo de semente de melancia: auxilia na nutrição e maciez dos fios. Extrato de frutas vermelhas: possui propriedades emolientes e nutritivas para os cabelos. Creme para pentear Melão Sua fórmula conta com óleo de melão, óleo de coco e extrato de alecrim, ativos que ajudam a manter os fios hidratados, saudáveis e fortes. Além disso, proporcionam desembaraço suave, maciez e brilho às ondinhas, aos cachinhos e crespinhos. <>MODO DE USO$& Qual a melhor forma de usar? Creme para pentear Kids Cachinhos sem nós e Creme para pentear Kids Cachinhos poderosos Melão Todos os itens Para obter um resultado impecável, sugerimos finalizar sempre com os cabelinhos molhados, fazendo a divisão em mechas para uma aplicação uniforme. Desembarace os fios com um pente de dentes largos e em seguida, amasse-os iniciando o movimento das pontas até a raiz. <>CARACTERÍSTICAS$& É produto vegano? Todos os produtos do kit são veganos. É liberado? Nenhum item é liberado.', 79.0, 67.15, NULL, 'Mom & Baby > Bath & Body Care > Hair Care & Body Wash', 'https://cf.shopee.com.br/file/sg-11134201-7rdxt-lyqoshrzncw742', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F616222685%2F18799358324', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22494243327', 'Chuveiro Eletrônico Fame Intense 7800W Branco e Cromado', '***PRODUTO A PRONTO ENTREGA COM ENVIO IMEDIATO*** ITEM ORIGINAL COM NOTA FISCAL Somos a Domus, Loja oficial da Shopee. Temos 5 anos de experiência em E-Commerce e nosso maior objetivo é garantir a satisfação dos nossos clientes! Chuveiro Elétrico Ducha Intense Khrome Fame | Banho confortável e potente com design moderno, economia e segurança para o seu dia a dia A Ducha Elétrica Intense Khrome da Fame oferece um banho com jato intenso e envolvente, combinando desempenho, conforto e economia. Com design moderno na cor cromada, valoriza o ambiente do banheiro com sofisticação. Possui controle de temperatura eletrônico, permitindo ajustar a temperatura ideal com praticidade e segurança, mesmo durante o uso. Sua instalação na parede é fácil e compatível com padrões hidráulicos e elétricos residenciais. A ducha é equipada com resistência de troca rápida e sistema de segurança contra sobreaquecimento, garantindo maior durabilidade e confiança para o uso diário. Ideal para quem busca economia sem abrir mão de desempenho e estética. Informações técnicas: Modelo: Ducha Intense Khrome Tipo: Elétrica, para parede Tensão: Disponível em 127V ou 220V Potência: 5.500W (127V) / 7.800W (220V) Tipo de jato: Pressurizado, espalhador amplo Controle de temperatura: Eletrônico Instalação: Parede, com engate rápido Cor: Cromado Compatível com disjuntores DR Conteúdo da embalagem: 1 Ducha Elétrica Intense Khrome Fame 1 Manual de instruções 1 Kit de instalação Para quem valoriza conforto, estilo e economia – um banho potente com a confiança da Fame.', 369.9, 359.9, NULL, 'Home & Living > Bathrooms > Showerheads & Bidet Sprays', 'https://cf.shopee.com.br/file/br-11134207-820m6-mmw34vuc38xu44', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F22494243327', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '41176049977', 'Aspirador Pó 2 Litros 1200W Com Tubo Prolongador Telescópico APV1200 Vonder', '***PRODUTO PRONTA ENTREGA COM ENVIO IMEDIATO*** PRODUTO ORIGINAL COM NOTA FISCAL Aspirador de Pó 1.200 W – 2 Litros – VONDER APV 1200 Destaques do produto Potente motor de 1.200 W com sucção eficiente para uso doméstico Sistema de filtragem em 3 etapas para maior retenção de partículas Coletor removível e lavável, dispensa saco recolhedor Recolhimento automático do cabo elétrico Rodas de transporte que facilitam a mobilidade Tubo telescópico ajustável e alcance total de 7,5 m (mangueira + cabo) Design compacto, ideal para guardar em pequenos espaços Produto certificado pelo Inmetro, com foco em segurança e qualidade Informações técnicas Modelo: APV 1200 Linha: Leve Potência do motor: 1.200 W Capacidade do reservatório: 2 L Tipo de aspiração: sólidos Vácuo: 19 kPa Nível de ruído: 83 dB(A) Comprimento da mangueira: 2,5 m Comprimento do cordão elétrico: 5 m Dimensões (C x L x A): 370 x 245 x 300 mm Tensão: 127 V~ ou 220 V~ Frequência: 50 / 60 Hz Peso aproximado: 4,45 kg Normas: IEC 60335-1 e IEC 60335-2-2 Conteúdo da embalagem 1 aspirador de pó 1 mangueira flexível de 2,5 m 1 bocal para pisos 1 bocal para estofados 1 bocal para cantos 1 tubo prolongador telescópico Garantia Garantia legal de 90 dias Motivos para comprar Limpeza rápida e eficiente para todos os ambientes; fácil de armazenar; baixo consumo de energia; ideal para o dia a dia; potente, ergonômico e com design moderno.', 402.9, 309.9, NULL, 'Home Appliances > Small Household Appliances > Vacuum Cleaners & Floor Care Appliances', 'https://cf.shopee.com.br/file/sg-11134201-821d9-mgjum1tlugi70f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F445163047%2F41176049977', NULL, NULL, '2026-07-28T02:1