INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20497724006', 'Base 2 em 1 Fast Glam Mistura Boa Alta Cobertura Matte Ana Hickmann', 'Sinta-se poderosa e confiante com a linha de maquiagens de Ana Hickmann. Produtos para rosto, olhos, boca e acessórios como esponjas, curvex, pincéis profissionais e kits. Produtos de alta performance. Seja a protagonista do seu próprio beauty show! Lançamento 2024 - Fast Glam Mistura Boa Base 2 em 1 Mistura Boa reúne base e corretivo em um único produto. É a combinação perfeita de alta cobertura e efeito matte. Ideal para quem gosta de uma pele homogênea e sequinha. Pode ser aplicado em todo o rosto ou apenas nas imperfeições, como manchas e olheiras. Modo de uso: Aplique em todo o rosto ou somente nas áreas que deseja camuflar manchas com os dedos ou com um pincel/esponja de maquiagem. Escolha entre 6 diferentes tipos de tons: C373 - Claro 1 C374 - Claro 2 C375 - Claro 3 C376 - Médio 1 C377 - Médio 2 C378 - Médio 3 C379 - Escuro 1 C380 - Escuro 2 Em caso de dúvidas, nos chame no chat, nossa equipe está pronta para atendê-la. * Produto Vegano *', 23.9, 23.9, NULL, 'Beauty > Makeup > Face', 'https://cf.shopee.com.br/file/br-11134207-820md-ml7z0nsimxaf6b', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F984347359%2F20497724006', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '26385628571', 'Sérum de Tratamento Tresemmé Blindagem Antiumidade 170ml', 'O Condicionador TRESemmé Blindagem Antiumidade foi desenvolvido para quem deseja cabelos livres de frizz e protegidos contra a umidade. Sua fórmula conta com tecnologia pró iônica,ácido hialurônico e queratina hidrolisada, ativos que ajudam a selar as cutículas capilares?desde a primeira aplicação. Com isso, os fios ficam mais macios, hidratados e alinhados, proporcionando um visual impecável por mais tempo.', 50.29, 37.45, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rfg8-m97f0p3grbuo1d', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F26385628571', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
