INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '8593700972', 'Kit com 2 Desinfetante Pinho Sol Lavanda 1750ml Cada', 'PINHO SOL® – LAVANDA Elimina 99,9% das bactérias, germes e fungos Pinho Sol Lavanda é um desinfetante que limpa e elimina 99,9% das bactérias/ germes e fungos*. Além disso, possui um delicioso perfume de lavanda deixando a sua casa sempre limpa protegida e com um agradável perfume que dura por muito mais tempo. Use em todos os cômodos da casa e em diversas superfícies como: vaso sanitário, ralo, pia, tanque, azulejos e pisos. Quer saber como usar? É fácil: – Para desinfecção, utilize o produto puro e deixe-o agir em contato com a área por 10 minutos. – Para limpeza geral de superfície, dilua 2 colheres de copa (30ml) por litro de água. Seguindo essa instrução, o produto rende até 16 litros. 1.75 L – Rende até 87 litros 1L – Rende até 50 litros. 500ml – Rende até 25 litros. Disponível nos tamanhos: 1.75L, 1L e 500ml', 58.69, 42.85, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/04d37bd123705874cd6f67685811a626', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F8593700972', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19199335398', 'Desodorante Old Spice Refrescante 80g', 'Experimente mais poder e estilo com o desodorante antitranspirante em gel Old Spice Refrescante! Sinta-se protegido contra o suor e o mau cheiro e enfrente seus desafios com mais confiança, graças a sua aplicação sem manchas brancas e aroma inesquecível que combina notas de sândalo e frutas vermelhas. • 2x mais proteção que sprays**Vs. Old Spice Spray • Perfume duradouro • Aroma refrescante com notas de sândalo e frutas vermelhas • Você longe do cheiro de cecê ou suor • Dura até 40 días****Com base na instruçao de uso para 2g por día', 29.29, 29.29, NULL, 'Beauty > Bath & Body Care > Body Deodorants', 'https://cf.shopee.com.br/file/sg-11134201-7rdxs-lycers9q3cx408', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F528273775%2F19199335398', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23699118614', 'Fralda Pampers Premium Care Pants Xxg 90 Unidades', 'Conteúdo: XXG 90 unidades Experimente a nova Pampers Premium Care Pants! Com cintura elástica 360° é fácil de pôr mesmo quando eles estão em movimento, e mantendo sua pele seca e protegida. O jeito fácil de trocar Fácil de pôr Cintura elástica 360° que se adapta ao corpinho do seu bebê com sistema de Ajuste Inteligente Fácil de tirar, rasgue suas laterais e retire-a normalmente Canais de ar que evitam que a fralda fique caída Ultra suave e respirável mantendo sua pele seca e protegida Indicador de umidade te avisa quando o bebê tem que ser trocado Até 12 horas* de proteção para noites inteiras de sono sequinho *Pode variar de acordo com os hábitos e características do bebê Para que serve Fralda Pampers Pants? Ideal para proteção e higiene do seu bebe. Quais os benefícios da Fralda Pampers Pants? Fácil De Vestir, Fácil De Retirar, Fácil De Descartar; Ajuste inteligente; Canais de ar. Como usar Coloque o bebê sobre a fralda, desgrude as fitas e puxe-as, grude as fitas sobre a faixa decorada.', 227.38, 227.38, NULL, 'Mom & Baby > Diapering & Potty > Disposable Diapers', 'https://cf.shopee.com.br/file/sg-11134201-8262h-mlghfksshjb639', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1609010660%2F23699118614', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
