INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22598008187', 'Cabo Vela Ford Del Rey 1981 a 1983 - 187055 - FO29', 'Cabo Vela Ford Del Rey 1981 a 1983 187055 FO29 1.6 8v Conduz a alta tensão produzida pela bobina (ou transformador) até as velas de ignição, sem permitir fugas de corrente, garantindo uma ignição sem falhas. Reduz de interferências eletromagnéticas, que podem prejudicar o funcionamento dos componentes eletrônicos do veículo, unidades de comando eletrônico e etc. Cabos resistivos - com o resistor instalado dentro dos terminais. Cabos supressivos - com o supressor instalado dentro do próprio cabo e sua resistividade depende do seu comprimento.', 43.21, 43.21, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Ignition', 'https://cf.shopee.com.br/file/sg-11134201-7rbn9-llwhrwos3716c7', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F895002122%2F22598008187', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
