INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19498665349', 'Filtro de Óleo do Motor Santa Fé 2.7 V6 24v GLS MPFI 2006 2007 2008 2009 2010', 'Similar ao original: JFO-H01 Garantia: 90 dias Usamos Fotos REAIS EM TODOS NOSSOS ANUNCIOS Produto com a qualidade Peças Premium Todos os nossos produtos acompanham nota fiscal Para compras com CNPJ de fora do Estado de São Paulo, o valor do imposto, (ST) Substituição Tributária NÃO ESTÁ INCLUSO NO VALOR DO PRODUTO ANUNCIADO, caso deseje comprar com CNPJ, após a emissão da nota fiscal, será calculado o valor do imposto de (ST), Substituição Tributária, que será COBRADO separadamente e antecipadamente. LEMBRANDO QUE O VALOR DO IMPOSTO, (ST) É COBRADO PELO ESTADO DE DESTINO e mercadoria só poderá ser despachada após o recolhimento antecipado. Peças Rápidas - O seu shopping de auto peças online!', 48.11, 48.11, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/br-11134201-7qukw-liahh656g0ova4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F513651190%2F19498665349', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
