INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18998994754', 'Máscara De Hidratação Forever Liss Desmaia Cabelo Prom 350g', 'Sua fórmula concentrada com Keratina Brasileira, D’Pantenol, Colágeno e Sinergia de Aminoácidos recupera os fios agredidos pela química realizando uma hidratação profunda nos fios garantindo assim a redução do volume e alinhamento capilar. Indicada para todos os tipos de cabelos realmente Desmaia os Fios. Modo de Usar: Aplique a Máscara Desmaia Cabelo Forever Liss com os cabelos úmidos em toda área do fio. Pentear com um pente até que perceba uniformidade na aplicação. Deixe em repouso por 5 minutos. Enxágue normalmente e finalize como desejar. #html-body [data-pb-style="646BA64906BCB"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64906BE0"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 55.24, 55.24, NULL, 'Beauty > Hair Care > Hair Treatment', 'https://cf.shopee.com.br/file/sg-11134201-7rbk4-lmg4grwhctp6dc', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F18998994754', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20797421320', 'Óleo Removedor Pós Depilação Depimiel Hidrat 60ml', 'O Óleo Removedor Hidratante Depimiel proporciona uma limpeza ideal pós depilação. Retirando os possíveis resíduos da cera que tenham ficado após a depilação. Modo de uso: Aplique uma pequena quantidade de Óleo Removedor Hidratante Depimiel diretamente sobre a pele ou na palma da mão e espalhe sobre pele depilada, massageando suavemente até a retirada dos resíduos. Se necessário, para retirar o excesso de óleo, passe um pedaço de algodão limpo e seco na região recém depilada. Precauções: Não se exponha ao sol ou cama solar 48 horas antes e após a depilação. Não use produtos que contenham álcool na área depilada. Não é recomendado para gestantes, crianças ou após cirurgias. Não aplique sobre pele lesionada, sobre varizes ou em mucosas. Mantenha fora do alcance das crianças. Em caso de contato co olhos consulte especialista #html-body [data-pb-style="646BA64831548"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA6483155E"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 23.85, 23.85, NULL, 'Beauty > Beauty Tools > Hair Removal Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rbmx-lmhkuf9cd02xb1', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20797421320', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
