INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58259707371', 'Lacta Laka Chocolate Branco', 'O chocolate branco Laka é cremoso, gostoso e um clássico da Lacta, perfeito para compartilhar momentos especiais. Com sua textura macia e sabor suave, é uma ótima opção para quem busca um doce saboroso e indulgente. Ideal para ser consumido puro, como sobremesa ou acompanhado de bebidas quentes. Experimente também adicioná-lo em suas receitas favoritas para um toque especial.', 11.79, 11.79, NULL, 'Food & Beverages > Snacks > Chocolate', 'https://cf.shopee.com.br/file/sg-11134201-825at-mqnel7pgy1hqe0', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676555116%2F58259707371', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
