INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23998201686', 'Retentor Sabó Lavadora 03532BRGGE', 'Retentor Sabó Lavadora 03532BRGGE O Retentor é um componente essencial para garantir o bom funcionamento de sua lavadora, proporcionando vedação eficiente e durabilidade. Esse retentor foi projetado para impedir vazamentos de água e evitar a entrada de sujeira nas partes internas da máquina, o que ajuda a preservar as engrenagens e outros componentes. Com uma vedação eficaz, sua lavadora mantém o desempenho ideal, evitando danos ao longo do tempo. Fabricado com materiais de alta qualidade, o Retentor Sabó 03532BRGGE oferece uma excelente resistência ao desgaste, suportando as condições exigentes do uso diário. Isso contribui diretamente para prolongar a vida útil da sua lavadora, minimizando a necessidade de manutenções frequentes e trazendo mais tranquilidade para o seu dia a dia. A instalação é simples e garante uma vedação precisa, o que ajuda a manter a lavadora funcionando de maneira eficiente.', 26.9, 26.9, NULL, 'Home Appliances > Large Household Appliances > Others', 'https://cf.shopee.com.br/file/sg-11134201-7rblo-m644hsq1yq97ec', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1398462025%2F23998201686', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
