INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43721736969', 'Limpador Multiuso Chá Branco Pulverizador 500ml Coperalcool Bacfree', 'Limpador Multiuso Chá Branco Pulverizador 500ml Coperalcool Bacfree Primeiro produto Coperalcool Bacfree com sistema de gatilho anatômico, mais fácil de manusear e aplicar por ser um limpador multissuperfícies, se torna prático em sua aplicação. É a solução perfeita para quem deseja praticidade e eficiência na limpeza do dia a dia. Sua eficácia vai além da limpeza comum, pois oferece um poder bactericida que contribui para a eliminação de germes, garantindo não apenas um ambiente visualmente limpo, mas também seguro e higienizado. Indicação de Uso: - Limpa mais de 20 superfícies, como fórmica, laminado, plástico, madeira, mármore, prataria, alumínio, cerâmica, porcelanato e diversas outras. Cor: Transparente Fragrância: Chá Branco Embalagem: 01 frasco pulverizador de 500ml', 28.42, 28.42, NULL, 'Home & Living > Home Care Supplies > Cleaning Agents', 'https://cf.shopee.com.br/file/sg-11134201-824hy-mf4frw7mi5u557', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F946161700%2F43721736969', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
