INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23498095115', 'Engate Rápido Para Mangueira 5/8" X 3/4" Tramontina', 'Acessórios para Jardinagem Engate Rápido Tramontina 5/8"X3/4" Prático é a solução ideal para otimizar suas tarefas de jardinagem. Fabricado com plástico de alta qualidade, este produto oferece resistência e durabilidade excepcionais. Seu sistema de conexão tipo click facilita a instalação e remoção dos acessórios de irrigação, proporcionando praticidade e eficiência no uso diário. Perfeito para mangueiras de 5/8"X3/4" polegada, o engate rápido garante uma ligação segura e firme. Ele assegura um fluxo de água preciso, essencial para manter seu jardim sempre bem cuidado. Vantagens: Material Resistente: Plástico de alta qualidade que assegura longa vida útil. Conexão Prática: Sistema de engate click para fácil instalação. Irrigação Eficiente: Proporciona fluxo de água preciso. Facilidade de Uso: Economiza tempo e esforço na jardinagem. Uso Versátil: Adequado para jardins, pátios e hortas. Especificações técnicas: Marca: Tramontina Material: Plástico Cor: Cinza e Laranja Tamanho: 5/8"X3/4" Sistema de Conexão: Rosqueado e Tipo Click Dimensões compatíveis com mangueiras de 1/2 polegada Conteúdo da embalagem: Engate rápido Tramontina para mangueira 5/8"X3/4" Garantia: Garantia de 12 meses contra defeitos de fabricação.', 50.9, 34.9, NULL, 'Home & Living > Gardening > Gardening Tools', 'https://cf.shopee.com.br/file/sg-11134201-7rfhh-m40fwdjesem72e', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F23498095115', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20098002779', 'Tomada para Antena de TV Slim Ilumi', 'A Tomada Antena de TV Slim Ilumi é uma solução moderna e prática para conexões de antenas de TV. Com design slim, ela proporciona um acabamento discreto e elegante, ideal para complementar a decoração de ambientes residenciais ou comerciais, oferecendo qualidade e funcionalidade. Vantagens: - Compatível com antenas de TV padrão; - Design slim para um acabamento mais sofisticado e moderno; - Fácil instalação e alta durabilidade; - Integra-se perfeitamente com o sistema modular slim da Ilumi. Características técnicas: Marca: Ilumi Modelo: Tomada de Antena de TV Slim Tipo de Produto: Tomada de Antena Compatibilidade: Sistema Slim Ilumi Garantia: - 3 meses pelo fabricante.', 32.9, 11.9, NULL, 'Home Appliances > Electrical Circuitry & Parts > Electric Sockets & Extension Cords', 'https://cf.shopee.com.br/file/sg-11134201-7rd5x-m6seg37cqfoy22', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F805449066%2F20098002779', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
