INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21357807539', 'Tênis Masculino Casual Couro Ferracini Durável Confort Cinza Marrom Impulse Original 7614-570D', 'ATENÇÃO: ESSE MODELO RECOMENDAMOS COMPRAR UMA NUMERAÇÃO MENOR QUE A HABITUAL, POIS A FORMA É GRANDE! O sneaker masculino Ferracini Impulse Neve é a definição de sofisticação e versatilidade. Com um design totalmente branco, ele se destaca pelo estilo minimalista e clean, ideal para quem busca um calçado que combine com qualquer ocasião. Inspirado na tendência athleisure, o sneaker Ferracini pode ser usado tanto em composições casuais quanto em produções mais refinadas, como alfaiataria e paletós. O solado em caixa alta reforça o toque fashion e garante conforto absoluto para o dia a dia. A cartela cromática branca segue como uma das principais apostas do streetstyle, sendo presença constante nos looks de influenciadores e celebridades. Para quem deseja um calçado moderno, elegante e fácil de combinar, o sneaker Impulse Neve é a opção perfeita. ______________________________________________ FICHA TÉCNICA Cabedal: Couro Palmilha: PU Solado: PU ______________________________________________ - Guia de medidas: (MEDIDAS DA PALMILHA) 37 - 26,5 CM 38 - 27,5 CM 39 - 28 CM 40 - 28,5 CM 41 - 29,5 CM 42 - 30 CM 43 - 30,5 CM 44 - 31 CM Se você possui um sapato com a palmilha removível, o processo é bem simples. Pegue uma régua ou uma fita métrica e meça do calcanhar a ponta da palmilha. Com esse número em mãos, basta comparar com a tabela acima.', 499.9, 499.9, NULL, 'Men Shoes > Sneakers', 'https://cf.shopee.com.br/file/sg-11134201-22100-3w8dfjn965ivb4', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F733934100%2F21357807539', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '21903957142', 'Ajustador De Passos E Elástico De Resistência Lateral Proaction G278', 'Elástico De Resistência Lateral e Ajustador de passos em Látex - Resistência 8 kilos - 5X12X30cm - Preto. Ideal para desenvolver agilidade e força nas pernas. Modelo: G278 Adquira agilidade e força nos músculos de todas as partes da perna, glúteos e membros superiores com o Extensor de resistência Lateral. Elástico extremamente versátil e confortável. Para treinar em casa, na academia ou em qualquer lugar. Com alças confortáveis e fecho em velcro, é indicada para todos os tamanhos de tornozelos, pés, pulsos e mãos. Pode ser usado em ambas as pernas ou preso de um lado por um espaldar ou barra, e do outro lado preso na perna ou nas mãos. Acompanha manual de exercícios. Conteúdo da Embalagem: 1 Ajustador de Passos Proaction G278 Todas as informações divulgadas são de responsabilidade do fabricante/fornecedor. Imagem meramente ilustrativa.', 40.0, 40.0, NULL, 'Sports & Outdoors > Sports & Outdoor Recreation Equipments > Yoga & Pilates', 'https://cf.shopee.com.br/file/cd259002c762d7634ff7adace000ef82', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F429392805%2F21903957142', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
