INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '43026972285', 'Armário de Cozinha Multiuso 4 Portas e Gaveta com Nicho Microondas e Forno Organizador Compacto', 'Cozinha Completa com Balcão e Armário – Funcionalidade e Estilo para Seu Ambiente Renove sua cozinha com um móvel moderno e prático. Conta com 4 portas, 1 gaveta e 1 nicho, proporcionando amplo espaço para organização. A bancada multifuncional permite acomodar eletrodomésticos como micro-ondas ou forno, otimizando o espaço. Fabricado em MDP de alta qualidade, possui pintura UV semi-brilho, garantindo durabilidade e acabamento sofisticado. Os puxadores em PVC são resistentes e elegantes, e os 4 pés facilitam a limpeza e trazem um toque moderno ao ambiente. Dimensões: -Altura: 170 cm -Largura: 60 cm -Profundidade Parte de cima: 27cm -Profundidade Parte de Baixo: 36 cm -Altura do Nicho: 45cm Diferenciais: -Envio imediato pela loja oficial -Frete grátis para todo o país -Fácil montagem e estrutura reforçada -30 dias de garantia -Aproveite e transforme sua cozinha com mais elegância e praticidade!', 441.65, 264.12, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/br-11134207-820me-mqdojh5ppo8y40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1242718651%2F43026972285', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
