INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23297348953', 'Livro O sermão do Monte | John Wesley', 'Após a emocionante experiência de sentir “o coração estranhamente aquecido”, John Wesley ficou encantado com a pregação e o ensino de Jesus no Sermão do Monte e considerou esse Sermão com tanta seriedade que dedicou a vida para seguir seus preceitos. 30% dos sermões doutrinários de Wesley, 13 dos 44, tratam do Sermão do Monte. Estes 13 discursos estão agora à sua disposição. O autor do sermão é o próprio Jesus, revelado aqui Professor, Mestre, Senhor, Filho de Deus e Deus. Não importa como Jesus é chamado ou compreendido, o Sermão do Monte dá provas de seu conhecimento singular, tanto de Deus como do homem. Mesmo os que mais duvidaram dele precisam admitir a genialidade de seu sermão. Detalhes do Produto: Autor: John Wesley Editora: Vida Acabamento: Brochura Dimensões: 16 larg. X 23 alt. Número de páginas: 256', 44.9, 44.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-825bc-mqj9cfqwsj6316', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F23297348953', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22697778612', 'Livro Juntas | Capa Dura | Camila Barros | Midian Lima | Raquel Lima | Gabriela Lopes', 'Livro Juntas | Capa Dura Deus conectou Midian, Camila, Raquel e Gabriela em um só propósito, para que a mensagem que receberam do Senhor também alcance outras mulheres. Cada autora escreveu um capítulo deste livro inspirada pela Palavra de Deus, e você será poderosamente abençoada e edificada através de seus testemunhos e aprendizados. Além disso, será encorajada a crer nas promessas divinas, romper com o passado e avançar em todas as áreas da vida, por meio de atividades práticas e declarações proféticas. A jornada com Cristo deve ser trilhada ao lado de pessoas que nos fortalecerão e nos impulsionarão a viver os sonhos de Deus. Então, não se esqueça: você não está sozinha, pois o Senhor nos chamou para cumprirmos sua missão JUNTAS. Autor: Camila Barros, Midian Lima, Raquel Lima, Gabriela Lopes Editora: Vida Acabamento: Capa Dura Dimensões: 17 cm largura x 23 cm altura Número de páginas: 208', 44.99, 31.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/br-11134207-7r98o-m8dw3eoyx7u9ef', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F217167158%2F22697778612', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22898852098', 'Fogão Itatiaia 5 Bocas Star New', 'O Fogão Star New 5 Bocas é o fogão que irá facilitar ainda mais o seu dia a dia na cozinha. O eletro é ágil no preparo de receitas, tem um forno amplo, é fácil de limpar e também conta com: Puxador em aço com design moderno para maior praticidadee conforto ao abrir a porta do forno. Trempes resistentes para maior estabilidade das panelas, com laterais arredondadas que evitam acúmulo de sujeira. Acendimento automático. Forno amplo com revestimento limpa-fácil para evitar o acúmulo de gordura e sujeira, garantindo mais praticidade para o dia a dia. Manípulos removíveis. O Fogão da Itatiaia é ideal para cozinhas mais compactas que necessitam de um eletro que se adeque ao espaço disponível. Ele também é um produto durável e resistente. Detalhe importante: - A saída de gás está posicionada no lado Direito do fogão, facilitando a instalação em diferentes ambientes. - O consumidor é responsável pela montagem. - As cores podem sofrer alterações dependendo do seu monitor. Características: MODELO: Star New Quantidade de bocas: 5 Acendimento: Automático Forno: Amplo Revestimento do forno: Limpa-fácil Puxador do forno: Aço com design moderno Trempes: Resistentes com laterais arredondadas Manípulos: Removíveis Saída de gás: Lado direito Indicação de uso: Cozinhas compactas Diferenciais: Fácil de limpar, durável e resistente Finalidade: Uso doméstico Dimensões: Altura: 86,3 cm Largura: 76,3 cm Profundidade: 54,9 cm Peso: 22,6 Kg Garantia do Fabricante: 12 meses', 999.0, 969.0, NULL, 'Home Appliances > Kitchen Appliances > Stoves, Hobs & Gas Regulators', 'https://cf.shopee.com.br/file/sg-11134201-824ig-me02zobtkbgl56', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1243712796%2F22898852098', NULL, NULL, '2026-