INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23094455624', 'Mesa Plástica de Apoio com Porta Copos Preta Mor', 'A Mesa Plástica de Apoio com Porta-Copos Preta Mor é perfeita para quem busca uma solução compacta e versátil. Com 51cm de largura, 51cm comprimento e 43cm de altura, foi projetada especificamente para se adequar a espaços menores, proporcionando um apoio conveniente onde quer que você esteja. Produzida nacionalmente, é confeccionada em polipropileno 100% virgem e proteção UV para garantir maior durabilidade. Disponível nas cores preta e branca, se destaca pelo excelente acabamento e qualidade. Pode ser utilizada na beira da praia, junto à piscina, em acampamentos, varandas, restaurantes, hotéis, bares e festas. É fácil de limpar e empilhável, ocupando pouco espaço quando for preciso armazenar várias unidades. Com ela, todo o conforto que você procura estará ao alcance de suas mãos!', 90.0, 90.0, NULL, 'Home & Living > Furniture > Desks & Tables', 'https://cf.shopee.com.br/file/sg-11134201-824j4-mfbbgd0pvll4bf', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1583442620%2F23094455624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18898040456', 'KIT 3 LITROS MOTOCOOL EXPERT HYBRID TECH + MOTUL MOCOOL 500ml', 'KIT 3 LITROS MOTOCOOL EXPERT HYBRID TECH + MOCOOL 50ML MOTOCICLETAS Fluido de arrefecimento MOTUL MOTOCOOL EXPERT -37°C 1L Características: Condição do item: Novo Marca: Motul MPN: 109590 Número de peça: 109590 Número de registro/certificação INMETRO: - OEM: 109590 "MOTUL Motocool Expert é um fluido de arrefecimento, anticongelante e anticorrosivo pronto para usar em sistemas de refrigeração de motocicletas. Baseado em monoetilenoglicol, o Motocool Expert contém aditivos híbridos reforçados contra corrosão adequados para ligas leves de alumínio usadas em projetos de motores de motocicletas." Aditivo de radiador MOTUL MOCOOL 500 ML Características: Código: 107798 Código universal de produto: 3374650270562 Condição do item: Novo Marca: Motul Modelo: Aditivo de radiador MOTUL MOCOOL 500 ML MPN: 107798 Número de registro de producto de ANP: - Peso da unidade: 500 g Tipo de veículo: Motos e quadriciclos "Aditivo de concentrado para melhora de troca térmica para todos os sistemas de arrefecimento de motocicletas, carros, quadriciclos e outros quando for observado superaquecimento ou em condições de corrida para reduzir a temperatura de operação do motor. ATENÇÃO: Alguns regulamentos de competição podem proibir o uso de qualquer produto além de água pura, em caso de dúvida , verifique com a organização oficial da corrida antes de usar o MoCool. A Motul Company não é responsável em caso de desqualificação de corrida ao usar MoCool de forma inadequada. MoCool não fornece qualquer proteção anticongelante. "', 395.35, 355.82, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Automobiles > Filters', 'https://cf.shopee.com.br/file/sg-11134201-7rccj-m67a8gtly15461', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1068060049%2F18898040456', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
