INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23097975265', 'Tinta Maxton Louro Natural 7.0', 'TINTA MAXTON 7.0 LOURO NATURAL + AGUA OXIGENADA Que tal revelar algo que está dentro de você? Um jeito de ser que estava adormecido ou uma personalidade que tem tudo a ver contigo! Você escolhe e Maxton te ajuda a expressar ao mundo o que deseja. Maxton oferece cores intensas e radiantes que te revelam e te dão liberdade para ser mais você. Esse Kit contém: 1 Tintura em Creme + 1 Loção Reveladora + 1 Par de Luvas + 1 Guia Explicativo. Benefícios Qualidade Profissional. Cor Intensa e Brilho Extremo. Uniforme da Raiz às Pontas. Mais Segurança para se Revelar: Com a Tecnologia MaxPlex você atinge o tom que deseja de forma ainda mais segura. MaxPlex preserva a estrutura dos fios enquanto você pinta os cabelos, oferecendo muito mais segurança para você se revelar com Maxton. Revele-se em 30 minutos.', 17.97, 15.9, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rdvn-m1fygfdhl54tb5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1045085918%2F23097975265', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
