INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '58209405525', 'Amstel Puro Malte Cerveja Lager', 'A Amstel é uma cerveja lager puro malte, apreciada em mais de 110 países, perfeita para compartilhar bons momentos. Com receita europeia, ingredientes naturais e sem aditivos, leva o espírito de Amsterdam para o mundo. Seja em festas, churrascos ou em casa, a Amstel é a escolha ideal para quem busca uma cerveja refrescante e saborosa. A coloração dourada e o leve amargor são suas marcas registradas.', 4.49, 4.49, NULL, 'Food & Beverages > Alcoholic Beverages > Beer & Cider', 'https://cf.shopee.com.br/file/sg-11134201-8259k-mqneknreyeiz1a', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1676554932%2F58209405525', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22892816308', 'Creme Para Pentear Leave In Dr Triskle Cicatri 10 100ml', 'A LINHA CICATRI10 age de forma inteligente reconstruindo zonas danificadas e selando as cutículas. Mantém os nutrientes essenciais no interior do fio, protegendo contra novos danos e proporcionando um resultado incrível e saudável. Modo de uso: Aplique na palma da mão a quantidade necessária para o comprimento e espalhe o produto entre os fios. Não enxague. Possui proteção térmica . #html-body [data-pb-style="646BA65FB1863"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA65FB1878"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}', 55.11, 55.11, NULL, 'Beauty > Hair Care > Hair Styling', 'https://cf.shopee.com.br/file/sg-11134201-7rce7-lr3ktgud7jcn98', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F22892816308', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22192992238', 'Cristaleira Ripada Vidro Temperado 100% MDF e Madeira Maciça 180CMX80CM Jb Açaí Branco Pérola', 'A Cristaleira Jb Açaí é a escolha perfeita para quem deseja organizar louças, taças e objetos decorativos com elegância e modernidade. Seu design sofisticado, que une a transparência do vidro à textura do ripado, transforma qualquer sala de jantar ou de estar em um ambiente muito mais refinado. • Design e Acabamento: Apresenta portas e laterais com detalhes ripados de 24mm e acabamento em pintura uv brilhante, proporcionando um visual contemporâneo e de alto padrão. • Estrutura e Estabilidade: Conta com pés e travessas produzidos em madeira maciça, o que confere ao móvel uma base sólida, resistente e com excelente suporte de peso. • Segurança e Exposição: Possui prateleiras, laterais e portas em vidro temperado de 4mm, oferecendo maior resistência a impactos e total visibilidade para suas coleções e cristais. • Capacidade de Organização: Dispõe de seis prateleiras amplas e oito nichos internos estrategicamente distribuídos para facilitar a arrumação de diversos tipos de utensílios. • Dimensões Contextualizadas: Apresenta um porte imponente com 180 cm de altura, 80 cm de largura e 40 cm de profundidade, otimizando o uso do espaço vertical no ambiente. • Qualidade do Material: Construída com painéis de mdf de alta densidade, a estrutura apresenta uma composição compacta e firme, assegurando que o móvel mantenha sua integridade e beleza ao longo do tempo. Acompanha 1 cristaleira, kit ferragens e manual de montagem. Para uma compra certeira: Os itens decorativos das imagens não fazem parte do produto. Confirme se as medidas cabem no seu ambiente, considerando uma pequena folga de até 2 cm para manuseio. Estilo: Moderno Peso (kg): 78 Garantia: 08 Meses Altura (cm): 180 Acabamento: Pintura UV Largura (cm): 80 Possui Pés: Sim Porta Taças: Não Cor da Porta: Off White Possui Adega: Não Possui Nichos: 8 Possui Portas: Sim Tipo de Porta: Bater Altura dos Pés: 15 Possui Gavetas: Não Suporta Até (kg): 22 Possui Espelhos: Não Profundidade (cm): 40 Escala de Brilho: Brilhante Material da Porta: MDF Origem do Produto: Nacional Possui Iluminação: Não Acabamento dos Pés: Pintura Ambiente Principal: Sala de Jantar Material Principal: MDF/MDP Necessita Montagem: Sim Possui Prateleiras: Sim Acabamento da Porta: Pintura UV Sapatas Niveladoras: Não Material da Prateleira: MDF/MDP Acabamento da Prateleira: Pintura UV Complexidade da Montagem: Média: pode ser montado por mais de uma pessoa e/ou necessite de maior conhecimento para montagem Tipo de Puxador da Porta: Externo Escala de Brilho da Porta: Brilhante Peso Máximo por Prateleira: 2 Tipo de Dobradiça/Corrediça da Porta: Aço Marca: JB Bechara Cor: Pérola Cor do Produto: Pérola Itens Inclusos: 1 Mesa Cristaleira, 1 Kit Ferragens e Manual de Montagem. Cor Predominante: Branco Linha ou Coleção: 2024 Quantidade de Prateleiras: 06 Prateleiras Quantidade de Portas: 2 Portas Quantidade de Gavetas: Não Possui', 1257.23, 1028.78, NULL, 'Home & Living > Furniture > Cupboards & Cabinets', 'https://cf.shopee.com.br/file/sg-11134201-820nd-mo1td5mxyl1f40', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22192992238', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '20297420978', 'Tintura Koleston 8.1 Louro Cinza Claro', 'Koleston está a cada dia mais realizando o desejo de muitas mulheres que procuram um cabelo com cor intensa e profunda com resultado deslumbrante. Suas cores são bonitas e atraentes que penetram facilmente no interior do fio sem danificar-los. Além de promover pigmentos no interior dos cabelos, a Koleston promove hidratação e nutrição aos fios garantindo brilho, maciez e um toque suave como você sempre quis. Sua textura cremosa preenchem os fios completamente promovendo uma camada de proteção impedindo que a água penetre no fio inibindo o desbotamento indesejado. Resultado de cores duradouras que não saem facilmente. Modo de Uso 1 - Escolha a cor que você deseja pintar o cabelo. São quatro tons básicos que vão do preto ao loiro, numeradas de 1 a 8. As nuances são as cores como dourado, bege, mate, acobreado, vermelho que tem um número específico para cada marca. 2 - A água oxigenada pode escurecer (Volume 10) ou clarear até 4 tons (Volume 40) por isso compare a dor do seu cabelo natural com a cor da tinta escolhida. Nas caixinhas de tinta Koleston, você pode encontrar qual é o tom do seu cabelo e qual será o resultado quando você pintar os cabelos. 3 - Antes de aplicar a tinta, pegue uma mistura de todos os componentes e passe AM alguma parte do braço. Espere 24 horas até que você tenha certeza que não tenha nenhuma sensibilidade a componentes. Divida os cabelos em cinco partes. Misture o tubo da água oxigenada com o tubo da tinta, até que estejam completamente homogeneizadas. 4 - Aplique o sachê pré-coloração que vem junto no tubo de tinta. Esse sachê faz uma pré-hidratação nos fios e melhora a fixação, prevenindo o desbotamento. Depois, com o cabelo ainda separado em mechas, aplique a tinta da raiz até as pontas, se for a primeira vez que você usa a tintura. Caso seja apenas retoque de raiz, aplique a tinta apenas nesse local. 5 - Deixe a tinta por 40 minutos, se for a primeira tintura, e por 30 minutos se for a segunda tintura. 6 - Se for a primeira tintura, passe um pouco de água fria, deixe por 5 minutos e retire com água corrente. Se for retoque de tinta, passe o resto da tinta em todo o cabelo, deixe por 5 minutos e enxágue em seguida. Não é necessário usar shampoo, aplique apenas o condicionar que vem na embalagem. #html-body [data-pb-style="646BA64646ADE"]{justify-content: Flex-start; display: Flex; flex-direction: Column; background-position: Left top; background-size: Cover; background-repeat: No-repeat; background-attachment: Scroll; border-style: None; border-width: 1px; border-radius: 0px; margin: 0px 0px 10px; padding: 10px;}#html-body [data-pb-style="646BA64646AF3"]{border-style: None; border-width: 1px; border-radius: 0px; margin: 0px; padding: 0px;}#html-body [data-pb-style="646BA64646B02"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B11"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B20"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B2E"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B3C"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B4A"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B58"]{font-weight: 400;}#html-body [data-pb-style="646BA64646B66"]{font-weight: 400;}', 38.47, 38.47, NULL, 'Beauty > Hair Care > Hair Colour', 'https://cf.shopee.com.br/file/sg-11134201-7rbnc-lmgh1uhwrwwp90', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1010974641%2F20297420978', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22193544717', 'Kit C/ 4 Caixas Piso Vinílico em Manta Scandian Home 0,7mm 40m²', 'Kit c/ 4 caixas Piso Vinílico em Manta Scandian Home 0,7mm 40m² Recomendações de uso: Áreas residenciais: quartos, salas, corredores, e outros ambientes comuns, uso interno. Piso com conforto térmico e acústico, antialérgico, resistente a umidade e de muito praticidade na limpeza. Confeccionado em material 100% sintético unindo a versatilidade do PVC ao charme e conforto da madeira. Garantia: 12 Meses Material Principal: PVC Acabamento (Construção e Acabamento): Liso Material Principal Construção e Acabamento: PVC Marca: Scandian Cor do Produto: Nogueira Cor Predominante: Marrom', 974.87, 819.98, NULL, 'Home & Living > Tools & Home Improvement > Roofing & Flooring', 'https://cf.shopee.com.br/file/sg-11134201-7renx-m2ew2h3afscbda', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F855489892%2F22193544717', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '19899253548', 'Kit Cilindro Motor Honda Nx400 Falcon 1999 2000 2001 2002 2003 2004 2005 2006 2007 2008 Kmp Original', 'COMPRANDO NA 🔸PARANÁ AUTO CICLO🔹 VOCÊ TEM O MELHOR PREÇO E ENTREGA RÁPIDA ----SOMOS REVENDEDORES OFICIAIS ---- TEXX - HJC - TXK - KMP - RIK - GP7---- >>>Enviamos sua encomenda em até 24h - Via Shopee Xpress totalmente rastreável e 100% seguro.<<<🚚 [PRODUTOS COM NOTA FISCAL e GARANTIA DE FÁBRICA.] 📄 ✔️ Kit Motor Cilindro Pistão Anéis kmp Completo Nx 400 Falcon 2003 Até 2015 C/ Catalisar Kmp ✔️ Informações técnicas ✅ O kit de motor completo da marca KMP é projetado para ser compatível com a motocicleta Honda NX 400 Falcon, especificamente os modelos fabricados entre os anos de 2003 e 2015 que possuem catalisador. Este kit inclui um cilindro completo, pistão e anéis, entre outros componentes essenciais necessários para a manutenção e restauração do motor da NX 400 Falcon com catalisador. Esses componentes desempenham um papel crucial no sistema de combustão da motocicleta, onde a energia é gerada para mover o veículo. A marca KMP sugere alta qualidade e confiabilidade, contribuindo para o desempenho adequado do motor e a qualidade de condução da motocicleta Honda NX 400 Falcon fabricada durante o período mencionado. É uma parte fundamental para a manutenção adequada e o funcionamento confiável deste modelo específico de motocicleta com catalisador. - Medida do Pino do Pistão: 20 mm Compatível Com: - Honda Nx 400 Falcon C/Catalisador Carburador (1999 Até 2008) - Honda Nx 400 i Falcon C/Catalisador Injetado (2012 Até 2015) Conteúdo da Embalagem: - 01 Cilindro Medida STD - 01 Pistão Kmp C/ Pino e trava - 01 Jogo de Anéis KMP Genuíno - 01 Kit a Junta Garantia - Nossos Produtos Possui 90 Dias de Garantia Contra Defeitos de Fabrica. >-------🔸🏍️🔹--------< • Não nos responsabilizamos pelo mau uso do produto. • Recomendamos que a troca / instalação seja realizada por um profissional qualificado. • Antes de comprar verifique se seu e-mail, endereço e dados estão atualizados no Cadastro, assim manteremos contato com você durante o processo da compra e, evitando eventuais problemas com a entrega do produto. 📍DUVIDAS❓ CHAMA NO CHAT!!!💬 Qualquer dúvida entrar em contato no campo de perguntas para evitar transtornos, temos uma equipe totalmente qualificada a disposição pronta para ajudar. Obrigado!', 789.9, 789.9, NULL, 'Spare Parts and Accessories for Vehicles > Spare Parts for Motorcycles > Engine', 'https://cf.shopee.com.br/file/br-11134207-7r98o-luv821xanxb41f', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1124035980%2F19899253548', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '23198804474', 'Devocional Oração e Arte | Daniel Bota', 'Neste deslumbrante devocional o artista plástico e autor Daniel Bota leva o leitor a um passeio por mais de 30 obras-primas da arte universal, tecendo reflexões bíblicas profundas que englobam seus criadores e inspirações, as mensagens por trás de suas pinceladas, contexto histórico e curiosidades que demonstram que a expressão da arte se conecta com a necessidade que nós temos do maior Artista, o próprio Deus. O Devocional Oração e Arte traz “os temas centrais da vida humana a partir de uma interface pulsante entre a Escritura Sagrada e obras icônicas” (Davi Lago). Com acabamento de luxo primoroso, a experiência de leitura se torna ainda mais instigante e inspiradora. Neste livro você encontrará devocionais inspirados em obras renomadas, tais como: Retirantes – Portinari, O Grito – Edvard Munch, Tempestade no Mar da Galileia – Rembrandt, Noite Estrelada – Van Gogh, A Incredulidade de São Tomé – Caravaggio, O Almoço dos Barqueiros – Renoir, Autorretrato com Colar de Espinhos e Beija-Flor – Frida Kahlo, A Torre de Babel – Pieter Bruegel, O Lago das Ninféias – Monet, Guernica – Picasso, A Visão do Vale de Ossos Secos – Gustave Doré, A Negação de Pedro – Carl Heinrich Bloch, O Três de Maio de 1808 em Madrid – Goya, A Criação de Adão – Michelangelo e Mona Lisa – Leonardo da Vinci. 21X21 CM 144 Páginas', 79.9, 78.99, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-7rdww-mdc00fd9ido7b5', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F23198804474', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
