INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '18360248624', 'O Pastor como Pregador | John MacArthur', 'O Pastor como Pregador fundamenta seu conteúdo na ideia de que “A pregação fiel da Palavra de Deus é o elemento mais importante do ministério pastoral” (John MacArthur). Isso simplesmente porque a Escritura apresenta uma declaração simples que revela a prioridade mais alta de cada pastor: “Prega a Palavra”. Assim, a grandeza dessa responsabilidade requer o melhor de cada pastor. Em O Pastor como Pregador – uma compilação de mensagens poderosas apresentadas na conferência anual para pastores na Grace Community Church – você conhecerá a essência do que cada ministro deve saber; inclui… O Foco e o Propósito da Pregação Bíblica , O Caráter de um Pregador Fiel , As Chaves para uma Pregação Eficaz , Como Pregar no poder do Espírito 16x23cm 252 Páginas', 50.9, 50.9, NULL, 'Books & Magazines > Books > Religion & Philosophy', 'https://cf.shopee.com.br/file/sg-11134201-22110-bmnoxj8siijv58', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F373289765%2F18360248624', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
