INSERT OR REPLACE INTO products (source, external_id, title, description, price, sale_price, discount_pct, category, image_url, affiliate_link, shop_name, rating, updated_at) VALUES ('shopee', '22197685122', 'Travesseiro 80 Penas De Ganso 20 Plumas De Ganso Daune', 'Travesseiro 80 Penas De Ganso 20 Plumas De Ganso Daune Branco Travesseiro Daune reúne tudo o que você precisa para ter suas noites de sono agradáveis. Enchimento com 20 plumas de ganso e 80 penas de ganso, tecido 100 algodão 233 fios e tratamento especial antialérgico. Escolha Daune, você merece todo o conforto na hora de dormir. Medida: 50cm x 70cm Características: - Tecido: 100 algodão 233 fios - Enchimento 20 plumas e 80 penas de ganso - Nível de conforto médio - Não é impermeável - Com tratamento antiácaro e antifungo - Pode ser feito lavagem em maquina, porém deve ser utilizado secadora até que o enchimento esteja complemente seco - Embalagem capa cristal com zíper - Garantia 90 dias AVISO: Esclarecemos que a OPÇÃO MÓVEIS se responsabilizará pela entrega dos produtos adquiridos até a porta de entrada ou portaria do endereço indicado, ou seja: é de total responsabilidade do cliente a montagem, desmontagem e instalação do produto adquirido. Para evitar futuros desagrados ou imprevistos com a entrega, também é necessário que o cliente confira as dimensões do produto escolhido, antes de finalizar a compra, devendo certificar-se de que a mercadoria passará normalmente por elevador, porta, escada e corredor.', 116.9, 116.9, NULL, 'Home & Living > Bedding > Pillows', 'https://cf.shopee.com.br/file/sg-11134201-7rdxu-ly5buf9oj964c8', 'https://shope.ee/an_redir?origin_link=https%3A%2F%2Fshopee.com.br%2Fproduct%2F1215229492%2F22197685122', NULL, NULL, '2026-07-28T02:11:31.708458+00:00');
